INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eec24bad-a2ac-4d35-892d-ad7f3311656f', '獻衷心', '獻衷心', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["繡鴛鴦帳暖，畫孔雀屏欹。","人悄悄，月明時。","想昔年歡笑，恨今日分離。","銀釭背，銅漏永，阻佳期。","小爐煙細，虛閣簾垂。","幾多心事，暗地思惟。","被嬌娥牽役，魂夢如癡。","金閨裏，山枕上，始應知。"]', '["繡鴛鴦帳暖，畫孔雀屏欹。","人悄悄，月明时。","想昔年歡笑，恨今日分離。","銀釭背，銅漏永，阻佳期。","小爐煙細，虛閣簾垂。","幾多心事，暗地思惟。","被嬌娥牽役，魂梦如癡。","金閨裏，山枕上，始應知。"]', '诗', 'shi', '', NULL, '獻衷心 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b339f77-31f9-438c-b15a-711c5e2f16d9', '女冠子 一', '女冠子 一', '0887ab34-a3b0-43a0-8aee-95d53a2da2c4', '唐', '["鳳樓琪樹，惆悵劉郎一去，正春深。","洞裏愁空結，人間信莫尋。","竹疎齋殿迥，松密醮壇陰。","倚雲低首望，可知心。"]', '["鳳楼琪樹，惆悵劉郎一去，正春深。","洞裏愁空結，人间信莫尋。","竹疎斋殿迥，松密醮壇陰。","倚云低首望，可知心。"]', '诗', 'shi', '', NULL, '女冠子 一 鹿虔扆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41ea050a-6f30-4219-bf8d-f3fa4f5bdd45', '女冠子 二', '女冠子 二', '0887ab34-a3b0-43a0-8aee-95d53a2da2c4', '唐', '["步虛壇上，絳節霓旌相向，引真仙。","玉佩搖蟾影，金爐嫋麝煙。","露濃霜簡濕，風緊羽衣偏。","欲留難得住，却歸天。"]', '["步虛壇上，絳節霓旌相向，引真仙。","玉佩搖蟾影，金爐嫋麝煙。","露濃霜簡濕，风緊羽衣偏。","欲留难得住，却归天。"]', '诗', 'shi', '', NULL, '女冠子 二 鹿虔扆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d9749e5-d85f-4530-a9aa-7f2b11e0e82a', '思越人', '思越人', '0887ab34-a3b0-43a0-8aee-95d53a2da2c4', '唐', '["翠屏欹，銀燭背，漏殘清夜迢迢。","雙帶繡窠盤錦薦，淚侵花暗香銷。","珊瑚枕膩鴉鬟亂，玉纖慵整雲散。","苦是適來新夢見，離腸爭不千斷。"]', '["翠屏欹，銀燭背，漏殘清夜迢迢。","雙带繡窠盤錦薦，泪侵花暗香銷。","珊瑚枕膩鴉鬟亂，玉纖慵整云散。","苦是適来新梦见，離腸爭不千斷。"]', '诗', 'shi', '', NULL, '思越人 鹿虔扆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('631b54fc-9c65-4c8f-a0a8-20f8d37a2ecc', '虞美人', '虞美人', '0887ab34-a3b0-43a0-8aee-95d53a2da2c4', '唐', '["卷荷香澹浮煙渚，綠嫩擎新雨。","瑣窗疎透曉風清，象牀珍簟冷光輕，水文平。","九疑黛色屏斜掩，枕上眉心歛。","不堪相望病將成，鈿昏檀粉淚縱橫，不勝情。"]', '["卷荷香澹浮煙渚，綠嫩擎新雨。","瑣窗疎透晓风清，象牀珍簟冷光轻，水文平。","九疑黛色屏斜掩，枕上眉心歛。","不堪相望病將成，鈿昏檀粉泪縱橫，不勝情。"]', '诗', 'shi', '', NULL, '虞美人 鹿虔扆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e78f122-3f5c-49ac-a2ed-9c4252a6aace', '臨江仙 一', '臨江仙 一', '0887ab34-a3b0-43a0-8aee-95d53a2da2c4', '唐', '["金鎖重門荒苑靜，綺窗愁對秋空。","翠華一去寂無蹤。","玉樓歌吹，聲斷已隨風。","煙月不知人事改，夜闌還照深宮。","藕花相向野塘中。","暗傷亡國，清露泣香紅。"]', '["金鎖重门荒苑静，綺窗愁对秋空。","翠华一去寂無蹤。","玉楼歌吹，声斷已隨风。","煙月不知人事改，夜闌還照深宮。","藕花相向野塘中。","暗傷亡国，清露泣香紅。"]', '诗', 'shi', '', NULL, '臨江仙 一 鹿虔扆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b810c924-5ff4-4c34-a47a-ace77ea15df0', '臨江仙 二', '臨江仙 二', '0887ab34-a3b0-43a0-8aee-95d53a2da2c4', '唐', '["無賴曉鶯驚夢斷，起來殘酒初醒。","映窗絲柳嫋煙青。","翠簾慵卷，約砌杏花零。","一自玉郎遊冶去，蓮凋月慘儀形。","暮天微雨灑閑庭。","手挼裙帶，無語倚雲屏。"]', '["無賴晓鶯驚梦斷，起来殘酒初醒。","映窗絲柳嫋煙青。","翠簾慵卷，約砌杏花零。","一自玉郎游冶去，蓮凋月慘儀形。","暮天微雨灑闲庭。","手挼裙带，無語倚云屏。"]', '诗', 'shi', '', NULL, '臨江仙 二 鹿虔扆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deccec6b-00f8-41d8-9811-4ab1b67bdc74', '訴衷情 一', '訴衷情 一', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["高歌宴罷月初盈，詩情引恨情。","煙露冷，水流輕，思想夢難成。","羅帳嫋香平，恨頻生。","思君無計睡還醒，隔層城。"]', '["高歌宴罷月初盈，诗情引恨情。","煙露冷，水流轻，思想梦难成。","羅帳嫋香平，恨頻生。","思君無計睡還醒，隔層城。"]', '诗', 'shi', '', NULL, '訴衷情 一 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e90e32e-a815-421f-bfd9-cd98c4005cfe', '訴衷情 二', '訴衷情 二', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["春深花簇小樓臺，風飄錦繡開。","新睡覺，步香階，山枕印紅顋。","鬢亂墜金釵，語檀偎。","臨行執手重重屬，幾千回。"]', '["春深花簇小楼台，风飄錦繡开。","新睡覺，步香階，山枕印紅顋。","鬢亂墜金釵，語檀偎。","臨行執手重重屬，幾千回。"]', '诗', 'shi', '', NULL, '訴衷情 二 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96ee4309-df9c-4dc7-af11-9b61ae5678c8', '訴衷情 三', '訴衷情 三', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["銀漢雲情玉漏長，蛩聲悄畫堂。","筠簟冷，碧窗涼，紅蠟淚飄香。","皓月瀉寒光，割人腸。","那堪獨自步池塘，對鴛鴦。"]', '["銀漢云情玉漏长，蛩声悄畫堂。","筠簟冷，碧窗涼，紅蠟泪飄香。","皓月瀉寒光，割人腸。","那堪独自步池塘，对鴛鴦。"]', '诗', 'shi', '', NULL, '訴衷情 三 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a65762f-839e-4d77-96a3-c8d1fea01c20', '訴衷情 四', '訴衷情 四', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["金風輕透碧窗紗，銀釭燄影斜。","欹枕臥，恨何賒，山掩小屏霞。","雲雨別吳娃，想容華。","夢成幾度遶天涯，到君家。"]', '["金风轻透碧窗紗，銀釭燄影斜。","欹枕臥，恨何賒，山掩小屏霞。","云雨別吳娃，想容华。","梦成幾度遶天涯，到君家。"]', '诗', 'shi', '', NULL, '訴衷情 四 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1488d95e-42f0-42a9-80eb-4891aa911537', '訴衷情 五', '訴衷情 五', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["春情滿眼臉紅消，嬌妒索人饒。","星靨小，玉璫搖，幾共醉春朝。","別後憶纖腰，夢魂勞。","如今風葉又蕭蕭，恨迢迢。"]', '["春情满眼臉紅消，嬌妒索人饒。","星靨小，玉璫搖，幾共醉春朝。","別後憶纖腰，梦魂勞。","如今风葉又蕭蕭，恨迢迢。"]', '诗', 'shi', '', NULL, '訴衷情 五 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ee94cd-9eb1-4fbb-a654-aaaba6707384', '生查子 一', '生查子 一', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["煙雨晚晴天，零落花無語。","難話此時心，梁燕雙來去。","琴韻對薰風，有恨和情撫。","腸斷斷弦頻，淚滴黃金縷。"]', '["煙雨晚晴天，零落花無語。","难話此时心，梁燕雙来去。","琴韻对薰风，有恨和情撫。","腸斷斷弦頻，泪滴黄金縷。"]', '诗', 'shi', '', NULL, '生查子 一 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb48dd5f-2935-4b5a-aee2-e06ca1beb37c', '生查子 二', '生查子 二', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["寂寞畫堂空，深夜垂羅幕。","燈暗錦屏欹，月冷珠簾薄。","愁恨夢難成，何處貪歡樂。","看看又春來，還是長蕭索。"]', '["寂寞畫堂空，深夜垂羅幕。","灯暗錦屏欹，月冷珠簾薄。","愁恨梦难成，何处貪歡乐。","看看又春来，還是长蕭索。"]', '诗', 'shi', '', NULL, '生查子 二 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ec4301-e7e4-4722-be6e-5493e8b520f9', '生查子 三', '生查子 三', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["離別又經年，獨對芳菲景。","嫁得薄情夫，長抱相思病。","花紅柳綠間晴空，蝶舞雙雙影。","羞看繡羅衣，爲有金鸞竝。"]', '["離別又經年，独对芳菲景。","嫁得薄情夫，长抱相思病。","花紅柳綠间晴空，蝶舞雙雙影。","羞看繡羅衣，爲有金鸾竝。"]', '诗', 'shi', '', NULL, '生查子 三 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4b8184b-df25-46c3-b3ac-ee7cb88577f9', '菩薩蠻 一', '菩薩蠻 一', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["羅裾薄薄秋波染，眉間畫得山兩點。","相見綺筵時，深情暗共知。","翠翹雲鬢動，歛態彈金鳳。","宴罷入蘭房，邀人解佩璫。"]', '["羅裾薄薄秋波染，眉间畫得山兩点。","相见綺筵时，深情暗共知。","翠翹云鬢动，歛態彈金鳳。","宴罷入蘭房，邀人解佩璫。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aae508b-b086-4443-bddc-53bbacb8c94c', '菩薩蠻 二', '菩薩蠻 二', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["羅衣隱約金泥畫，玳筵一曲當秋夜。","聲顫覷人嬌，[雲]鬟嫋翠翹。","酒醺紅玉輭，眉翠秋山遠。","繡幌麝煙沈，誰人知兩心。"]', '["羅衣隐約金泥畫，玳筵一曲當秋夜。","声顫覷人嬌，[云]鬟嫋翠翹。","酒醺紅玉輭，眉翠秋山远。","繡幌麝煙沈，誰人知兩心。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4438aee-f218-40fc-babf-fd4d11e12a98', '菩薩蠻 三', '菩薩蠻 三', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["玉容光照菱花影，沈沈臉上秋波冷。","白雪一聲新，雕梁起暗塵。","寶釵搖翡翠，香惹芙蓉醉。","攜手入鴛衾，誰人知此心。"]', '["玉容光照菱花影，沈沈臉上秋波冷。","白雪一声新，雕梁起暗塵。","寶釵搖翡翠，香惹芙蓉醉。","携手入鴛衾，誰人知此心。"]', '诗', 'shi', '', NULL, '菩薩蠻 三 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b6ee9e-3e1a-41f4-b978-f26808ef46ac', '漁歌子', '漁歌子', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["柳如眉，雲似髮，鮫綃霧縠籠香雪。","夢魂驚，鐘漏歇，窗外曉鶯殘月。","幾多情，無處說，落花飛絮清明節。","少年郎，容易別，一去音書斷絕。"]', '["柳如眉，云似髮，鮫綃霧縠籠香雪。","梦魂驚，鐘漏歇，窗外晓鶯殘月。","幾多情，無处说，落花飞絮清明節。","少年郎，容易別，一去音书斷絕。"]', '诗', 'shi', '', NULL, '漁歌子 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a33b96d-d322-465c-8221-949e7386bea7', '滿宮花 一', '满宮花 一', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["雪霏霏，風凜凜。","玉郎何處狂飲，醉時想得縱風流，羅帳香幃鴛寢。","春朝秋夜思君甚，愁見繡屏孤枕。","少年何事負初心，淚滴縷金雙袵。"]', '["雪霏霏，风凜凜。","玉郎何处狂饮，醉时想得縱风流，羅帳香幃鴛寢。","春朝秋夜思君甚，愁见繡屏孤枕。","少年何事負初心，泪滴縷金雙袵。"]', '诗', 'shi', '', NULL, '滿宮花 一 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acdc2c06-2f64-4b7c-818b-5fb211927587', '滿宮花 二', '满宮花 二', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["寒夜長，更漏永。","愁見透簾月影，王孫何處不歸來，應在倡樓酩酊。","金鴨無香羅帳冷，羞更雙鸞交頸。","夢中幾度見兒夫，不忍駡伊薄倖。"]', '["寒夜长，更漏永。","愁见透簾月影，王孫何处不归来，應在倡楼酩酊。","金鴨無香羅帳冷，羞更雙鸾交頸。","梦中幾度见兒夫，不忍駡伊薄倖。"]', '诗', 'shi', '', NULL, '滿宮花 二 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93000ffd-2e21-416c-adf9-86d3ec51cb54', '謁金門 一', '謁金门 一', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["煙水闊，人值清明時節。","雨細花零鶯語切，愁腸千萬結。","鴈去音徽斷絕，有恨欲憑誰說。","無事傷心猶不徹，春時容易別。"]', '["煙水闊，人值清明时節。","雨細花零鶯語切，愁腸千万結。","鴈去音徽斷絕，有恨欲憑誰说。","無事傷心猶不徹，春时容易別。"]', '诗', 'shi', '', NULL, '謁金門 一 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f3ca39-30b0-488e-9e8b-cd454c7ebbd1', '謁金門 二', '謁金门 二', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["春欲半，堆砌落花千片。","早是潘郎長不見，忍聽雙語燕。","飛絮晴空颺遠，風送誰家弦管。","愁倚畫屏凡事嬾，淚霑金縷線。"]', '["春欲半，堆砌落花千片。","早是潘郎长不见，忍听雙語燕。","飞絮晴空颺远，风送誰家弦管。","愁倚畫屏凡事嬾，泪霑金縷線。"]', '诗', 'shi', '', NULL, '謁金門 二 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6643378c-dd0f-4597-9a46-f407ca75a574', '謁金門 三', '謁金门 三', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["長思憶，思憶佳辰輕擲。","霜月透簾澄夜色，小屏山凝碧。","恨恨君何太極，記得嬌嬈無力。","獨坐思量愁似織，斷腸煙水隔。"]', '["长思憶，思憶佳辰轻擲。","霜月透簾澄夜色，小屏山凝碧。","恨恨君何太極，記得嬌嬈無力。","独坐思量愁似织，斷腸煙水隔。"]', '诗', 'shi', '', NULL, '謁金門 三 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd98291d-64a8-44f4-b6aa-cf1af22e40eb', '木蘭花', '木蘭花', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["小芙蓉，香旖旎，碧玉堂深清似水。","閉寶匣，掩金鋪，倚屏拖袖愁如醉。","遲遲好景煙花媚，曲渚鴛鴦眠錦翅。","凝然愁望靜相思，一雙笑靨嚬香蘂。"]', '["小芙蓉，香旖旎，碧玉堂深清似水。","閉寶匣，掩金鋪，倚屏拖袖愁如醉。","遲遲好景煙花媚，曲渚鴛鴦眠錦翅。","凝然愁望静相思，一雙笑靨嚬香蘂。"]', '诗', 'shi', '', NULL, '木蘭花 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('562317fd-861c-4d45-b792-9836b1164e89', '玉樓春 一', '玉楼春 一', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["寂寂畫堂梁上燕，高卷翠簾橫數扇。","一庭春色惱人來，滿地落花紅幾片。","愁倚錦屏低雪面，淚滴繡羅金縷線。","好天涼月盡傷心，爲是玉郎長不見。"]', '["寂寂畫堂梁上燕，高卷翠簾橫數扇。","一庭春色惱人来，满地落花紅幾片。","愁倚錦屏低雪面，泪滴繡羅金縷線。","好天涼月尽傷心，爲是玉郎长不见。"]', '诗', 'shi', '', NULL, '玉樓春 一 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f39f195d-09e1-4e67-b30d-6191162cdf9a', '玉樓春 二', '玉楼春 二', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["輕歛翠蛾呈皓齒，鶯轉一枝花影裏。","聲聲清迥遏行雲，寂寂畫梁塵暗起。","玉斝滿斟情未已，促坐王孫公子醉。","春風筵上貫珠勻，豔色韶顏嬌旖旎。"]', '["轻歛翠蛾呈皓齒，鶯轉一枝花影裏。","声声清迥遏行云，寂寂畫梁塵暗起。","玉斝满斟情未已，促坐王孫公子醉。","春风筵上貫珠勻，豔色韶顏嬌旖旎。"]', '诗', 'shi', '', NULL, '玉樓春 二 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63f5c3ae-a990-4fe5-be7f-164cc8011b33', '黃鍾樂', '黄鍾乐', 'bdd2a575-b5b7-45a2-8e5b-3c8ecd137650', '唐', '["池塘煙暖草萋萋，惆悵閑宵含恨。","愁坐思堪迷，遙想玉人情事遠，音容渾似隔桃溪。","偏記同歡秋月低，簾外論心花畔。","和醉暗相攜，何事春來君不見，夢魂長在錦江西。"]', '["池塘煙暖草萋萋，惆悵闲宵含恨。","愁坐思堪迷，遙想玉人情事远，音容渾似隔桃溪。","偏記同歡秋月低，簾外論心花畔。","和醉暗相携，何事春来君不见，梦魂长在錦江西。"]', '诗', 'shi', '', NULL, '黃鍾樂 魏承班 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18eef17d-1f32-4682-9438-19a6e46db5d3', '江城子', '江城子', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["帬拖碧，步飄香，纖腰束素長。","鬢雲光，拂面瓏璁，膩玉碎凝妝。","寶柱秦箏彈向晚，弦促雁，更思量。"]', '["帬拖碧，步飄香，纖腰束素长。","鬢云光，拂面瓏璁，膩玉碎凝妝。","寶柱秦箏彈向晚，弦促雁，更思量。"]', '诗', 'shi', '', NULL, '江城子 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('827aac15-b44e-4db1-a265-4c9607e3fdf9', '何滿子', '何满子', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["雲雨常陪勝會，笙歌慣逐閑遊。","錦里風光應占，玉鞭金勒驊騮。","戴月潛穿深曲，和香醉脫輕裘。","方喜正同鴛帳，又言將往皇州。","每憶良宵公子伴，夢魂長挂紅樓。","欲表傷離情味，丁香結在心頭。"]', '["云雨常陪勝會，笙歌慣逐闲游。","錦里风光應占，玉鞭金勒驊騮。","戴月潛穿深曲，和香醉脫轻裘。","方喜正同鴛帳，又言將往皇州。","每憶良宵公子伴，梦魂长挂紅楼。","欲表傷離情味，丁香結在心头。"]', '诗', 'shi', '', NULL, '何滿子 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2786042e-1d15-4250-8589-afc625324854', '醉公子', '醉公子', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["暮煙籠蘚砌，戟門猶未閉。","盡日醉尋春，歸來月滿身。","離鞍偎繡袂，墜巾花亂綴。","何處惱佳人，檀痕衣上新。"]', '["暮煙籠蘚砌，戟门猶未閉。","尽日醉尋春，归来月满身。","離鞍偎繡袂，墜巾花亂綴。","何处惱佳人，檀痕衣上新。"]', '诗', 'shi', '', NULL, '醉公子 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8522f620-042d-49ba-90ae-85f66484752f', '女冠子', '女冠子', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["雙成伴侶，去去不知何處，有佳期。","霞帔金絲薄，花冠玉葉危。","嬾乘丹鳳子，學跨小龍兒。","叵耐天風緊，挫腰肢。"]', '["雙成伴侶，去去不知何处，有佳期。","霞帔金絲薄，花冠玉葉危。","嬾乘丹鳳子，学跨小龙兒。","叵耐天风緊，挫腰肢。"]', '诗', 'shi', '', NULL, '女冠子 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d204429-cef6-48da-830e-1387a3da29b9', '菩薩蠻 一', '菩薩蠻 一', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["隴雲暗合秋天白，俯窗獨坐窺煙陌。","樓際角重吹，黃昏方醉歸。","荒唐難共語，明日還應去。","上馬出門時，金鞭莫與伊。"]', '["隴云暗合秋天白，俯窗独坐窺煙陌。","楼際角重吹，黄昏方醉归。","荒唐难共語，明日還應去。","上马出门时，金鞭莫與伊。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08a31151-6a4a-4fd3-a7cd-ffd0ba7cfdfc', '菩薩蠻 二', '菩薩蠻 二', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["嗚嗚曉角調如語，畫樓三會喧雷鼓。","枕上夢方殘，月光鋪水寒。","蛾眉應歛翠，咫尺同千里。","宿酒未全消，滿懷離恨饒。"]', '["嗚嗚晓角調如語，畫楼三會喧雷鼓。","枕上梦方殘，月光鋪水寒。","蛾眉應歛翠，咫尺同千里。","宿酒未全消，满懷離恨饒。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07afe4a4-b78c-446a-91cb-c70043879ea8', '菩薩蠻 三', '菩薩蠻 三', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["錦茵閑襯丁香枕，銀釭燼落猶慵寢。","顒坐遍紅爐，誰知情緒孤。","少年狂蕩慣，花曲長牽絆。","去便不歸來，空教駿馬回。"]', '["錦茵闲襯丁香枕，銀釭燼落猶慵寢。","顒坐遍紅爐，誰知情緒孤。","少年狂蕩慣，花曲长牽絆。","去便不归来，空教駿马回。"]', '诗', 'shi', '', NULL, '菩薩蠻 三 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed875b3e-f772-4ea2-a040-a2f9dc2a8aaa', '杏園芳', '杏园芳', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["嚴妝嫩臉花明，教人見了關情。","含羞舉步越羅輕，稱娉婷。","終朝咫尺窺香閣，迢遙似隔層城。","何時休遣夢相縈，入雲屏。"]', '["嚴妝嫩臉花明，教人见了关情。","含羞舉步越羅轻，稱娉婷。","終朝咫尺窺香閣，迢遙似隔層城。","何时休遣梦相縈，入云屏。"]', '诗', 'shi', '', NULL, '杏園芳 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a5e0894-ee35-4835-8ba1-e6569f6dba48', '清平樂 一', '清平乐 一', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["偎紅歛翠，盡日思閑事。","髻滑鳳皇釵欲墜，雨打梨花滿地。","繡衣獨倚闌干，玉容似怯春寒。","應待少年公子，鴛幃深處同歡。"]', '["偎紅歛翠，尽日思闲事。","髻滑鳳皇釵欲墜，雨打梨花满地。","繡衣独倚闌干，玉容似怯春寒。","應待少年公子，鴛幃深处同歡。"]', '诗', 'shi', '', NULL, '清平樂 一 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82ed652-75c6-45c1-a0d3-844f37ab3ffd', '清平樂 二', '清平乐 二', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["芳年妙妓，淡拂鉛華翠。","輕笑自然生百媚，爭那尊前人意。","酒傾琥珀杯時，更堪能唱新詞。","賺得王孫狂處，斷腸一搦腰肢。"]', '["芳年妙妓，淡拂鉛华翠。","轻笑自然生百媚，爭那尊前人意。","酒傾琥珀杯时，更堪能唱新词。","賺得王孫狂处，斷腸一搦腰肢。"]', '诗', 'shi', '', NULL, '清平樂 二 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ac63601-68b4-49bf-94f3-d0151da7303b', '滿宮花', '满宮花', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["月沈沈，人悄悄，一炷後庭香嫋。","風流帝子不歸來，滿地禁花慵掃。","離恨多，相見少，何處醉迷三島。","漏清宮樹子規啼，愁鎖碧窗春曉。"]', '["月沈沈，人悄悄，一炷後庭香嫋。","风流帝子不归来，满地禁花慵掃。","離恨多，相见少，何处醉迷三島。","漏清宮樹子規啼，愁鎖碧窗春晓。"]', '诗', 'shi', '', NULL, '滿宮花 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20d65124-64ea-4169-a025-9e3994466c13', '臨江仙 一', '臨江仙 一', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["一番荷芰生池沼，檻前風送馨香。","昔年於此伴蕭娘。","相偎佇立，牽惹敘衷腸。","時逞笑容無限態，還如菡萏爭芳。","別來虛遣思悠颺。","慵窺往事，金鎖小蘭房。"]', '["一番荷芰生池沼，檻前风送馨香。","昔年於此伴蕭娘。","相偎佇立，牽惹敘衷腸。","时逞笑容無限態，還如菡萏爭芳。","別来虛遣思悠颺。","慵窺往事，金鎖小蘭房。"]', '诗', 'shi', '', NULL, '臨江仙 一 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77082434-76ea-40ee-8379-171b09d1e12b', '臨江仙 二', '臨江仙 二', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["深秋寒夜銀河靜，月明深院中庭。","西窗幽夢等閑成。","逡巡覺後，特地恨難平。","紅燭半條殘焰短，[依]稀暗背銀屏。","枕前何事最傷情。","梧桐葉上，點點露珠零。"]', '["深秋寒夜銀河静，月明深院中庭。","西窗幽梦等闲成。","逡巡覺後，特地恨难平。","紅燭半條殘焰短，[依]稀暗背銀屏。","枕前何事最傷情。","梧桐葉上，点点露珠零。"]', '诗', 'shi', '', NULL, '臨江仙 二 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f52f0ed-26fc-4194-bff7-f4aa1d632255', '撥櫂子 一', '撥櫂子 一', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["風切切，深秋月。","十朵芙蓉繁豔歇，小檻細腰無力。","空贏得，目斷魂飛何處說。","寸心恰似丁香結，看看瘦盡胸前雪。","偏挂恨，少年拋擲。","羞覩見，繡被堆紅閑不徹。"]', '["风切切，深秋月。","十朵芙蓉繁豔歇，小檻細腰無力。","空贏得，目斷魂飞何处说。","寸心恰似丁香結，看看瘦尽胸前雪。","偏挂恨，少年拋擲。","羞覩见，繡被堆紅闲不徹。"]', '诗', 'shi', '', NULL, '撥櫂子 一 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8df17e20-db30-4af9-80cb-0ce7056d2b2a', '撥櫂子 二', '撥櫂子 二', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["丹臉膩，雙靨媚。","冠子縷金裝翡翠，將一朵，瓊花堪比。","窠窠繡，鸞鳳衣裳香窣地。","銀臺蠟燭滴紅淚，醁酒勸人教半醉。","簾幕外，月華如水。","特地向，寶帳顛狂不肯睡。"]', '["丹臉膩，雙靨媚。","冠子縷金裝翡翠，將一朵，瓊花堪比。","窠窠繡，鸾鳳衣裳香窣地。","銀台蠟燭滴紅泪，醁酒勸人教半醉。","簾幕外，月华如水。","特地向，寶帳顛狂不肯睡。"]', '诗', 'shi', '', NULL, '撥櫂子 二 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a03b4eb-b0ea-4720-a192-ab61ac1be495', '秋夜月', '秋夜月', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["三秋佳節，罥晴空，凝碎露，茱萸千結。","菊蘂和煙輕撚，酒浮金屑。","徵雲雨，調絲竹，此時難輟。","歡極，一片豔歌聲揭。","黃昏慵別，炷沈煙，熏繡被，翠帷同歇。","醉竝鴛鴦雙枕，煖偎春雪。","語丁寧，情委曲，論心正切。","夜深，窗透數條斜月。"]', '["三秋佳節，罥晴空，凝碎露，茱萸千結。","菊蘂和煙轻撚，酒浮金屑。","徵云雨，調絲竹，此时难輟。","歡極，一片豔歌声揭。","黄昏慵別，炷沈煙，熏繡被，翠帷同歇。","醉竝鴛鴦雙枕，煖偎春雪。","語丁寧，情委曲，論心正切。","夜深，窗透數條斜月。"]', '诗', 'shi', '', NULL, '秋夜月 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ec1eb0-934a-4cdc-899c-03d4d4ecf2e0', '金浮圖', '金浮圖', '77f61596-1053-454e-9983-39a9d07c882d', '唐', '["繁華地，王孫富貴。","玳瑁筵開，下朝無事。","壓紅茵，鳳舞黃金翅。","玉立纖腰，一片揭天歌吹。","滿目綺羅珠翠，和風淡蕩，偷散沈檀氣。","堪判醉，韶光正媚。","折盡牡丹，豔迷人意。","金張許史應難比，貪戀歡娛，不覺金烏墜。","還惜會難別易，金船更勸，勒住花驄轡。"]', '["繁华地，王孫富貴。","玳瑁筵开，下朝無事。","壓紅茵，鳳舞黄金翅。","玉立纖腰，一片揭天歌吹。","满目綺羅珠翠，和风淡蕩，偷散沈檀氣。","堪判醉，韶光正媚。","折尽牡丹，豔迷人意。","金張許史應难比，貪戀歡娛，不覺金烏墜。","還惜會难別易，金船更勸，勒住花驄轡。"]', '诗', 'shi', '', NULL, '金浮圖 尹鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43b26bff-11ff-4e3e-af16-2dab4773e1a5', '定西番', '定西番', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["蒼翠濃陰滿院，鶯對語。","蝶交飛，戲薔薇。","斜日倚闌風好，餘香出繡衣。","未得玉郎消息，幾時歸。"]', '["蒼翠濃陰满院，鶯对語。","蝶交飞，戲薔薇。","斜日倚闌风好，餘香出繡衣。","未得玉郎消息，幾时归。"]', '诗', 'shi', '', NULL, '定西番 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25eaed0e-c778-453d-9bf1-c4aa567549a0', '何滿子 一', '何满子 一', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["寂寞芳菲暗度，歲華如箭堪驚。","緬想舊歡多少事，轉添春思難平。","曲檻絲垂金柳，小窗弦斷銀箏。","深院空聞燕語，滿園閑落花輕。","一片相思休不得，忍教長日愁生。","誰見夕陽孤夢，覺來無限傷情。"]', '["寂寞芳菲暗度，歲华如箭堪驚。","緬想旧歡多少事，轉添春思难平。","曲檻絲垂金柳，小窗弦斷銀箏。","深院空闻燕語，满园闲落花轻。","一片相思休不得，忍教长日愁生。","誰见夕陽孤梦，覺来無限傷情。"]', '诗', 'shi', '', NULL, '何滿子 一 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61f4f62d-de38-4dcf-b52c-8bd4e627d5d4', '何滿子 二', '何满子 二', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["無語殘妝澹薄，含羞嚲袂輕盈。","幾度香閨眠過曉，綺窗疎日微明。","雲母帳中偷惜，水精枕上初驚。","笑靨嫩疑花拆，愁眉翠歛山橫。","相望只教添悵恨，整鬟時見纖瓊。","獨倚朱扉閑立，誰知別有深情。"]', '["無語殘妝澹薄，含羞嚲袂轻盈。","幾度香閨眠過晓，綺窗疎日微明。","云母帳中偷惜，水精枕上初驚。","笑靨嫩疑花拆，愁眉翠歛山橫。","相望只教添悵恨，整鬟时见纖瓊。","独倚朱扉闲立，誰知別有深情。"]', '诗', 'shi', '', NULL, '何滿子 二 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e04a599-362c-4639-8bef-1d401fd6fc9d', '女冠子 一', '女冠子 一', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["碧桃紅杏，遲日媚籠光影，綵霞深。","香暖熏鶯語，風清引鶴音。","翠鬟冠玉葉，霓袖捧瑤琴。","應共吹簫侶，暗相尋。"]', '["碧桃紅杏，遲日媚籠光影，綵霞深。","香暖熏鶯語，风清引鹤音。","翠鬟冠玉葉，霓袖捧瑤琴。","應共吹簫侶，暗相尋。"]', '诗', 'shi', '', NULL, '女冠子 一 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b30dcc07-35be-4966-a86c-d31195dbdfe0', '女冠子 二', '女冠子 二', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["修蛾慢臉，不語檀心一點，小山妝。","蟬鬢低含綠，羅衣澹拂黃。","[悶]來深院裏，閑步落花傍。","纖手輕輕整，玉爐香。"]', '["修蛾慢臉，不語檀心一点，小山妝。","蟬鬢低含綠，羅衣澹拂黄。","[悶]来深院裏，闲步落花傍。","纖手轻轻整，玉爐香。"]', '诗', 'shi', '', NULL, '女冠子 二 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ee9f89-3b5b-4d7f-b953-deb35d7c450a', '酒泉子 一', '酒泉子 一', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["閑臥繡幃，慵想萬般情寵。","錦檀偏，翹股重，翠雲欹。","暮天屏上春山碧，映香煙霧隔。","蕙蘭心，魂夢役，歛蛾眉。"]', '["闲臥繡幃，慵想万般情寵。","錦檀偏，翹股重，翠云欹。","暮天屏上春山碧，映香煙霧隔。","蕙蘭心，魂梦役，歛蛾眉。"]', '诗', 'shi', '', NULL, '酒泉子 一 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81a630e-1170-4c2d-8465-92dc4fc8dce8', '酒泉子 二', '酒泉子 二', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["鈿匣舞鸞，隱映豔紅修碧。","月梳斜，雲鬢膩，粉香寒。","曉花微斂輕呵展，嫋釵金燕輭。","日初升，簾半卷，對妝殘。"]', '["鈿匣舞鸾，隐映豔紅修碧。","月梳斜，云鬢膩，粉香寒。","晓花微斂轻呵展，嫋釵金燕輭。","日初升，簾半卷，对妝殘。"]', '诗', 'shi', '', NULL, '酒泉子 二 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14833f3b-b55c-4775-aeb4-fcd75682f670', '浣溪沙 一', '浣溪沙 一', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["春暮黃鶯下砌前，水精簾影露珠懸，綺霞低映晚晴天。","弱柳萬條垂翠帶，殘紅滿地碎香鈿，蕙風飄蕩散輕煙。"]', '["春暮黄鶯下砌前，水精簾影露珠懸，綺霞低映晚晴天。","弱柳万條垂翠带，殘紅满地碎香鈿，蕙风飄蕩散轻煙。"]', '诗', 'shi', '', NULL, '浣溪沙 一 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74ecb65d-59ce-4430-8a1d-c86cbaf26090', '浣溪沙 二', '浣溪沙 二', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["花榭香紅煙景迷，滿庭芳草綠萋萋，金鋪閑掩繡簾底。","紫燕一雙嬌語碎，翠屏十二晚峰齊，夢魂消散醉空閨。"]', '["花榭香紅煙景迷，满庭芳草綠萋萋，金鋪闲掩繡簾底。","紫燕一雙嬌語碎，翠屏十二晚峰齊，梦魂消散醉空閨。"]', '诗', 'shi', '', NULL, '浣溪沙 二 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('074e7c8a-b265-4cfa-b30f-b454f25c2bf8', '浣溪沙 三', '浣溪沙 三', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["晚起紅房醉欲消，綠鬟雲散嫋金翹，雪香花語不勝嬌。","好是向人柔弱處，玉纖時急繡帬腰，春心牽惹轉無憀。"]', '["晚起紅房醉欲消，綠鬟云散嫋金翹，雪香花語不勝嬌。","好是向人柔弱处，玉纖时急繡帬腰，春心牽惹轉無憀。"]', '诗', 'shi', '', NULL, '浣溪沙 三 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5f2cd0e-baf3-4626-9d78-d9c1a1bd498e', '浣溪沙 四', '浣溪沙 四', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["一隻橫釵墜髻叢，靜眠珍簟起來慵，繡羅紅嫩抹蘇胸。","羞歛細蛾魂暗斷，因迷無語思猶濃，小屏香靄碧山重。"]', '["一隻橫釵墜髻叢，静眠珍簟起来慵，繡羅紅嫩抹蘇胸。","羞歛細蛾魂暗斷，因迷無語思猶濃，小屏香靄碧山重。"]', '诗', 'shi', '', NULL, '浣溪沙 四 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e138c3-b25e-4ccb-aa4b-44cf1756bb7a', '浣溪沙 五', '浣溪沙 五', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["雲薄羅帬綬帶長，滿身新裛瑞龍香，翠鈿斜映豔梅妝。","佯不覷人空婉約，笑和嬌語太猖狂，忍教牽恨暗形相。"]', '["云薄羅帬綬带长，满身新裛瑞龙香，翠鈿斜映豔梅妝。","佯不覷人空婉約，笑和嬌語太猖狂，忍教牽恨暗形相。"]', '诗', 'shi', '', NULL, '浣溪沙 五 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1a59f93-1bc1-460d-a86c-096272ddfa80', '浣溪沙 六', '浣溪沙 六', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["碧玉冠輕嫋燕釵，捧心無語步香階，緩移弓底繡羅鞋。","暗想歡娛何計好，豈堪期約有時乖，日高深院正忘懷。"]', '["碧玉冠轻嫋燕釵，捧心無語步香階，緩移弓底繡羅鞋。","暗想歡娛何計好，豈堪期約有时乖，日高深院正忘懷。"]', '诗', 'shi', '', NULL, '浣溪沙 六 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('521f2b2b-2754-4315-aa76-a5da687b89a1', '浣溪沙 七', '浣溪沙 七', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["半醉凝情臥繡茵，睡容無力卸羅裙，玉籠鸚鵡厭聽聞。","慵整落釵金翡翠，象梳欹鬢月生雲，錦屏綃幌麝煙薰。"]', '["半醉凝情臥繡茵，睡容無力卸羅裙，玉籠鸚鵡厭听闻。","慵整落釵金翡翠，象梳欹鬢月生云，錦屏綃幌麝煙薰。"]', '诗', 'shi', '', NULL, '浣溪沙 七 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c05d14b-972f-4b48-8cc5-2a071587c4dd', '後庭花 一', '後庭花 一', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["鶯啼燕語芳菲節，瑞庭花發。","昔時歡宴歌聲揭，管弦清越。","自從陵谷追遊歇，畫梁塵黦。","傷心一片如珪月，閑鎖宮闕。"]', '["鶯啼燕語芳菲節，瑞庭花發。","昔时歡宴歌声揭，管弦清越。","自從陵谷追游歇，畫梁塵黦。","傷心一片如珪月，闲鎖宮闕。"]', '诗', 'shi', '', NULL, '後庭花 一 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6c34993-0955-4407-ae8c-bf79131007af', '後庭花 二', '後庭花 二', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["輕盈舞伎含芳豔，競妝新臉。","步搖珠翠修蛾歛，膩鬟雲染。","歌聲慢發開檀點，繡衫斜掩。","時將纖手勻紅臉，笑拈金靨。"]', '["轻盈舞伎含芳豔，競妝新臉。","步搖珠翠修蛾歛，膩鬟云染。","歌声慢發开檀点，繡衫斜掩。","时將纖手勻紅臉，笑拈金靨。"]', '诗', 'shi', '', NULL, '後庭花 二 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b458676-96bb-49f9-806b-6a9b61cb1818', '後庭花 三', '後庭花 三', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["越羅小袖新香蒨，薄籠金釧。","倚闌無語搖輕扇，半遮勻面。","春殘日暖鶯嬌嬾，滿庭花片。","爭不教人長相見，畫堂深院。"]', '["越羅小袖新香蒨，薄籠金釧。","倚闌無語搖轻扇，半遮勻面。","春殘日暖鶯嬌嬾，满庭花片。","爭不教人长相见，畫堂深院。"]', '诗', 'shi', '', NULL, '後庭花 三 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28d902c2-bef1-4273-8727-f52edd667c76', '菩薩蠻 一', '菩薩蠻 一', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["梨花滿院飄香雪，高樓夜靜風箏咽。","斜月照簾帷，憶君和夢稀。","小窗燈影背，燕語驚愁態。","屏掩斷香飛，行雲山外歸。"]', '["梨花满院飄香雪，高楼夜静风箏咽。","斜月照簾帷，憶君和梦稀。","小窗灯影背，燕語驚愁態。","屏掩斷香飞，行云山外归。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2270beb-0b01-438f-8e8d-ce49d97cb728', '菩薩蠻 二', '菩薩蠻 二', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["繡簾高軸臨塘看，雨翻荷芰真珠散。","殘暑晚初涼，輕風渡水香。","無憀悲往事，爭那牽情思。","光影暗相催，等閑秋又來。"]', '["繡簾高軸臨塘看，雨翻荷芰真珠散。","殘暑晚初涼，轻风渡水香。","無憀悲往事，爭那牽情思。","光影暗相催，等闲秋又来。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06888732-a419-46c9-9010-e054fa27a722', '菩薩蠻 三', '菩薩蠻 三', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["天含殘碧融春色，五陵薄倖無消息。","盡日掩朱門，離愁暗斷魂。","鶯啼芳樹暖，燕拂回塘滿。","寂寞對屏山，相思醉夢間。"]', '["天含殘碧融春色，五陵薄倖無消息。","尽日掩朱门，離愁暗斷魂。","鶯啼芳樹暖，燕拂回塘满。","寂寞对屏山，相思醉梦间。"]', '诗', 'shi', '', NULL, '菩薩蠻 三 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b113a314-0f4c-4922-bf7a-64234edb7645', '清平樂', '清平乐', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["春光欲暮，寂寞閑庭戶。","粉蝶雙雙穿檻舞，簾卷晚天疎雨。","含愁獨倚閨幃，玉爐煙斷香微。","正是銷魂時節，東風滿院花飛。"]', '["春光欲暮，寂寞闲庭戶。","粉蝶雙雙穿檻舞，簾卷晚天疎雨。","含愁独倚閨幃，玉爐煙斷香微。","正是銷魂时節，东风满院花飞。"]', '诗', 'shi', '', NULL, '清平樂 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a979cef-4c14-4bc8-96db-92f84e5473c3', '更漏子 一', '更漏子 一', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["秋色清，河影淡，深戶燭寒光暗。","綃幌碧，錦衾紅，博山香炷融。","更漏咽，蛩鳴切，滿院霜華如雪。","新月上，薄雲收，映簾懸玉鉤。"]', '["秋色清，河影淡，深戶燭寒光暗。","綃幌碧，錦衾紅，博山香炷融。","更漏咽，蛩鳴切，满院霜华如雪。","新月上，薄云收，映簾懸玉鉤。"]', '诗', 'shi', '', NULL, '更漏子 一 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd6d6f59-7f30-4cc7-8d8c-1a3852437cb7', '更漏子 二', '更漏子 二', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["煙月寒，秋夜靜，漏轉金壺初永。","羅幕下，繡屏空，燈花結碎紅。","人悄悄，愁無了，思夢不成難曉。","長憶得，與郎期，竊香私語時。"]', '["煙月寒，秋夜静，漏轉金壺初永。","羅幕下，繡屏空，灯花結碎紅。","人悄悄，愁無了，思梦不成难晓。","长憶得，與郎期，竊香私語时。"]', '诗', 'shi', '', NULL, '更漏子 二 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d3e961f-91f2-4264-b9d9-172a7d80a088', '南歌子 一', '南歌子 一', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["遠山愁黛碧，橫波慢臉明，膩香紅玉茜羅輕。","深院晚堂人靜，理銀箏。","鬢動行雲影，帬遮點屐聲，嬌羞愛問曲中名。","楊柳杏花時節，幾多情。"]', '["远山愁黛碧，橫波慢臉明，膩香紅玉茜羅轻。","深院晚堂人静，理銀箏。","鬢动行云影，帬遮点屐声，嬌羞愛问曲中名。","楊柳杏花时節，幾多情。"]', '诗', 'shi', '', NULL, '南歌子 一 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7a63117-7262-4bb7-a4de-a0c4504164d6', '南歌子 二', '南歌子 二', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["惹恨還添恨，牽腸即斷腸，凝情不語一枝芳。","獨映畫簾閑立，繡衣香。","暗想爲雲女，應憐傅粉郎，晚來輕步出閨房。","髻慢釵橫無力，縱猖狂。"]', '["惹恨還添恨，牽腸即斷腸，凝情不語一枝芳。","独映畫簾闲立，繡衣香。","暗想爲云女，應怜傅粉郎，晚来轻步出閨房。","髻慢釵橫無力，縱猖狂。"]', '诗', 'shi', '', NULL, '南歌子 二 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a7144a7-76ee-49c2-b587-3042bce414e2', '木蘭花', '木蘭花', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["掩朱扉，鉤翠箔，滿院鶯聲春寂寞。","勻粉淚，恨檀郎，一去不歸花又落。","對斜暉，臨小閣，前事豈堪重想著。","金帶冷，畫屏幽，寶帳慵熏蘭麝薄。"]', '["掩朱扉，鉤翠箔，满院鶯声春寂寞。","勻粉泪，恨檀郎，一去不归花又落。","对斜暉，臨小閣，前事豈堪重想著。","金带冷，畫屏幽，寶帳慵熏蘭麝薄。"]', '诗', 'shi', '', NULL, '木蘭花 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e104e918-cc16-4d78-b0f9-3a6e9a3d4403', '小重山', '小重山', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["梁燕雙飛畫閣前，寂寥多少恨，嬾孤眠。","曉來閑處想君憐，紅羅帳，金鴨冷沈煙。","誰信損嬋娟，倚屏啼玉筯，溼香鈿。","四支無力上鞦韆，羣花謝，愁對豔陽天。"]', '["梁燕雙飞畫閣前，寂寥多少恨，嬾孤眠。","晓来闲处想君怜，紅羅帳，金鴨冷沈煙。","誰信損嬋娟，倚屏啼玉筯，溼香鈿。","四支無力上鞦韆，羣花謝，愁对豔陽天。"]', '诗', 'shi', '', NULL, '小重山 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3be1a26-d648-40b0-8c9e-d670c1728362', '臨江仙 一', '臨江仙 一', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["南齊天子寵嬋娟，六宮羅綺三千，潘妃嬌豔獨芳妍。","椒房蘭洞，雲雨降神仙。","縱態迷歡心不足，風流可惜當年，纖腰婉約步金蓮。","妖君傾國，猶自至今傳。"]', '["南齊天子寵嬋娟，六宮羅綺三千，潘妃嬌豔独芳妍。","椒房蘭洞，云雨降神仙。","縱態迷歡心不足，风流可惜當年，纖腰婉約步金蓮。","妖君傾国，猶自至今傳。"]', '诗', 'shi', '', NULL, '臨江仙 一 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f37302d0-d50a-491b-9d4f-7fca8f0314d0', '臨江仙 二', '臨江仙 二', 'eae41440-0efc-404c-8812-abb482608df1', '唐', '["幽閨欲曙聞鶯轉，紅窗月影微明，好風頻謝落花聲。","隔幃殘燭，猶照綺屏箏。","繡被錦茵眠玉煖，炷香斜嫋煙輕，淡蛾羞斂不勝情。"]', '["幽閨欲曙闻鶯轉，紅窗月影微明，好风頻謝落花声。","隔幃殘燭，猶照綺屏箏。","繡被錦茵眠玉煖，炷香斜嫋煙轻，淡蛾羞斂不勝情。"]', '诗', 'shi', '', NULL, '臨江仙 二 毛熙震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5c29920-5e23-4486-a9c6-8cea077c9846', '漁父 一', '漁父 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["水接衡門十里餘，信船歸去臥看書。","輕爵祿，慕玄虛，莫道漁人只爲魚。"]', '["水接衡门十里餘，信船归去臥看书。","轻爵祿，慕玄虛，莫道漁人只爲鱼。"]', '诗', 'shi', '', NULL, '漁父 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e05ab9fb-54ad-479f-b789-b63c3ba86238', '漁父 二', '漁父 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["避世垂綸不記年，官高爭得似君閑。","傾白酒，對青山，笑指柴門待月還。"]', '["避世垂綸不記年，官高爭得似君闲。","傾白酒，对青山，笑指柴门待月還。"]', '诗', 'shi', '', NULL, '漁父 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('532ec4a3-c152-4b35-ba8b-6c4a68a58b2e', '漁父 三', '漁父 三', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["櫂警鷗飛水濺袍，影隨潭面柳垂縚。","終日醉，絕塵勞，曾見錢塘八月濤。"]', '["櫂警鷗飞水濺袍，影隨潭面柳垂縚。","終日醉，絕塵勞，曾见錢塘八月濤。"]', '诗', 'shi', '', NULL, '漁父 三 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d18821e-9ec6-435a-87a8-9e1a5594ff0e', '南鄉子 一', '南乡子 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["煙漠漠，雨淒淒，岸花零落鷓鴣啼。","遠客扁舟臨野渡，思鄉處，潮退水平春色暮。"]', '["煙漠漠，雨淒淒，岸花零落鷓鴣啼。","远客扁舟臨野渡，思乡处，潮退水平春色暮。"]', '诗', 'shi', '', NULL, '南鄉子 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd56e488-9962-4ad2-b620-5ff1c50213dc', '南鄉子 二', '南乡子 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["蘭橈舉，水文開，競攜藤籠采蓮來。","回塘深處遙相見，邀同宴，淥酒一巵紅上面。"]', '["蘭橈舉，水文开，競携藤籠采蓮来。","回塘深处遙相见，邀同宴，淥酒一巵紅上面。"]', '诗', 'shi', '', NULL, '南鄉子 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7a5d641-0eb8-4c04-9c8b-3f4af53f9c42', '南鄉子 三', '南乡子 三', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["歸路近，扣舷歌，采真珠處水風多。","曲岸小橋山月過，煙深鎖，豆蔻花垂千萬朵。"]', '["归路近，扣舷歌，采真珠处水风多。","曲岸小橋山月過，煙深鎖，豆蔻花垂千万朵。"]', '诗', 'shi', '', NULL, '南鄉子 三 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96948b9f-faf5-4c7c-b965-b3c325efb564', '南鄉子 四', '南乡子 四', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["乘綵舫，過蓮塘，櫂歌驚起睡鴛鴦。","帶香遊女偎伴笑，爭窈窕，競折團荷遮晚照。"]', '["乘綵舫，過蓮塘，櫂歌驚起睡鴛鴦。","带香游女偎伴笑，爭窈窕，競折團荷遮晚照。"]', '诗', 'shi', '', NULL, '南鄉子 四 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('247d70ab-539b-4859-83d5-dccbfbf85835', '南鄉子 五', '南乡子 五', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["傾綠蟻，泛紅螺，閑邀女伴簇笙歌。","避暑信船輕浪裏，閑游戲，夾岸荔支紅蘸水。"]', '["傾綠蟻，泛紅螺，闲邀女伴簇笙歌。","避暑信船轻浪裏，闲游戲，夾岸荔支紅蘸水。"]', '诗', 'shi', '', NULL, '南鄉子 五 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476685f9-2788-4387-8bbb-376064101d82', '南鄉子 六', '南乡子 六', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["雲帶雨，浪迎風，釣翁回櫂碧灣中。","春酒香熟鱸魚美，誰同醉，纜却扁舟篷底睡。"]', '["云带雨，浪迎风，釣翁回櫂碧灣中。","春酒香熟鱸鱼美，誰同醉，纜却扁舟篷底睡。"]', '诗', 'shi', '', NULL, '南鄉子 六 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65de0b89-c4a1-4167-8fbc-7489e550da5a', '南鄉子 七', '南乡子 七', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["沙月靜，水煙輕，芰荷香裏夜船行。","綠鬟紅臉誰家女，遙相顧，緩唱櫂歌極浦去。"]', '["沙月静，水煙轻，芰荷香裏夜船行。","綠鬟紅臉誰家女，遙相顧，緩唱櫂歌極浦去。"]', '诗', 'shi', '', NULL, '南鄉子 七 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26aa81b9-8ed8-4306-970d-4b9eb629448c', '南鄉子 八', '南乡子 八', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["漁市散，渡船稀，越南雲樹望中微。","行客待潮天欲暮，送春浦，愁聽猩猩啼瘴雨。"]', '["漁市散，渡船稀，越南云樹望中微。","行客待潮天欲暮，送春浦，愁听猩猩啼瘴雨。"]', '诗', 'shi', '', NULL, '南鄉子 八 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b8c14ec-8b91-4437-8035-7ac20ff04852', '南鄉子 九', '南乡子 九', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["攏雲髻，背犀梳，焦紅衫映綠羅裾。","越王臺下春風暖，花盈岸，遊賞每邀鄰女伴。"]', '["攏云髻，背犀梳，焦紅衫映綠羅裾。","越王台下春风暖，花盈岸，游賞每邀鄰女伴。"]', '诗', 'shi', '', NULL, '南鄉子 九 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98dc7da7-3563-4bb9-994a-ae937a4f81e3', '南鄉子 十', '南乡子 十', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["相見處，晚晴天，刺桐花下越臺前。","暗裏回眸深屬意，遺雙翠，騎象背人先過水。"]', '["相见处，晚晴天，刺桐花下越台前。","暗裏回眸深屬意，遺雙翠，騎象背人先過水。"]', '诗', 'shi', '', NULL, '南鄉子 十 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9c9a82-fe2f-45cc-9a5f-f204b397c6e1', '南鄉子 十一', '南乡子 十一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["攜籠去，采菱歸，碧波風起雨霏霏。","趁岸小船齊櫂急，羅衣溼，出向桄榔樹下立。"]', '["携籠去，采菱归，碧波风起雨霏霏。","趁岸小船齊櫂急，羅衣溼，出向桄榔樹下立。"]', '诗', 'shi', '', NULL, '南鄉子 十一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b86ce6b-1f21-48ba-aadb-10d3750bb2a7', '南鄉子 十二', '南乡子 十二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["雲髻重，葛衣輕，見人微笑亦多情。","拾翠采珠能幾許，來還去，爭及村居織機女。"]', '["云髻重，葛衣轻，见人微笑亦多情。","拾翠采珠能幾許，来還去，爭及村居织機女。"]', '诗', 'shi', '', NULL, '南鄉子 十二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de87596f-5622-42bd-b13b-278ac97f32fb', '南鄉子 十三', '南乡子 十三', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["登畫舸，泛清波，采蓮時唱采蓮歌。","攔櫂聲齊羅袖斂，池光颭，驚起沙鷗八九點。"]', '["登畫舸，泛清波，采蓮时唱采蓮歌。","攔櫂声齊羅袖斂，池光颭，驚起沙鷗八九点。"]', '诗', 'shi', '', NULL, '南鄉子 十三 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4bab55c-8ede-4bc0-965d-5db75de2553e', '南鄉子 十四', '南乡子 十四', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["雙髻墜，小眉彎，笑隨女伴下春山。","玉纖遙指花深處，爭回顧，孔雀雙雙迎日舞。"]', '["雙髻墜，小眉彎，笑隨女伴下春山。","玉纖遙指花深处，爭回顧，孔雀雙雙迎日舞。"]', '诗', 'shi', '', NULL, '南鄉子 十四 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f839416d-477f-4954-a99a-707f7a16a86e', '南鄉子 十五', '南乡子 十五', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["紅豆蔻，紫玫瑰，謝娘家接越王臺。","一曲鄉歌齊撫掌，堪遊賞，酒酌螺杯流水上。"]', '["紅豆蔻，紫玫瑰，謝娘家接越王台。","一曲乡歌齊撫掌，堪游賞，酒酌螺杯流水上。"]', '诗', 'shi', '', NULL, '南鄉子 十五 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('653b43b1-1eb4-4749-9e01-a7cc83799d9d', '南鄉子 十六', '南乡子 十六', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["山果熟，水花香，家家風景有池塘。","木蘭舟上珠簾卷，歌聲遠，椰子酒傾鸚鵡醆。"]', '["山果熟，水花香，家家风景有池塘。","木蘭舟上珠簾卷，歌声远，椰子酒傾鸚鵡醆。"]', '诗', 'shi', '', NULL, '南鄉子 十六 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11a80ed-d673-4c77-a2a7-912849e5e855', '南鄉子 十七', '南乡子 十七', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["新月上，遠煙開，慣隨潮水采珠來。","櫂穿花過歸溪口，酤春酒，小艇纜牽垂岸柳。"]', '["新月上，远煙开，慣隨潮水采珠来。","櫂穿花過归溪口，酤春酒，小艇纜牽垂岸柳。"]', '诗', 'shi', '', NULL, '南鄉子 十七 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f687c986-6b25-4042-acee-36025c48d160', '西溪子 一', '西溪子 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["金縷翠鈿浮動，妝罷小窗圓夢。","日高時，春已老，人來到，滿地落花慵埽。","無語倚屏風，泣殘紅。"]', '["金縷翠鈿浮动，妝罷小窗圓梦。","日高时，春已老，人来到，满地落花慵埽。","無語倚屏风，泣殘紅。"]', '诗', 'shi', '', NULL, '西溪子 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b7b22c-e7ac-482c-96ce-85c41fbe1ff1', '西溪子 二', '西溪子 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["馬上見時如夢，認得臉波相送。","柳堤長，無限意，夕陽裏，醉把金鞭欲墜。","歸去想嬌嬈，暗魂銷。"]', '["马上见时如梦，認得臉波相送。","柳堤长，無限意，夕陽裏，醉把金鞭欲墜。","归去想嬌嬈，暗魂銷。"]', '诗', 'shi', '', NULL, '西溪子 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05558777-b488-490e-b423-20a2ad1d6a20', '女冠子 一', '女冠子 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["星高月午，丹桂青松深處，醮壇開。","金磬敲清露，珠幢立翠苔。","步虛聲縹緲，相像思徘徊。","曉天歸去路，指蓬萊。"]', '["星高月午，丹桂青松深处，醮壇开。","金磬敲清露，珠幢立翠苔。","步虛声縹緲，相像思徘徊。","晓天归去路，指蓬萊。"]', '诗', 'shi', '', NULL, '女冠子 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1cd81e5-ee89-4384-90d2-fa4faf276a88', '女冠子 二', '女冠子 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["春山夜靜，愁聞洞天疎磬，玉堂虛。","細霧垂珠佩，輕煙曳翠裾。","對花情脈脈，望月步徐徐。","劉阮今何處，絕來書。"]', '["春山夜静，愁闻洞天疎磬，玉堂虛。","細霧垂珠佩，轻煙曳翠裾。","对花情脈脈，望月步徐徐。","劉阮今何处，絕来书。"]', '诗', 'shi', '', NULL, '女冠子 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('682f88eb-c0f1-4c23-a18c-84d5d217a398', '中興樂', '中兴乐', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["後庭寂寂日初長，翩翩蝶舞紅芳。","繡簾垂地，金鴨無香，誰知春思如狂，憶蕭郎。","等閑一去，程遙信斷，五嶺三湘。","休開鸞鏡學宮妝，可能更理笙簧。","倚屏凝睇，淚落成行，手尋裙帶鴛鴦，暗思量。","忍孤前約，教人花貌，虛老風光。"]', '["後庭寂寂日初长，翩翩蝶舞紅芳。","繡簾垂地，金鴨無香，誰知春思如狂，憶蕭郎。","等闲一去，程遙信斷，五嶺三湘。","休开鸾镜学宮妝，可能更理笙簧。","倚屏凝睇，泪落成行，手尋裙带鴛鴦，暗思量。","忍孤前約，教人花貌，虛老风光。"]', '诗', 'shi', '', NULL, '中興樂 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4529676f-c5c5-464b-8734-1dc6638757ee', '酒泉子 一', '酒泉子 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["寂寞青樓，風觸繡簾珠碎撼。","月朦朧，花暗澹，鎖春愁。","尋思往事依稀夢，淚臉露桃紅色重。","鬢欹蟬，釵墜鳳，思悠悠。"]', '["寂寞青楼，风觸繡簾珠碎撼。","月朦朧，花暗澹，鎖春愁。","尋思往事依稀梦，泪臉露桃紅色重。","鬢欹蟬，釵墜鳳，思悠悠。"]', '诗', 'shi', '', NULL, '酒泉子 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12273877-96ff-42b1-ae4f-349d5e49dbfb', '酒泉子 二', '酒泉子 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["雨漬花零，紅散香凋池兩岸。","別情遙，春歌斷，掩銀屏。","孤帆早晚離三楚，閑理鈿箏愁幾許。","曲中情，弦上語，不堪聽。"]', '["雨漬花零，紅散香凋池兩岸。","別情遙，春歌斷，掩銀屏。","孤帆早晚離三楚，闲理鈿箏愁幾許。","曲中情，弦上語，不堪听。"]', '诗', 'shi', '', NULL, '酒泉子 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e066325-85d3-49cf-96c9-228e6c6a47c9', '酒泉子 三', '酒泉子 三', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["秋雨連綿，聲散敗荷叢裏。","那堪深夜枕前聽，酒初醒。","牽愁惹思更無停，燭暗香凝天欲曙。","細和煙，冷和雨，透簾旌。"]', '["秋雨連綿，声散敗荷叢裏。","那堪深夜枕前听，酒初醒。","牽愁惹思更無停，燭暗香凝天欲曙。","細和煙，冷和雨，透簾旌。"]', '诗', 'shi', '', NULL, '酒泉子 三 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7f5df0-8477-4726-8448-3986817f63e4', '酒泉子 四', '酒泉子 四', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["秋月嬋娟，皎潔碧紗窗外。","照花穿竹冷沈沈，印池心。","凝露滴，砌蛩吟。","驚覺謝娘殘夢，夜深斜傍枕前來，影徘徊。"]', '["秋月嬋娟，皎潔碧紗窗外。","照花穿竹冷沈沈，印池心。","凝露滴，砌蛩吟。","驚覺謝娘殘梦，夜深斜傍枕前来，影徘徊。"]', '诗', 'shi', '', NULL, '酒泉子 四 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa82c90-03b7-4b5a-8064-f77aee7a58ab', '浣溪沙 一', '浣溪沙 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["入夏偏宜澹薄妝，越羅衣褪鬱金黃，翠鈿檀注助容光。","相見無言還有恨，幾回判却又思量，月窗香徑夢悠颺。"]', '["入夏偏宜澹薄妝，越羅衣褪鬱金黄，翠鈿檀注助容光。","相见無言還有恨，幾回判却又思量，月窗香徑梦悠颺。"]', '诗', 'shi', '', NULL, '浣溪沙 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('339b46be-397b-424b-bc67-89621f4d725b', '浣溪沙 二', '浣溪沙 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["晚出閑庭看海棠，風流學得內家妝，小釵橫戴一枝芳。","鏤玉梳斜雲鬢膩，縷金衣透雪肌香，暗思何事立殘陽。"]', '["晚出闲庭看海棠，风流学得內家妝，小釵橫戴一枝芳。","鏤玉梳斜云鬢膩，縷金衣透雪肌香，暗思何事立殘陽。"]', '诗', 'shi', '', NULL, '浣溪沙 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f0e607d-0b39-453f-abd3-01c879b2ef2c', '浣溪沙 三', '浣溪沙 三', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["訪舊傷離欲斷魂，無因重見玉樓人，六街微雨鏤香塵。","早爲不逢巫峽夢，那堪虛度錦江春，遇花傾酒莫辭頻。"]', '["訪旧傷離欲斷魂，無因重见玉楼人，六街微雨鏤香塵。","早爲不逢巫峽梦，那堪虛度錦江春，遇花傾酒莫辞頻。"]', '诗', 'shi', '', NULL, '浣溪沙 三 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de8125a-0bb5-4239-b032-697f5ab0f2ce', '浣溪沙 四', '浣溪沙 四', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["紅藕花香到檻頻，可堪閑憶似花人，舊歡如夢絕音塵。"]', '["紅藕花香到檻頻，可堪闲憶似花人，旧歡如梦絕音塵。"]', '诗', 'shi', '', NULL, '浣溪沙 四 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60065c15-5bd2-4f72-a21e-7af33e65d0ac', '巫山一段雲 一', '巫山一段云 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["有客經巫峽，停橈向水湄。","楚王曾此夢瑤姬，一夢杳無期。","塵暗珠簾卷，香銷翠幄垂。","西風回首不勝悲，暮雨灑空祠。"]', '["有客經巫峽，停橈向水湄。","楚王曾此梦瑤姬，一梦杳無期。","塵暗珠簾卷，香銷翠幄垂。","西风回首不勝悲，暮雨灑空祠。"]', '诗', 'shi', '', NULL, '巫山一段雲 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('708d1fc4-07c9-4615-bf78-a59b5603af99', '巫山一段雲 二', '巫山一段云 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["古廟依青嶂，行宮枕碧流。","水聲山色鎖妝樓，往事思悠悠。","雲雨朝還暮，煙花春復秋。","啼猨何必近孤舟，行客自多愁。"]', '["古廟依青嶂，行宮枕碧流。","水声山色鎖妝楼，往事思悠悠。","云雨朝還暮，煙花春复秋。","啼猨何必近孤舟，行客自多愁。"]', '诗', 'shi', '', NULL, '巫山一段雲 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcdb0c46-805f-4264-9b42-ba659edf64e7', '菩薩蠻 一', '菩薩蠻 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["回塘風起波文細，刺桐花裏門斜閉。","殘日照平蕪，雙雙飛鷓鴣。","征帆何處客，相見還相隔。","不語欲魂銷，望中煙水遙。"]', '["回塘风起波文細，刺桐花裏门斜閉。","殘日照平蕪，雙雙飞鷓鴣。","征帆何处客，相见還相隔。","不語欲魂銷，望中煙水遙。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c6f7fce-1ae7-4a25-949c-fd27c7f019a1', '菩薩蠻 二', '菩薩蠻 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["等閑將度三春景，簾垂碧砌參差影。","曲檻日初斜，杜鵑啼落花。","恨君容易處，又話瀟湘去。","凝思倚屏山，淚流紅臉斑。"]', '["等闲將度三春景，簾垂碧砌參差影。","曲檻日初斜，杜鵑啼落花。","恨君容易处，又話瀟湘去。","凝思倚屏山，泪流紅臉斑。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e312a3be-340e-4d75-b926-bba030ab95a9', '菩薩蠻 三', '菩薩蠻 三', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["隔簾微雨雙飛燕，砌花零落紅深淺。","捻得寶箏調，心隨征櫂遙。","楚天雲外路，動便經年去。","香斷畫屏深，舊歡何處尋。"]', '["隔簾微雨雙飞燕，砌花零落紅深淺。","捻得寶箏調，心隨征櫂遙。","楚天云外路，动便經年去。","香斷畫屏深，旧歡何处尋。"]', '诗', 'shi', '', NULL, '菩薩蠻 三 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b3b95c3-6eba-44c4-a37f-f0906161c3e8', '漁歌子 一', '漁歌子 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["楚山青，湘水淥，春風澹蕩看不足。","草芊芊，花簇簇，漁艇櫂歌相續。","信浮沈，無管束，釣回乘月歸灣曲。","酒盈尊，雲滿屋，不見人間榮辱。"]', '["楚山青，湘水淥，春风澹蕩看不足。","草芊芊，花簇簇，漁艇櫂歌相續。","信浮沈，無管束，釣回乘月归灣曲。","酒盈尊，云满屋，不见人间榮辱。"]', '诗', 'shi', '', NULL, '漁歌子 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b6a670-b8dd-438a-b85c-5a52186366b7', '漁歌子 二', '漁歌子 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["荻花秋，瀟湘夜，橘洲佳景如屏畫。","碧煙中，明月下，小艇垂綸初罷。","水爲鄉，蓬作舍，魚羹稻飯常飡也。","酒盈杯，書滿架，名利不將心挂。"]', '["荻花秋，瀟湘夜，橘洲佳景如屏畫。","碧煙中，明月下，小艇垂綸初罷。","水爲乡，蓬作舍，鱼羹稻飯常飡也。","酒盈杯，书满架，名利不將心挂。"]', '诗', 'shi', '', NULL, '漁歌子 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf6109d8-9474-4ff4-92be-42d62b58b17e', '漁歌子 三', '漁歌子 三', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["柳垂絲，花滿樹，鶯啼楚岸春天暮。","櫂輕舟，出深浦，緩唱漁郎歸去。","罷垂綸，還酌醑，孤村遙指雲遮處。","下長汀，臨深渡，驚起一行沙鷺。"]', '["柳垂絲，花满樹，鶯啼楚岸春天暮。","櫂轻舟，出深浦，緩唱漁郎归去。","罷垂綸，還酌醑，孤村遙指云遮处。","下长汀，臨深渡，驚起一行沙鷺。"]', '诗', 'shi', '', NULL, '漁歌子 三 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c8b98eb-208d-486d-9206-16b43b967cc9', '漁歌子 四', '漁歌子 四', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["九疑山，三湘水，蘆花時節秋風起。","水雲間，山月裏，櫂月穿雲遊戲。","鼓清琴，傾淥蟻，扁舟自得逍遙志。","任東西，無定止，不議人間醒醉。"]', '["九疑山，三湘水，蘆花时節秋风起。","水云间，山月裏，櫂月穿云游戲。","鼓清琴，傾淥蟻，扁舟自得逍遙志。","任东西，無定止，不議人间醒醉。"]', '诗', 'shi', '', NULL, '漁歌子 四 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c2c9656-63aa-487f-a075-7c80cc54d7b0', '望遠行 一', '望远行 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["春日遲遲思寂寥，行客關山路遙。","瓊窗時聽語鶯嬌，柳絲牽恨一條條。","休暈繡，罷吹簫，貌逐殘花暗凋。","同心猶結舊帬腰，忍孤風月度良宵。"]', '["春日遲遲思寂寥，行客关山路遙。","瓊窗时听語鶯嬌，柳絲牽恨一條條。","休暈繡，罷吹簫，貌逐殘花暗凋。","同心猶結旧帬腰，忍孤风月度良宵。"]', '诗', 'shi', '', NULL, '望遠行 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06ec58fc-8048-460b-ba02-543697d557a9', '望遠行 二', '望远行 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["露滴幽庭落葉時，愁聚蕭娘柳眉。","玉郎一去負佳期，水雲迢遰雁書遲。","屏半掩，枕斜欹，蠟淚無言對垂。","吟蛩斷續漏頻移，入窗明月鑒空幃。"]', '["露滴幽庭落葉时，愁聚蕭娘柳眉。","玉郎一去負佳期，水云迢遰雁书遲。","屏半掩，枕斜欹，蠟泪無言对垂。","吟蛩斷續漏頻移，入窗明月鑒空幃。"]', '诗', 'shi', '', NULL, '望遠行 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26b558f2-256b-4b8b-9daf-21579a7c29e3', '河傳 一', '河傳 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["去去，何處。","迢迢巴楚，山水相連。","朝雲暮雨，依舊十二峰前，猨聲到客船。","愁腸豈異丁香結，因離別，故國音書絕。","想佳人花下，對明月春風，恨應同。"]', '["去去，何处。","迢迢巴楚，山水相連。","朝云暮雨，依旧十二峰前，猨声到客船。","愁腸豈異丁香結，因離別，故国音书絕。","想佳人花下，对明月春风，恨應同。"]', '诗', 'shi', '', NULL, '河傳 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a2cf3a-3835-467d-b376-7ee46b21c4a3', '河傳 二', '河傳 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["春暮，微雨。","送君南浦，愁斂雙蛾。","落花深處，啼鳥似逐離歌，粉檀珠淚和。","臨流更把同心結，情哽咽，後會何時節。","不堪回首相望，已隔汀洲，櫓聲幽。"]', '["春暮，微雨。","送君南浦，愁斂雙蛾。","落花深处，啼鸟似逐離歌，粉檀珠泪和。","臨流更把同心結，情哽咽，後會何时節。","不堪回首相望，已隔汀洲，櫓声幽。"]', '诗', 'shi', '', NULL, '河傳 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ad82ed6-247b-4c36-87c9-c83f429a8525', '虞美人', '虞美人', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["金籠鶯報天將曙，驚起分飛處。","夜來潛與玉郎期，多情不覺酒醒遲，失歸期。","映花避月遙相送，膩髻偏垂鳳。","却回嬌步入香閨，倚屏無語撚雲箆，翠眉低。"]', '["金籠鶯報天將曙，驚起分飞处。","夜来潛與玉郎期，多情不覺酒醒遲，失归期。","映花避月遙相送，膩髻偏垂鳳。","却回嬌步入香閨，倚屏無語撚云箆，翠眉低。"]', '诗', 'shi', '', NULL, '虞美人 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea807a5-0933-4cb7-a740-7f7a5db89247', '臨江仙 一', '臨江仙 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["簾卷池心小閣虛，暫涼閑步徐徐。","芰荷經雨半凋疎，拂堤垂柳，蟬噪夕陽餘。","不語低鬟幽思遠，玉釵斜墜雙魚。","幾回偷看寄來書，離情別恨，相隔欲何如。"]', '["簾卷池心小閣虛，暫涼闲步徐徐。","芰荷經雨半凋疎，拂堤垂柳，蟬噪夕陽餘。","不語低鬟幽思远，玉釵斜墜雙鱼。","幾回偷看寄来书，離情別恨，相隔欲何如。"]', '诗', 'shi', '', NULL, '臨江仙 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e89b6389-cff0-4db9-9870-5e8b067171b9', '臨江仙 二', '臨江仙 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["鶯報簾前暖日紅，玉爐殘麝猶濃。","起來閨思尚疎慵，[別]愁春夢，誰解此情悰。","彊整嬌姿臨寶鏡，小池一朵芙蓉。","舊歡無處再尋蹤，更堪回顧，屏畫九疑峰。"]', '["鶯報簾前暖日紅，玉爐殘麝猶濃。","起来閨思尚疎慵，[別]愁春梦，誰解此情悰。","彊整嬌姿臨寶镜，小池一朵芙蓉。","旧歡無处再尋蹤，更堪回顧，屏畫九疑峰。"]', '诗', 'shi', '', NULL, '臨江仙 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61fff933-a0ed-4164-83d1-27f8e87d93fd', '定風波 一', '定风波 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["志在煙霞慕隱淪，功成歸看五湖春。","一葉舟中吟復醉，雲水，此時方認自由身。","花島爲鄰鷗作侶，深處，經年不見市朝人。","已得希夷微妙旨，潛喜，荷衣蕙帶絕纖塵。"]', '["志在煙霞慕隐淪，功成归看五湖春。","一葉舟中吟复醉，云水，此时方認自由身。","花島爲鄰鷗作侶，深处，經年不见市朝人。","已得希夷微妙旨，潛喜，荷衣蕙带絕纖塵。"]', '诗', 'shi', '', NULL, '定風波 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d71f3418-6ebc-42d2-9534-b02f44eba2fa', '定風波 二', '定风波 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["十載逍遙物外居，白雲流水似相於。","乘興有時攜短櫂，江島，誰知求道不求魚。","到處等閑邀鶴伴，春岸，野花香氣撲琴書。","更飲一杯紅霞酒，回首，半鉤新月貼清虛。"]', '["十載逍遙物外居，白云流水似相於。","乘兴有时携短櫂，江島，誰知求道不求鱼。","到处等闲邀鹤伴，春岸，野花香氣撲琴书。","更饮一杯紅霞酒，回首，半鉤新月貼清虛。"]', '诗', 'shi', '', NULL, '定風波 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09c15b2c-a7c9-44a0-98bf-8991313da30f', '定風波 三', '定风波 三', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["又見辭巢燕子歸，阮郎何事絕音徽。","簾外西風黃葉落，池閣，隱莎蛩叫雨霏霏。","愁坐算程千萬里，頻跂，等閑經歲兩相違。","聽鵲憑龜無定處，不知，淚痕流在畫羅衣。"]', '["又见辞巢燕子归，阮郎何事絕音徽。","簾外西风黄葉落，池閣，隐莎蛩叫雨霏霏。","愁坐算程千万里，頻跂，等闲經歲兩相違。","听鵲憑龟無定处，不知，泪痕流在畫羅衣。"]', '诗', 'shi', '', NULL, '定風波 三 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58fced0b-0d5b-424e-902f-ccdad55da9a3', '定風波 四', '定风波 四', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["雁過秋空夜未央，隔窗煙月鎖蓮塘。","往事豈堪容易想，惆悵，故人迢遰在瀟湘。","縱有回文重疊意，誰寄，解鬟臨鏡泣殘妝。","沈水香消金鴨冷，愁永，候蟲聲接杵聲長。"]', '["雁過秋空夜未央，隔窗煙月鎖蓮塘。","往事豈堪容易想，惆悵，故人迢遰在瀟湘。","縱有回文重叠意，誰寄，解鬟臨镜泣殘妝。","沈水香消金鴨冷，愁永，候蟲声接杵声长。"]', '诗', 'shi', '', NULL, '定風波 四 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9390a40-6928-4136-bc48-bd8ca51cd85e', '定風波 五', '定风波 五', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["簾外煙和月滿庭，此時閑坐若爲情。","小閣擁爐殘酒醒，愁聽，寒風葉落一聲聲。","惟恨玉人芳信阻，雲雨，屏帷寂寞夢難成。","斗轉更闌心杳杳，將曉，銀釭斜照綺琴橫。"]', '["簾外煙和月满庭，此时闲坐若爲情。","小閣擁爐殘酒醒，愁听，寒风葉落一声声。","惟恨玉人芳信阻，云雨，屏帷寂寞梦难成。","斗轉更闌心杳杳，將晓，銀釭斜照綺琴橫。"]', '诗', 'shi', '', NULL, '定風波 五 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df76abfb-56ef-4ff3-9585-c50515835af0', '南歌子', '南歌子', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["錦帳銀燈影，紗窗玉漏聲，迢迢永夜夢難成。","愁對小庭秋色，月空明。"]', '["錦帳銀灯影，紗窗玉漏声，迢迢永夜梦难成。","愁对小庭秋色，月空明。"]', '诗', 'shi', '', NULL, '南歌子 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c51161-e4a9-4d04-83b4-5772d6199098', '漁父 一', '漁父 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["擺脫塵機上釣船，免教榮辱有流年。","無繫絆，沒愁煎，須信船中有散仙。"]', '["擺脫塵機上釣船，免教榮辱有流年。","無繫絆，沒愁煎，須信船中有散仙。"]', '诗', 'shi', '', NULL, '漁父 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c3c3e5a-cb3e-4b9e-a14a-746dfb0f25c2', '漁父 二', '漁父 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["風浩寒溪照膽明，小君山上玉蟾生。","荷露墜，翠煙輕，撥剌游魚幾箇驚。"]', '["风浩寒溪照膽明，小君山上玉蟾生。","荷露墜，翠煙轻，撥剌游鱼幾箇驚。"]', '诗', 'shi', '', NULL, '漁父 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('672dc390-62c6-4784-bc85-1b8fe1435764', '巫山一段雲 一', '巫山一段云 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["絳闕登真子，飄飄御綵鸞。","碧虛風雨佩光寒，斂袂下雲端。","月帳朝霞薄，星冠玉蘂攢。","遠遊蓬島降人間，特地拜龍顏。"]', '["絳闕登真子，飄飄御綵鸾。","碧虛风雨佩光寒，斂袂下云端。","月帳朝霞薄，星冠玉蘂攢。","远游蓬島降人间，特地拜龙顏。"]', '诗', 'shi', '', NULL, '巫山一段雲 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8996ca1f-d51f-40b8-adf7-74ac77bcbccb', '巫山一段雲 二', '巫山一段云 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["春去秋來也，愁心似醉醺。","去時邀約早回輪，及去又何曾。","歌扇花光[黦]，衣珠滴淚新。","恨身飜不作車塵，萬里得隨君。"]', '["春去秋来也，愁心似醉醺。","去时邀約早回輪，及去又何曾。","歌扇花光[黦]，衣珠滴泪新。","恨身飜不作车塵，万里得隨君。"]', '诗', 'shi', '', NULL, '巫山一段雲 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15718a00-e714-4b68-a9bb-93df519d9e65', '春光好 一', '春光好 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["天初暖，日初長，好春光。","萬彙此時皆得意，競芬芳。","筍迸苔錢嫩綠，花偎雪塢濃香。","誰把金絲裁翦却，挂斜陽。"]', '["天初暖，日初长，好春光。","万彙此时皆得意，競芬芳。","筍迸苔錢嫩綠，花偎雪塢濃香。","誰把金絲裁翦却，挂斜陽。"]', '诗', 'shi', '', NULL, '春光好 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f8186b-3b47-419b-a667-eb64560d35c2', '春光好 二', '春光好 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["花滴露，柳搖煙，豔陽天。","雨霽山櫻紅欲爛，谷鶯遷。","飲處交飛玉斝，遊時倒把金鞭。","風颭九衢榆葉動，簇青錢。"]', '["花滴露，柳搖煙，豔陽天。","雨霽山櫻紅欲爛，谷鶯遷。","饮处交飞玉斝，游时倒把金鞭。","风颭九衢榆葉动，簇青錢。"]', '诗', 'shi', '', NULL, '春光好 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f98e5a-9d57-43a5-b710-402fa43ab185', '春光好 三', '春光好 三', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["胸鋪雪，臉分蓮，理繁弦。","纖指飛飜金鳳語，轉嬋娟。","嘈囋如敲玉佩，清泠似滴香泉。","曲罷問郎名箇甚，想夫憐。"]', '["胸鋪雪，臉分蓮，理繁弦。","纖指飞飜金鳳語，轉嬋娟。","嘈囋如敲玉佩，清泠似滴香泉。","曲罷问郎名箇甚，想夫怜。"]', '诗', 'shi', '', NULL, '春光好 三 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86059a04-da7c-4e09-bda4-ae91d1c13444', '春光好 四', '春光好 四', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["磧香散，渚冰融，暖空濛。","飛絮悠揚徧虛空，惹輕風。","柳眼煙來點綠，花心日與妝紅。","黃雀錦鸞相對舞，近簾櫳。"]', '["磧香散，渚冰融，暖空濛。","飞絮悠揚徧虛空，惹轻风。","柳眼煙来点綠，花心日與妝紅。","黄雀錦鸾相对舞，近簾櫳。"]', '诗', 'shi', '', NULL, '春光好 四 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cf291e8-6059-4a47-87f2-d9ed7073c158', '春光好 五', '春光好 五', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["雞樹綠，鳳池清，滿神京。","玉兔宮前金牓出，列仙名。","疊雪羅袍接武，團花駿馬嬌行。","開宴錦江遊爛熳，柳煙輕。"]', '["雞樹綠，鳳池清，满神京。","玉兔宮前金牓出，列仙名。","叠雪羅袍接武，團花駿马嬌行。","开宴錦江游爛熳，柳煙轻。"]', '诗', 'shi', '', NULL, '春光好 五 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5530c224-4953-4abd-9202-4192c0ebdce5', '春光好 六', '春光好 六', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["芳叢繡，綠筵張，兩心狂。","空遣橫波傳意緒，對笙簧。","雖似安仁擲果，未聞韓壽分香。","流水桃花情不已，待劉郎。"]', '["芳叢繡，綠筵張，兩心狂。","空遣橫波傳意緒，对笙簧。","雖似安仁擲果，未闻韓壽分香。","流水桃花情不已，待劉郎。"]', '诗', 'shi', '', NULL, '春光好 六 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1dd11a0-4e85-41f4-995e-ef02726fb21e', '春光好 七', '春光好 七', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["垂繡幔，掩雲屏，思盈盈。","雙枕珊瑚無限情，翠釵橫。","幾見纖纖動處，時聞款款嬌聲。","却出錦屏妝面了，理秦箏。"]', '["垂繡幔，掩云屏，思盈盈。","雙枕珊瑚無限情，翠釵橫。","幾见纖纖动处，时闻款款嬌声。","却出錦屏妝面了，理秦箏。"]', '诗', 'shi', '', NULL, '春光好 七 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13950046-d1b9-4be8-95e6-59d28af94fbb', '春光好 八', '春光好 八', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["金轡響，玉鞭長，映垂楊。","堤上采花筵上醉，滿衣香。","無處不攜弦管，直應占斷春光。","年少王孫何處好，競尋芳。"]', '["金轡响，玉鞭长，映垂楊。","堤上采花筵上醉，满衣香。","無处不携弦管，直應占斷春光。","年少王孫何处好，競尋芳。"]', '诗', 'shi', '', NULL, '春光好 八 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f12566-c8ba-4ff0-8fe3-ae8f362b212b', '春光好 九', '春光好 九', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["蘋葉嫩，杏花明，畫船輕。","雙浴鴛鴦出綠汀，櫂歌聲。","春水無風無浪，春來半雨半晴。","紅粉相隨南浦晚，莫辭行。"]', '["蘋葉嫩，杏花明，畫船轻。","雙浴鴛鴦出綠汀，櫂歌声。","春水無风無浪，春来半雨半晴。","紅粉相隨南浦晚，莫辞行。"]', '诗', 'shi', '', NULL, '春光好 九 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e2fd147-05b2-4754-a59a-a1112c5b816d', '西江月 一', '西江月 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["月映長江秋水，分明冷浸星河。","淺沙汀上白雲多，雪散幾叢蘆葦。","扁舟倒影寒潭，煙光遠罩輕波。","笛聲何處響漁歌，兩岸蘋香暗起。"]', '["月映长江秋水，分明冷浸星河。","淺沙汀上白云多，雪散幾叢蘆葦。","扁舟倒影寒潭，煙光远罩轻波。","笛声何处响漁歌，兩岸蘋香暗起。"]', '诗', 'shi', '', NULL, '西江月 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f41c26f-df32-4ba8-b928-73d6cd0a07ca', '西江月 二', '西江月 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["水上鴛鴦比翼，巧將繡作羅衣。","鏡中重畫遠山眉，春睡起來無力。","細雀穩簪雲髻，含羞時想佳期。","臉邊紅豔對花枝，猶占鳳樓春色。"]', '["水上鴛鴦比翼，巧將繡作羅衣。","镜中重畫远山眉，春睡起来無力。","細雀穩簪云髻，含羞时想佳期。","臉邊紅豔对花枝，猶占鳳楼春色。"]', '诗', 'shi', '', NULL, '西江月 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05b73306-fde3-4a3c-9de3-570db2ca3dfe', '赤棗子 一', '赤棗子 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["夜悄悄，燭熒熒，金爐香盡酒初醒。","春睡起來回雪面，含羞不語倚雲屏。"]', '["夜悄悄，燭熒熒，金爐香尽酒初醒。","春睡起来回雪面，含羞不語倚云屏。"]', '诗', 'shi', '', NULL, '赤棗子 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68b0f21c-5c27-4e0f-955f-dc4117dc2d37', '赤棗子 二', '赤棗子 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["蓮臉薄，柳眉長，等閑無事莫思量。","每一見時明月夜，損人情思斷人腸。"]', '["蓮臉薄，柳眉长，等闲無事莫思量。","每一见时明月夜，損人情思斷人腸。"]', '诗', 'shi', '', NULL, '赤棗子 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a9b382-5e4c-466e-9cc3-32947ed44546', '女冠子 一', '女冠子 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["薄妝桃臉，滿面縱橫花靨，豔情多。","綬帶盤金縷，輕帬透碧羅。","含羞眉[乍]斂，微語笑相和。","不會頻偷眼，意如何。"]', '["薄妝桃臉，满面縱橫花靨，豔情多。","綬带盤金縷，轻帬透碧羅。","含羞眉[乍]斂，微語笑相和。","不會頻偷眼，意如何。"]', '诗', 'shi', '', NULL, '女冠子 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da72420f-2ac0-47ef-bc07-86610e4ae40d', '女冠子 二', '女冠子 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["秋宵秋月，一朵荷花初發，照前池。","搖曳熏香夜，嬋娟對鏡時。","蘂中千點淚，心裏萬條絲。","恰似輕盈女，好風姿。"]', '["秋宵秋月，一朵荷花初發，照前池。","搖曳熏香夜，嬋娟对镜时。","蘂中千点泪，心裏万條絲。","恰似轻盈女，好风姿。"]', '诗', 'shi', '', NULL, '女冠子 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2afa154-9d9a-4994-a5d0-6a77f8c8c406', '更漏子 一', '更漏子 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["玉闌干，金甃井，月照碧梧桐影。","獨自箇，立多時，露華濃溼衣。","一向，凝情望，待得不成模樣。","雖叵耐，又尋思，爭生嗔得伊。"]', '["玉闌干，金甃井，月照碧梧桐影。","独自箇，立多时，露华濃溼衣。","一向，凝情望，待得不成模樣。","雖叵耐，又尋思，爭生嗔得伊。"]', '诗', 'shi', '', NULL, '更漏子 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df05905-1771-4876-a9cb-d129dd450824', '更漏子 二', '更漏子 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["三十六宮秋夜永，露華點滴高梧。","丁丁玉漏咽銅壺，明月上金鋪。","紅線毯，博山爐，香風暗觸流蘇。","羊車一去長青蕪，鏡塵鸞綵孤。"]', '["三十六宮秋夜永，露华点滴高梧。","丁丁玉漏咽銅壺，明月上金鋪。","紅線毯，博山爐，香风暗觸流蘇。","羊车一去长青蕪，镜塵鸾綵孤。"]', '诗', 'shi', '', NULL, '更漏子 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65c75c13-83ff-4e40-bb42-5b6a71f6acc4', '定風波', '定风波', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["暖日閑窗映碧紗，小池春水浸晴霞。","數樹海棠紅欲盡，爭忍，玉閨深掩過年華。","獨凭繡牀方寸亂，腸斷，淚珠穿破臉邊花。","鄰舍女郎相借問，音信，教人羞道未還家。"]', '["暖日闲窗映碧紗，小池春水浸晴霞。","數樹海棠紅欲尽，爭忍，玉閨深掩過年华。","独凭繡牀方寸亂，腸斷，泪珠穿破臉邊花。","鄰舍女郎相借问，音信，教人羞道未還家。"]', '诗', 'shi', '', NULL, '定風波 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c73389e-37e9-411e-9d7a-08219e6878ff', '木蘭花 一', '木蘭花 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["兒家夫婿心容易，身又不來書不寄。","閑庭獨立鳥關關，爭忍拋奴深院裏。","悶向綠紗窗下睡，睡又不成愁已至。","今年却憶去年春，同在木蘭花下醉。"]', '["兒家夫婿心容易，身又不来书不寄。","闲庭独立鸟关关，爭忍拋奴深院裏。","悶向綠紗窗下睡，睡又不成愁已至。","今年却憶去年春，同在木蘭花下醉。"]', '诗', 'shi', '', NULL, '木蘭花 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2556d24-ea0a-46ee-b42c-2448998f2a64', '木蘭花 二', '木蘭花 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["日照玉樓花似錦，樓上醉和春色寢。","綠楊風送小鶯聲，殘夢不成離玉枕。","堪愛晚來韶景甚，寶柱秦箏方再品。","青蛾紅臉笑來迎，又向海棠花下飲。"]', '["日照玉楼花似錦，楼上醉和春色寢。","綠楊风送小鶯声，殘梦不成離玉枕。","堪愛晚来韶景甚，寶柱秦箏方再品。","青蛾紅臉笑来迎，又向海棠花下饮。"]', '诗', 'shi', '', NULL, '木蘭花 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e550440c-6141-4505-9b16-0860c0b60ac5', '木蘭花 三', '木蘭花 三', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["春早玉樓煙雨夜，簾外櫻桃花半謝。","錦屏香冷繡衾寒，怊悵憶君無計舍。","侵曉鵲聲來砌下，鸞鏡殘妝紅粉罷。","黛眉雙點不成描，留待玉郎歸日畫。"]', '["春早玉楼煙雨夜，簾外櫻桃花半謝。","錦屏香冷繡衾寒，怊悵憶君無計舍。","侵晓鵲声来砌下，鸾镜殘妝紅粉罷。","黛眉雙点不成描，留待玉郎归日畫。"]', '诗', 'shi', '', NULL, '木蘭花 三 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6f6c50b-e533-45da-8e33-99e1221b8012', '清平樂', '清平乐', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["春來街砌，春雨如絲細。","春地滿飄紅杏蔕，春燕舞隨風勢。","春幡細縷春繒，春閨一點春燈。","自是春心撩亂，非干春夢無憑。"]', '["春来街砌，春雨如絲細。","春地满飄紅杏蔕，春燕舞隨风勢。","春幡細縷春繒，春閨一点春灯。","自是春心撩亂，非干春梦無憑。"]', '诗', 'shi', '', NULL, '清平樂 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c79ce05e-b8bf-484d-ae74-db8b3f6e292b', '菩薩蠻 一', '菩薩蠻 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["曉來中酒和春睡，四支無力雲鬟墜。","斜臥臉波春，玉郎休惱人。","日高猶未起，爲戀鴛鴦被。","鸚鵡語金籠，道兒還是慵。"]', '["晓来中酒和春睡，四支無力云鬟墜。","斜臥臉波春，玉郎休惱人。","日高猶未起，爲戀鴛鴦被。","鸚鵡語金籠，道兒還是慵。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfb041e0-8247-4bf3-882e-ea753a0b7959', '菩薩蠻 二', '菩薩蠻 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["紅爐煖閣佳人睡，隔簾飛雪添寒氣。","小院奏笙歌，香風簇綺羅。","酒傾金醆滿，蘭燭重開宴。","公子醉如泥，天街聞馬嘶。"]', '["紅爐煖閣佳人睡，隔簾飞雪添寒氣。","小院奏笙歌，香风簇綺羅。","酒傾金醆满，蘭燭重开宴。","公子醉如泥，天街闻马嘶。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('890b74b1-6cce-437f-a5de-54fd78763f66', '菩薩蠻 三', '菩薩蠻 三', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["翠眉雙臉新妝薄，幽閨斜卷青羅幕。","寒食百花時，紅繁香滿枝。","雙雙梁燕語，蝶舞相隨去。","腸斷正思君，閑眠冷繡茵。"]', '["翠眉雙臉新妝薄，幽閨斜卷青羅幕。","寒食百花时，紅繁香满枝。","雙雙梁燕語，蝶舞相隨去。","腸斷正思君，闲眠冷繡茵。"]', '诗', 'shi', '', NULL, '菩薩蠻 三 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62088d62-97db-4659-844e-ed744403c770', '菩薩蠻 四', '菩薩蠻 四', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["畫屏繡閣三秋雨，香脣膩臉偎人語。","語罷欲天明，嬌多夢不成。","曉街鐘鼓絕，嗔道如今別。","特地氣長吁，倚屏彈淚珠。"]', '["畫屏繡閣三秋雨，香脣膩臉偎人語。","語罷欲天明，嬌多梦不成。","晓街鐘鼓絕，嗔道如今別。","特地氣长吁，倚屏彈泪珠。"]', '诗', 'shi', '', NULL, '菩薩蠻 四 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b6be4e4-6d12-4fa3-a0ba-36c07052dbeb', '浣溪沙 一', '浣溪沙 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["落絮殘鶯半日天，玉柔花醉只思眠，惹窗映竹滿爐煙。","獨掩畫屏愁不語，斜欹瑤枕髻鬟偏，此時心在阿誰邊。"]', '["落絮殘鶯半日天，玉柔花醉只思眠，惹窗映竹满爐煙。","独掩畫屏愁不語，斜欹瑤枕髻鬟偏，此时心在阿誰邊。"]', '诗', 'shi', '', NULL, '浣溪沙 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('941385dc-c3ae-4c48-8730-441ae643c1f6', '浣溪沙 二', '浣溪沙 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["天碧羅衣拂地垂，美人初著更相宜，宛風如舞透香肌。","獨坐含嚬吹鳳竹，園中緩步折花枝，有情無力泥人時。"]', '["天碧羅衣拂地垂，美人初著更相宜，宛风如舞透香肌。","独坐含嚬吹鳳竹，园中緩步折花枝，有情無力泥人时。"]', '诗', 'shi', '', NULL, '浣溪沙 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75562549-d8ba-45b4-bdb3-6aca5f7eb1b0', '浣溪沙 三', '浣溪沙 三', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["相見休言有淚珠，酒闌重得敘歡娛，鳳屏鴛枕宿金鋪。","蘭麝細香聞喘息，綺羅纖縷見肌膚，此時還恨薄情無。"]', '["相见休言有泪珠，酒闌重得敘歡娛，鳳屏鴛枕宿金鋪。","蘭麝細香闻喘息，綺羅纖縷见肌膚，此时還恨薄情無。"]', '诗', 'shi', '', NULL, '浣溪沙 三 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aac88aa-cc66-4a26-82a3-2f3d495d533f', '三字令', '三字令', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["春欲盡，日遲遲。","牡丹時，羅幌卷。","翠簾垂，綵牋書。","紅粉淚，兩心知。","人不在，燕空歸。","負佳期，香燼落。","枕函欹，月分明。","花澹薄，惹相思。"]', '["春欲尽，日遲遲。","牡丹时，羅幌卷。","翠簾垂，綵牋书。","紅粉泪，兩心知。","人不在，燕空归。","負佳期，香燼落。","枕函欹，月分明。","花澹薄，惹相思。"]', '诗', 'shi', '', NULL, '三字令 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf8cd8b7-81fd-475d-a044-6065b65b42df', '南鄉子 一', '南乡子 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["嫩草如煙，石榴花發海南天。","日暮江亭春影淥，鴛鴦浴，水遠山長看不足。"]', '["嫩草如煙，石榴花發海南天。","日暮江亭春影淥，鴛鴦浴，水远山长看不足。"]', '诗', 'shi', '', NULL, '南鄉子 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70ca46ae-8fcd-4c00-9c54-6f9266cd5c77', '南鄉子 二', '南乡子 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["畫舸停橈，槿花籬外竹橫橋。","水上遊人沙上女，回顧，笑指芭蕉林裏住。"]', '["畫舸停橈，槿花籬外竹橫橋。","水上游人沙上女，回顧，笑指芭蕉林裏住。"]', '诗', 'shi', '', NULL, '南鄉子 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c29278c-31b8-4121-b1d4-da18ea188522', '南鄉子 三', '南乡子 三', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["岸遠沙平，日斜歸路晚霞明。","孔雀自憐金翠尾，臨水，認得行人驚不起。"]', '["岸远沙平，日斜归路晚霞明。","孔雀自怜金翠尾，臨水，認得行人驚不起。"]', '诗', 'shi', '', NULL, '南鄉子 三 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cdf73a6-417d-41d6-8f96-0a1434687d81', '南鄉子 四', '南乡子 四', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["洞口誰家，木蘭船繫木蘭花。","紅袖女郎相引去，遊南浦，笑倚春風相對語。"]', '["洞口誰家，木蘭船繫木蘭花。","紅袖女郎相引去，游南浦，笑倚春风相对語。"]', '诗', 'shi', '', NULL, '南鄉子 四 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('739ca26b-6d49-42c6-aca3-7be479e32257', '南鄉子 五', '南乡子 五', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["二八花鈿，胸前如雪臉如蓮。","耳墜金[鐶]穿瑟瑟，霞衣窄，笑倚江頭招遠客。"]', '["二八花鈿，胸前如雪臉如蓮。","耳墜金[鐶]穿瑟瑟，霞衣窄，笑倚江头招远客。"]', '诗', 'shi', '', NULL, '南鄉子 五 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d1841f3-11e9-4a0f-b414-84b145d75e19', '南鄉子 六', '南乡子 六', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["路入南中，桄榔葉暗蓼花紅。","兩岸人家微雨後，收紅豆，樹底纖纖擡素手。"]', '["路入南中，桄榔葉暗蓼花紅。","兩岸人家微雨後，收紅豆，樹底纖纖擡素手。"]', '诗', 'shi', '', NULL, '南鄉子 六 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35f6e378-6ed2-45c3-8b80-0f67f8ba78af', '南鄉子 七', '南乡子 七', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["袖斂鮫綃，采香深洞笑相邀。","藤杖枝頭蘆酒滴，鋪葵席，豆蔻花間趖晚日。"]', '["袖斂鮫綃，采香深洞笑相邀。","藤杖枝头蘆酒滴，鋪葵席，豆蔻花间趖晚日。"]', '诗', 'shi', '', NULL, '南鄉子 七 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d156335f-3eff-4fc5-b842-d6d5b540c922', '南鄉子 八', '南乡子 八', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["翡翠鵁鶄，白蘋香裏小沙汀。","島上陰陰秋雨色，蘆花撲，數隻漁船何處宿。"]', '["翡翠鵁鶄，白蘋香裏小沙汀。","島上陰陰秋雨色，蘆花撲，數隻漁船何处宿。"]', '诗', 'shi', '', NULL, '南鄉子 八 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab114324-8ee1-4048-816d-998ffabde86b', '獻衷心', '獻衷心', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["見好花顏色，爭笑東風。","雙臉上，晚妝同。","閉小樓深閣，春景重重。","三五夜，偏有恨，月明中。","情未已，信曾通，滿衣猶自染檀紅。","恨不如雙燕，飛舞簾櫳。","春欲暮，殘絮盡，柳條空。"]', '["见好花顏色，爭笑东风。","雙臉上，晚妝同。","閉小楼深閣，春景重重。","三五夜，偏有恨，月明中。","情未已，信曾通，满衣猶自染檀紅。","恨不如雙燕，飞舞簾櫳。","春欲暮，殘絮尽，柳條空。"]', '诗', 'shi', '', NULL, '獻衷心 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b0a0e32-2f69-4857-a165-1d56eec60ef0', '賀明朝 一', '賀明朝 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["憶昔花間初識面，紅袖半遮妝臉。","輕轉石榴帬帶，故將纖纖玉指，偷撚雙鳳金線。","碧梧桐鎖深深院，誰料得兩情，何日教繾綣？","羨春來雙燕，飛到玉樓，朝暮相見。"]', '["憶昔花间初識面，紅袖半遮妝臉。","轻轉石榴帬带，故將纖纖玉指，偷撚雙鳳金線。","碧梧桐鎖深深院，誰料得兩情，何日教繾綣？","羨春来雙燕，飞到玉楼，朝暮相见。"]', '诗', 'shi', '', NULL, '賀明朝 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b0e29a0-9353-449f-a69d-d42adde3c960', '賀明朝 二', '賀明朝 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["憶昔花間相見後，只憑纖手，暗拋紅豆。","人前不解，巧傳心事，別來依舊，孤負春晝。","碧羅衣上蹙金繡，覩對對鴛鴦，空裛淚痕透。","想韶顏非久，終是爲伊，只[恁]偷瘦。"]', '["憶昔花间相见後，只憑纖手，暗拋紅豆。","人前不解，巧傳心事，別来依旧，孤負春晝。","碧羅衣上蹙金繡，覩对对鴛鴦，空裛泪痕透。","想韶顏非久，終是爲伊，只[恁]偷瘦。"]', '诗', 'shi', '', NULL, '賀明朝 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('587d77cd-4aea-480f-9386-bad8e98c43f5', '江城子', '江城子', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["晚日金陵岸草平，落霞明，水無情。","六代繁華，暗逐逝波聲。","空有姑蘇臺上月，如西子鏡，照江城。"]', '["晚日金陵岸草平，落霞明，水無情。","六代繁华，暗逐逝波声。","空有姑蘇台上月，如西子镜，照江城。"]', '诗', 'shi', '', NULL, '江城子 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd884a84-e2d3-4c90-b009-4751733509b2', '鳳樓春', '鳳楼春', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["鳳髻綠雲叢，深掩房櫳。","錦書通，夢中相見覺來慵。","勻面淚，臉珠融。","因想玉郎何處去，對淑景誰同。","小樓中，春思無窮。","倚闌凝望，闇牽愁緒，柳花飛起東風。","斜日照簾，羅幌香冷粉屏空。","海棠零落，鶯語殘紅。"]', '["鳳髻綠云叢，深掩房櫳。","錦书通，梦中相见覺来慵。","勻面泪，臉珠融。","因想玉郎何处去，对淑景誰同。","小楼中，春思無窮。","倚闌凝望，闇牽愁緒，柳花飞起东风。","斜日照簾，羅幌香冷粉屏空。","海棠零落，鶯語殘紅。"]', '诗', 'shi', '', NULL, '鳳樓春 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1803c1f-74f3-43aa-884c-233a546b7348', '生查子', '生查子', '72eeb99b-0933-4b31-876c-2465ec0aa444', '唐', '["竟日畫堂歡，入夜重開宴。","翦燭蠟煙香，促席花光顫。","待得月華來，滿院如鋪練。","門外簇驊騮，直待更深散。"]', '["竟日畫堂歡，入夜重开宴。","翦燭蠟煙香，促席花光顫。","待得月华来，满院如鋪練。","门外簇驊騮，直待更深散。"]', '诗', 'shi', '', NULL, '生查子 歐陽彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c572aa02-22cd-4b18-895d-8d43cd3c3b75', '虞美人 一', '虞美人 一', '45872534-3d7d-442b-a8d5-656fdbbde825', '唐', '["粉融紅膩蓮房綻，臉動雙波慢。","小魚銜玉鬢釵橫，石榴裙染象紗輕，轉娉婷。","偷期錦浪荷深處，一夢雲兼雨。","臂留檀印齒痕香，深秋不寐漏初長，儘思量。"]', '["粉融紅膩蓮房綻，臉动雙波慢。","小鱼銜玉鬢釵橫，石榴裙染象紗轻，轉娉婷。","偷期錦浪荷深处，一梦云兼雨。","臂留檀印齒痕香，深秋不寐漏初长，儘思量。"]', '诗', 'shi', '', NULL, '虞美人 一 閻選 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8902ac96-c29f-4b61-a845-adc79820d012', '虞美人 二', '虞美人 二', '45872534-3d7d-442b-a8d5-656fdbbde825', '唐', '["楚腰蠐領團香玉，鬢疊深深綠。","月蛾星眼笑微頻，柳夭桃豔不勝春，晚妝勻。","水紋簟映青紗帳，霧罩秋波上。","一枝嬌臥醉芙蓉，良宵不得與君同，恨忡忡。"]', '["楚腰蠐領團香玉，鬢叠深深綠。","月蛾星眼笑微頻，柳夭桃豔不勝春，晚妝勻。","水紋簟映青紗帳，霧罩秋波上。","一枝嬌臥醉芙蓉，良宵不得與君同，恨忡忡。"]', '诗', 'shi', '', NULL, '虞美人 二 閻選 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a66e343-6aa0-448c-8e6c-5bf2cc885e8c', '臨江仙 一', '臨江仙 一', '45872534-3d7d-442b-a8d5-656fdbbde825', '唐', '["雨停荷芰逗濃香，岸邊蟬噪垂楊。","物華空有舊池塘，不逢仙子，何處夢襄王。","珍簟對欹鴛枕冷，此來塵暗淒涼。","欲憑危檻恨偏長，藕花珠綴，猶似汗凝妝。"]', '["雨停荷芰逗濃香，岸邊蟬噪垂楊。","物华空有旧池塘，不逢仙子，何处梦襄王。","珍簟对欹鴛枕冷，此来塵暗淒涼。","欲憑危檻恨偏长，藕花珠綴，猶似汗凝妝。"]', '诗', 'shi', '', NULL, '臨江仙 一 閻選 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('743b4178-4586-4ae5-a489-fc5c0a46ad16', '臨江仙 二', '臨江仙 二', '45872534-3d7d-442b-a8d5-656fdbbde825', '唐', '["十二高峰天外寒，竹梢輕拂仙壇。","寶衣行雨在雲端，畫簾深殿，香霧冷風殘。","欲問楚王何處去，翠屏猶掩金鸞。","猨啼明月照空灘，孤舟行客，驚夢亦艱難。"]', '["十二高峰天外寒，竹梢轻拂仙壇。","寶衣行雨在云端，畫簾深殿，香霧冷风殘。","欲问楚王何处去，翠屏猶掩金鸾。","猨啼明月照空灘，孤舟行客，驚梦亦艱难。"]', '诗', 'shi', '', NULL, '臨江仙 二 閻選 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d92adcb3-734c-45bc-944c-a1a819cc9129', '浣溪沙', '浣溪沙', '45872534-3d7d-442b-a8d5-656fdbbde825', '唐', '["寂寞流蘇冷繡茵，倚屏山枕惹香塵，小庭花露泣濃春。","劉阮信非仙洞客，嫦娥終是月中人，此生無路訪東鄰。"]', '["寂寞流蘇冷繡茵，倚屏山枕惹香塵，小庭花露泣濃春。","劉阮信非仙洞客，嫦娥終是月中人，此生無路訪东鄰。"]', '诗', 'shi', '', NULL, '浣溪沙 閻選 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31845bea-cac9-4019-9aaf-78353e309f44', '八拍蠻 一', '八拍蠻 一', '45872534-3d7d-442b-a8d5-656fdbbde825', '唐', '["雲鎖嫩黃煙柳細，風吹紅蔕雪梅殘。","光影不勝閨閣恨，行行坐坐黛眉攢。"]', '["云鎖嫩黄煙柳細，风吹紅蔕雪梅殘。","光影不勝閨閣恨，行行坐坐黛眉攢。"]', '诗', 'shi', '', NULL, '八拍蠻 一 閻選 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5714d257-717e-4a98-a8aa-6da4306c4406', '八拍蠻 二', '八拍蠻 二', '45872534-3d7d-442b-a8d5-656fdbbde825', '唐', '["愁鎖黛眉煙易慘，淚飄紅臉粉難勻。","憔悴不知緣底事，遇人推道不宜春。"]', '["愁鎖黛眉煙易慘，泪飄紅臉粉难勻。","憔悴不知緣底事，遇人推道不宜春。"]', '诗', 'shi', '', NULL, '八拍蠻 二 閻選 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c49a658-3d33-45bc-9dd4-94368e83ccea', '河傳', '河傳', '45872534-3d7d-442b-a8d5-656fdbbde825', '唐', '["秋雨，秋雨。","無晝無夜，滴滴霏霏。","暗燈涼簟怨分離，妖姬不勝悲。","西風稍急喧窗竹，停又續，膩臉懸雙玉。","幾回邀約雁來時，違期，雁歸，人不歸。"]', '["秋雨，秋雨。","無晝無夜，滴滴霏霏。","暗灯涼簟怨分離，妖姬不勝悲。","西风稍急喧窗竹，停又續，膩臉懸雙玉。","幾回邀約雁来时，違期，雁归，人不归。"]', '诗', 'shi', '', NULL, '河傳 閻選 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30935d92-e742-4a19-bc1a-8864899ec8f8', '謁金門', '謁金门', '45872534-3d7d-442b-a8d5-656fdbbde825', '唐', '["美人浴，碧沼蓮開芬馥。","雙髻綰雲顏似玉，素娥輝淡綠。","雅態芳姿閑淑，雪映鈿裝金斛。","水濺青絲珠斷續，酥融香透肉。"]', '["美人浴，碧沼蓮开芬馥。","雙髻綰云顏似玉，素娥輝淡綠。","雅態芳姿闲淑，雪映鈿裝金斛。","水濺青絲珠斷續，酥融香透肉。"]', '诗', 'shi', '', NULL, '謁金門 閻選 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecb6781b-0d4e-4572-a38f-745de09d1fde', '定風波', '定风波', '45872534-3d7d-442b-a8d5-656fdbbde825', '唐', '["江水沈沈帆影過，游魚到晚透寒波。","渡口雙雙飛白鳥，煙嫋，蘆花深處隱漁歌。","扁舟短櫂歸蘭浦，人去，蕭蕭竹徑透青莎。","深夜無風新雨歇，涼月，露迎珠顆入圓荷。"]', '["江水沈沈帆影過，游鱼到晚透寒波。","渡口雙雙飞白鸟，煙嫋，蘆花深处隐漁歌。","扁舟短櫂归蘭浦，人去，蕭蕭竹徑透青莎。","深夜無风新雨歇，涼月，露迎珠顆入圓荷。"]', '诗', 'shi', '', NULL, '定風波 閻選 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b69ffca-1b10-48e2-8b0d-b34c03c13d63', '竹枝 一', '竹枝 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["門前春水白蘋花，岸上無人小艇斜。","商女經過江欲暮，散拋殘食飼神鵶。"]', '["门前春水白蘋花，岸上無人小艇斜。","商女經過江欲暮，散拋殘食飼神鵶。"]', '诗', 'shi', '', NULL, '竹枝 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d6c1a07-33ca-4305-bd6d-e9ded88011d3', '竹枝 二', '竹枝 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["亂繩千結絆人深，越羅萬丈表長尋。","楊柳在身垂意緒，藕花落盡見蓮心。"]', '["亂繩千結絆人深，越羅万丈表长尋。","楊柳在身垂意緒，藕花落尽见蓮心。"]', '诗', 'shi', '', NULL, '竹枝 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2c357cb-9a9d-4322-bca0-f3203a9f7dee', '浣溪沙 一', '浣溪沙 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["蓼岸風多橘柚香，江邊一望楚天長，片帆煙際閃孤光。","目送征鴻飛杳杳，思隨流水去茫茫，蘭紅波碧憶瀟湘。"]', '["蓼岸风多橘柚香，江邊一望楚天长，片帆煙際閃孤光。","目送征鴻飞杳杳，思隨流水去茫茫，蘭紅波碧憶瀟湘。"]', '诗', 'shi', '', NULL, '浣溪沙 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d2a7b2a-a1df-490c-8b7e-0d25064a83f3', '浣溪沙 二', '浣溪沙 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["桃杏風香簾幕閑，謝家門戶約花關，畫梁幽語燕初還。","繡閣數行題了壁，曉屏一枕酒醒山，却疑身是夢雲間。"]', '["桃杏风香簾幕闲，謝家门戶約花关，畫梁幽語燕初還。","繡閣數行題了壁，晓屏一枕酒醒山，却疑身是梦云间。"]', '诗', 'shi', '', NULL, '浣溪沙 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46f89c35-c0f4-4950-a354-493dda57ce5a', '浣溪沙 三', '浣溪沙 三', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["花漸凋疎不耐風，畫簾垂地晚堂空，墮階縈蘚舞愁紅。","膩粉半黏金靨子，殘香猶煖繡薰籠，蕙心無處與人同。"]', '["花漸凋疎不耐风，畫簾垂地晚堂空，墮階縈蘚舞愁紅。","膩粉半黏金靨子，殘香猶煖繡薰籠，蕙心無处與人同。"]', '诗', 'shi', '', NULL, '浣溪沙 三 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d7b331b-d180-4f6e-a1b1-e611d94899d5', '浣溪沙 四', '浣溪沙 四', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["攬鏡無言淚欲流，凝情半日嬾梳頭，一庭疎雨溼春愁。","楊柳祗知傷怨別，杏花應信損嬌羞，淚霑魂斷軫離憂。"]', '["攬镜無言泪欲流，凝情半日嬾梳头，一庭疎雨溼春愁。","楊柳祗知傷怨別，杏花應信損嬌羞，泪霑魂斷軫離憂。"]', '诗', 'shi', '', NULL, '浣溪沙 四 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11a2ee36-eca7-4461-b30d-9aff17862cba', '浣溪沙 五', '浣溪沙 五', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["半踏長裾宛約行，晚簾疎處見分明，此時堪恨昧平生。","早是[銷]魂殘燭影，更愁聞著品弦聲，杳無消息若爲情。"]', '["半踏长裾宛約行，晚簾疎处见分明，此时堪恨昧平生。","早是[銷]魂殘燭影，更愁闻著品弦声，杳無消息若爲情。"]', '诗', 'shi', '', NULL, '浣溪沙 五 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('728c2dea-54d0-46f5-975c-5468995294d6', '浣溪沙 六', '浣溪沙 六', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["蘭沐初休曲檻前，暖風遲日洗頭天，濕雲新斂未梳蟬。","翠袂半將遮粉臆，寶釵長欲墜香肩，此時模樣不禁憐。"]', '["蘭沐初休曲檻前，暖风遲日洗头天，濕云新斂未梳蟬。","翠袂半將遮粉臆，寶釵长欲墜香肩，此时模樣不禁怜。"]', '诗', 'shi', '', NULL, '浣溪沙 六 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ecfab6d-7c9c-454d-94c7-2047c688a4a8', '浣溪沙 七', '浣溪沙 七', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["風遞殘香出繡簾，團窠金鳳舞襜襜，落花微雨恨相兼。","何處去來狂太甚，空推宿酒睡無厭，爭教人不別猜嫌。"]', '["风遞殘香出繡簾，團窠金鳳舞襜襜，落花微雨恨相兼。","何处去来狂太甚，空推宿酒睡無厭，爭教人不別猜嫌。"]', '诗', 'shi', '', NULL, '浣溪沙 七 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc3956e-a90f-4921-becb-bc6ad5461589', '浣溪沙 八', '浣溪沙 八', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["輕打銀箏墜燕泥，斷絲高罥畫樓西，花冠閑上午牆啼。","粉籜半開新竹徑，紅苞盡落舊桃蹊，不堪終日閉深閨。"]', '["轻打銀箏墜燕泥，斷絲高罥畫楼西，花冠闲上午牆啼。","粉籜半开新竹徑，紅苞尽落旧桃蹊，不堪終日閉深閨。"]', '诗', 'shi', '', NULL, '浣溪沙 八 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377b6f08-190a-41af-880f-323d04a71ce1', '浣溪沙 九', '浣溪沙 九', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["烏帽斜欹倒佩魚，靜街偷步訪仙居，隔牆應認打門初。","將見客時微掩斂，得人憐處且生疎，低頭羞問壁邊書。"]', '["烏帽斜欹倒佩鱼，静街偷步訪仙居，隔牆應認打门初。","將见客时微掩斂，得人怜处且生疎，低头羞问壁邊书。"]', '诗', 'shi', '', NULL, '浣溪沙 九 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c3cdcc7-9a45-4d9a-af7f-e98337cea86c', '浣溪沙 十', '浣溪沙 十', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["風撼芳菲滿院香，四簾慵卷日初長，鬢雲垂枕嚮微鍠。","春夢未成愁寂寂，佳期難會信茫茫。","萬般心，千點淚，泣蘭堂。"]', '["风撼芳菲满院香，四簾慵卷日初长，鬢云垂枕嚮微鍠。","春梦未成愁寂寂，佳期难會信茫茫。","万般心，千点泪，泣蘭堂。"]', '诗', 'shi', '', NULL, '浣溪沙 十 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1af4e30b-2cac-4518-be26-f507b2561610', '浣溪沙 十一', '浣溪沙 十一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["碧玉衣裳白玉人，翠眉紅臉小腰身，瑞雲飛雨逐行雲。","除却弄珠兼解佩，便隨西子與東鄰，是誰容易比真真。"]', '["碧玉衣裳白玉人，翠眉紅臉小腰身，瑞云飞雨逐行云。","除却弄珠兼解佩，便隨西子與东鄰，是誰容易比真真。"]', '诗', 'shi', '', NULL, '浣溪沙 十一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96fa4159-84ef-4c2c-9716-97b82be0a404', '浣溪沙 十二', '浣溪沙 十二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["何事相逢不展眉，苦將情分惡猜疑，眼前行止想應知。","半恨半嗔回面處，和嬌和淚泥人時，萬般饒得爲憐伊。"]', '["何事相逢不展眉，苦將情分惡猜疑，眼前行止想應知。","半恨半嗔回面处，和嬌和泪泥人时，万般饒得爲怜伊。"]', '诗', 'shi', '', NULL, '浣溪沙 十二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7b007ab-302a-4908-ba5f-431a9d1dda54', '浣溪沙 十三', '浣溪沙 十三', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["落絮飛花滿帝城，看看春盡又傷情，歲華頻度想堪驚。","風月豈惟今日恨，煙霄終待此身榮，未甘虛老負平生。"]', '["落絮飞花满帝城，看看春尽又傷情，歲华頻度想堪驚。","风月豈惟今日恨，煙霄終待此身榮，未甘虛老負平生。"]', '诗', 'shi', '', NULL, '浣溪沙 十三 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3ab0e52-98aa-41ee-a6f7-d3433e3c2f6e', '浣溪沙 十四', '浣溪沙 十四', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["靜想離愁暗淚零，欲棲雲雨計難成，少年多是薄情人。"]', '["静想離愁暗泪零，欲棲云雨計难成，少年多是薄情人。"]', '诗', 'shi', '', NULL, '浣溪沙 十四 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be63ad1e-b608-4688-bf9d-38297c9d9c5a', '浣溪沙 十五', '浣溪沙 十五', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["試問於誰分最多，便隨人意轉橫波，縷金衣上小雙鵝。","醉後愛稱嬌姐姐，夜來留得好哥哥，不知情事久長麽。"]', '["試问於誰分最多，便隨人意轉橫波，縷金衣上小雙鵝。","醉後愛稱嬌姐姐，夜来留得好哥哥，不知情事久长麽。"]', '诗', 'shi', '', NULL, '浣溪沙 十五 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('713960ff-e843-4900-bfd4-2ee42e74449f', '浣溪沙 十六', '浣溪沙 十六', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["葉墜空階折早秋，細煙輕霧鎖妝樓，寸心雙淚慘嬌羞。","風月但牽魂夢苦，歲華偏感別離愁，恨和相憶兩難酬。"]', '["葉墜空階折早秋，細煙轻霧鎖妝楼，寸心雙泪慘嬌羞。","风月但牽魂梦苦，歲华偏感別離愁，恨和相憶兩难酬。"]', '诗', 'shi', '', NULL, '浣溪沙 十六 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cea9bf0-654f-4319-94a4-f3c9779c621a', '浣溪沙 十七', '浣溪沙 十七', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["月淡風和畫閣深，露桃煙柳影相侵，斂眉凝緒夜沈沈。"]', '["月淡风和畫閣深，露桃煙柳影相侵，斂眉凝緒夜沈沈。"]', '诗', 'shi', '', NULL, '浣溪沙 十七 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c77d5646-0a85-4320-824c-9cf083d80e92', '浣溪沙 十八', '浣溪沙 十八', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["自入春來月夜稀，今宵蟾彩倍凝輝，強開襟抱出簾帷。","囓指暗思花下約，凭闌羞覩淚痕衣，薄情狂蕩幾時歸。"]', '["自入春来月夜稀，今宵蟾彩倍凝輝，強开襟抱出簾帷。","囓指暗思花下約，凭闌羞覩泪痕衣，薄情狂蕩幾时归。"]', '诗', 'shi', '', NULL, '浣溪沙 十八 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b592eacf-3d4f-4592-aea1-1b4109ed33d1', '浣溪沙 十九', '浣溪沙 十九', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["十五年來錦岸遊，未曾行處不風流，好花長與萬金酬。","滿眼利名渾信運，一生狂蕩恐難休，且陪煙月醉紅樓。"]', '["十五年来錦岸游，未曾行处不风流，好花长與万金酬。","满眼利名渾信運，一生狂蕩恐难休，且陪煙月醉紅楼。"]', '诗', 'shi', '', NULL, '浣溪沙 十九 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70749194-b1b9-4cac-a0eb-e27896d13d3b', '河傳 一', '河傳 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["太平天子，等閑遊戲，疏河千里。","柳如絲，偎倚，綠波春水，長淮風不起。","如花殿脚三千女，爭雲雨，何處留人住？","錦帆風，煙際紅，燒空，魂迷大業中。"]', '["太平天子，等闲游戲，疏河千里。","柳如絲，偎倚，綠波春水，长淮风不起。","如花殿脚三千女，爭云雨，何处留人住？","錦帆风，煙際紅，燒空，魂迷大業中。"]', '诗', 'shi', '', NULL, '河傳 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b57b23b5-6394-4e55-974f-3113249193c6', '河傳 二', '河傳 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["柳拖金縷，著煙籠霧，濛濛落絮。","鳳皇舟上楚女，妙舞，雷喧波上鼓。","龍爭虎戰分中土，人無主，桃葉江南渡。","襞花牋，豔思牽，成篇，宮娥相與傳。"]', '["柳拖金縷，著煙籠霧，濛濛落絮。","鳳皇舟上楚女，妙舞，雷喧波上鼓。","龙爭虎戰分中土，人無主，桃葉江南渡。","襞花牋，豔思牽，成篇，宮娥相與傳。"]', '诗', 'shi', '', NULL, '河傳 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e713966-2aa8-4483-8ab0-f26fcffe5695', '河傳 三', '河傳 三', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["花落，煙薄，謝家池閣，寂寞春深。","翠蛾輕斂意沈吟，霑襟，無人知此心。","玉爐香斷霜灰冷，簾鋪影，梁燕歸紅杏。","晚來天，空悄然，孤眠，枕檀雲髻偏。"]', '["花落，煙薄，謝家池閣，寂寞春深。","翠蛾轻斂意沈吟，霑襟，無人知此心。","玉爐香斷霜灰冷，簾鋪影，梁燕归紅杏。","晚来天，空悄然，孤眠，枕檀云髻偏。"]', '诗', 'shi', '', NULL, '河傳 三 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4899fc8-c230-4553-83ac-152dfc1f269f', '河傳 四', '河傳 四', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["風颭，波斂，團荷閃閃，珠傾露點。","木蘭舟上，何處吳娃越豔，藕花紅照臉。","大堤狂殺襄陽客，煙波隔，渺渺湖光白。","身已歸，心不歸，斜暉，遠汀鸂鶒飛。"]', '["风颭，波斂，團荷閃閃，珠傾露点。","木蘭舟上，何处吳娃越豔，藕花紅照臉。","大堤狂殺襄陽客，煙波隔，渺渺湖光白。","身已归，心不归，斜暉，远汀鸂鶒飞。"]', '诗', 'shi', '', NULL, '河傳 四 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19669525-bb28-4fae-8284-c377cf28dc13', '菩薩鬘 一', '菩薩鬘 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["月華如水籠香砌，金鐶碎撼門初閉。","寒影墮高簷，鉤垂一面簾。","碧煙輕嫋嫋，紅戰燈花笑。","即此是高唐，掩屏秋夢長。"]', '["月华如水籠香砌，金鐶碎撼门初閉。","寒影墮高簷，鉤垂一面簾。","碧煙轻嫋嫋，紅戰灯花笑。","即此是高唐，掩屏秋梦长。"]', '诗', 'shi', '', NULL, '菩薩鬘 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1787888d-1009-488a-9e88-4fff5686ae36', '菩薩鬘 二', '菩薩鬘 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["花冠頻鼓牆頭翼，東方澹白連窗色。","門外早鶯聲，背樓殘月明。","薄寒籠醉態，依舊鉛華在。","握手送人歸，半拖金縷衣。"]', '["花冠頻鼓牆头翼，东方澹白連窗色。","门外早鶯声，背楼殘月明。","薄寒籠醉態，依旧鉛华在。","握手送人归，半拖金縷衣。"]', '诗', 'shi', '', NULL, '菩薩鬘 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f160c40-ef41-4f75-980d-20cbb2205ff0', '菩薩鬘 三', '菩薩鬘 三', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["小庭花落無人掃，疎香滿地東風老。","春晚信沈沈，天涯何處尋。","曉堂屏六扇，眉共湘山遠。","爭奈別離心，近來尤不禁。"]', '["小庭花落無人掃，疎香满地东风老。","春晚信沈沈，天涯何处尋。","晓堂屏六扇，眉共湘山远。","爭奈別離心，近来尤不禁。"]', '诗', 'shi', '', NULL, '菩薩鬘 三 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e196927-ec2a-4838-957c-2a0164c9b4e6', '菩薩鬘 四', '菩薩鬘 四', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["青嵒碧洞經朝雨，隔花相喚南溪去。","一隻木蘭船，波平遠浸天。","扣船驚翡翠，嫩玉擡香臂。","紅日欲沈西，煙中遙解觿。"]', '["青嵒碧洞經朝雨，隔花相喚南溪去。","一隻木蘭船，波平远浸天。","扣船驚翡翠，嫩玉擡香臂。","紅日欲沈西，煙中遙解觿。"]', '诗', 'shi', '', NULL, '菩薩鬘 四 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('543e1b87-45c3-438f-bd58-ad49c2bae031', '菩薩鬘 五', '菩薩鬘 五', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["木綿花映叢祠小，越禽聲裏春光曉。","銅鼓與蠻歌，南人祈賽多。","客帆風正急，茜袖偎檣立。","極浦幾回頭，煙波無限愁。"]', '["木綿花映叢祠小，越禽声裏春光晓。","銅鼓與蠻歌，南人祈賽多。","客帆风正急，茜袖偎檣立。","極浦幾回头，煙波無限愁。"]', '诗', 'shi', '', NULL, '菩薩鬘 五 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('394a5165-aece-4176-aa06-aa753527dc18', '河瀆神 一', '河瀆神 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["汾水碧依依，黃雲落葉初飛。","翠娥一去不言歸，廟門空掩斜暉。","四壁陰森排古畫，依舊瓊輪羽駕。","小殿沈沈清夜，銀燈飄落香灺。"]', '["汾水碧依依，黄云落葉初飞。","翠娥一去不言归，廟门空掩斜暉。","四壁陰森排古畫，依旧瓊輪羽駕。","小殿沈沈清夜，銀灯飄落香灺。"]', '诗', 'shi', '', NULL, '河瀆神 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e13d2a99-01ec-4a6b-b06d-2cad293f01c3', '河瀆神 二', '河瀆神 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["江上草芊芊，春晚湘妃廟前。","一方卵色楚南天，數行斜雁聯翩。","獨倚朱闌情不極，魂斷終朝相憶。","兩槳不知消息，遠汀時起鸂鶒。"]', '["江上草芊芊，春晚湘妃廟前。","一方卵色楚南天，數行斜雁聯翩。","独倚朱闌情不極，魂斷終朝相憶。","兩槳不知消息，远汀时起鸂鶒。"]', '诗', 'shi', '', NULL, '河瀆神 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3154487f-3653-40b0-ab2e-fe4d28b85749', '虞美人 一', '虞美人 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["紅窗寂寂無人語，暗淡棃花雨。","繡羅紋地粉新描，博山香炷旋抽條，睡魂銷。","天涯一去無消息，終日長相憶。","教人相憶幾時休，不堪棖觸別離愁，淚還流。"]', '["紅窗寂寂無人語，暗淡棃花雨。","繡羅紋地粉新描，博山香炷旋抽條，睡魂銷。","天涯一去無消息，終日长相憶。","教人相憶幾时休，不堪棖觸別離愁，泪還流。"]', '诗', 'shi', '', NULL, '虞美人 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db30835-283e-4f6c-bf37-73808a24d5d8', '虞美人 二', '虞美人 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["好風微揭簾旌起，金翼鸞相倚。","翠簷愁聽乳禽聲，此時春態暗關情，獨難平。","畫堂流水空相翳，一穗香搖曳。","教人無處寄相思，落花芳草過前期，沒人知。"]', '["好风微揭簾旌起，金翼鸾相倚。","翠簷愁听乳禽声，此时春態暗关情，独难平。","畫堂流水空相翳，一穗香搖曳。","教人無处寄相思，落花芳草過前期，沒人知。"]', '诗', 'shi', '', NULL, '虞美人 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5b0cba7-68e3-4fc2-833f-492609473aab', '後庭花 一', '後庭花 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["景陽鐘動宮鶯轉，露涼金殿。","輕飆吹起瓊花綻，玉葉如剪。","晚來高閣上，珠簾卷。","見墜香千片，修蛾慢臉陪雕輦，後庭新宴。"]', '["景陽鐘动宮鶯轉，露涼金殿。","轻飆吹起瓊花綻，玉葉如剪。","晚来高閣上，珠簾卷。","见墜香千片，修蛾慢臉陪雕輦，後庭新宴。"]', '诗', 'shi', '', NULL, '後庭花 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc9365c-2851-4723-8853-976273a30ae8', '後庭花 二', '後庭花 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["石城依舊空江國，故宮春色。","七尺青絲芳草綠，絕世難得。","玉英凋落盡，更何人識。","野棠如織，只是教人添怨憶，悵望無極。"]', '["石城依旧空江国，故宮春色。","七尺青絲芳草綠，絕世难得。","玉英凋落尽，更何人識。","野棠如织，只是教人添怨憶，悵望無極。"]', '诗', 'shi', '', NULL, '後庭花 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f4112b7-6c67-4481-954d-59fc039e7c03', '生查子 一', '生查子 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["寂寞掩朱門，正是天將暮。","暗澹小庭中，滴滴梧桐雨。","繡工夫，牽心緒，配盡鴛鴦縷。","待得沒人時，偎倚論私語。"]', '["寂寞掩朱门，正是天將暮。","暗澹小庭中，滴滴梧桐雨。","繡工夫，牽心緒，配尽鴛鴦縷。","待得沒人时，偎倚論私語。"]', '诗', 'shi', '', NULL, '生查子 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afea507b-1980-45f5-9353-7d9f2eec8ee7', '生查子 二', '生查子 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["暖日策花驄，嚲鞚垂楊陌。","芳草惹煙青，落絮隨風白。","誰家繡轂動香塵，隱映神仙客。","狂殺玉鞭郎，咫尺音容隔。"]', '["暖日策花驄，嚲鞚垂楊陌。","芳草惹煙青，落絮隨风白。","誰家繡轂动香塵，隐映神仙客。","狂殺玉鞭郎，咫尺音容隔。"]', '诗', 'shi', '', NULL, '生查子 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b99aa4b-0499-400d-92f3-5fdb88b91ae2', '生查子 三', '生查子 三', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["金井墮高梧，玉殿籠斜月。","永巷寂無人，斂態愁堪絕。","玉爐寒，香燼滅，還似君恩歇。","翠輦不歸來，幽恨將誰說。"]', '["金井墮高梧，玉殿籠斜月。","永巷寂無人，斂態愁堪絕。","玉爐寒，香燼滅，還似君恩歇。","翠輦不归来，幽恨將誰说。"]', '诗', 'shi', '', NULL, '生查子 三 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d180a80-faee-4e11-a417-6e909785a5fd', '生查子 四', '生查子 四', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["春病與春愁，何事年年有。","半爲枕前人，半爲花間酒。","醉金尊，攜玉手，共作鴛鴦偶。","倒載臥雲屏，雪面腰如柳。"]', '["春病與春愁，何事年年有。","半爲枕前人，半爲花间酒。","醉金尊，携玉手，共作鴛鴦偶。","倒載臥云屏，雪面腰如柳。"]', '诗', 'shi', '', NULL, '生查子 四 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c6c08c0-1ca4-491e-bad1-f5f63cd963ae', '生查子 五', '生查子 五', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["爲惜美人嬌，長有如花笑。","半醉倚紅妝，轉語傳青鳥。","眷方深，憐恰好，唯恐相逢少。","似這一般情，肯信春光老。"]', '["爲惜美人嬌，长有如花笑。","半醉倚紅妝，轉語傳青鸟。","眷方深，怜恰好，唯恐相逢少。","似這一般情，肯信春光老。"]', '诗', 'shi', '', NULL, '生查子 五 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8395e94b-bc01-41ba-b91b-27c3eb57b3b5', '生查子 六', '生查子 六', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["清曉牡丹芳，紅豔凝金蘂。","乍占錦江春，永認笙歌地。","感人心，爲物瑞，爛熳煙花裏。","戴上玉釵時，迥與凡花異。"]', '["清晓牡丹芳，紅豔凝金蘂。","乍占錦江春，永認笙歌地。","感人心，爲物瑞，爛熳煙花裏。","戴上玉釵时，迥與凡花異。"]', '诗', 'shi', '', NULL, '生查子 六 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a2482f-4f3b-4c4a-a68f-2b207d9f37d8', '生查子 七', '生查子 七', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["密雨阻佳期，盡日凝然坐。","簾外正淋漓，不覺愁如鎖。","夢難裁，心欲破，淚逐簷聲墜。","想得玉人情，也合思量我。"]', '["密雨阻佳期，尽日凝然坐。","簾外正淋漓，不覺愁如鎖。","梦难裁，心欲破，泪逐簷声墜。","想得玉人情，也合思量我。"]', '诗', 'shi', '', NULL, '生查子 七 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50be5375-735b-4fcc-99d8-709a8d1e2205', '臨江仙 一', '臨江仙 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["霜拍井梧乾葉墮，翠幃雕檻初寒。","薄鉛殘黛稱花冠，含情無語，延佇倚闌干。","杳杳征輪何處去，離愁別恨千般。","不堪心緒正多端，鏡匳長掩，無意對孤鸞。"]', '["霜拍井梧乾葉墮，翠幃雕檻初寒。","薄鉛殘黛稱花冠，含情無語，延佇倚闌干。","杳杳征輪何处去，離愁別恨千般。","不堪心緒正多端，镜匳长掩，無意对孤鸾。"]', '诗', 'shi', '', NULL, '臨江仙 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cbf927c-c896-4026-906d-41595be3d4a0', '臨江仙 二', '臨江仙 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["暮雨淒淒深院閉，燈前凝坐初更。","玉釵低壓鬢雲橫，半垂羅幕，相映燭光明。","終是有心投漢珮，低頭但理秦箏。","燕雙鸞偶不勝情，只愁明發，將逐楚雲行。"]', '["暮雨淒淒深院閉，灯前凝坐初更。","玉釵低壓鬢云橫，半垂羅幕，相映燭光明。","終是有心投漢珮，低头但理秦箏。","燕雙鸾偶不勝情，只愁明發，將逐楚云行。"]', '诗', 'shi', '', NULL, '臨江仙 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f38187-7868-4643-9b20-94359f6d925d', '酒泉子 一', '酒泉子 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["空磧無邊，萬里陽關道路。","馬蕭蕭，人去去，隴雲愁。","香貂舊製戎衣窄，胡霜千里白。","綺羅心，魂夢隔，上高樓。"]', '["空磧無邊，万里陽关道路。","马蕭蕭，人去去，隴云愁。","香貂旧製戎衣窄，胡霜千里白。","綺羅心，魂梦隔，上高楼。"]', '诗', 'shi', '', NULL, '酒泉子 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7be7bd72-35f5-41e5-a91d-9a534b50d755', '酒泉子 二', '酒泉子 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["曲檻小樓，正是鶯花二月。","思無憀，愁欲絕，鬱離襟。","展屏空對瀟湘水，眼前千萬里。","淚掩紅，眉斂翠，恨沈沈。"]', '["曲檻小楼，正是鶯花二月。","思無憀，愁欲絕，鬱離襟。","展屏空对瀟湘水，眼前千万里。","泪掩紅，眉斂翠，恨沈沈。"]', '诗', 'shi', '', NULL, '酒泉子 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('421cd718-6070-4dd9-8f49-2f7a46914bad', '酒泉子 三', '酒泉子 三', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["斂態窗前，嫋嫋雀釵拋頸。","燕成雙，鸞對影，偶新知。","玉纖澹拂眉山小，鏡中嗔共照。","翠連娟，紅縹緲，早妝時。"]', '["斂態窗前，嫋嫋雀釵拋頸。","燕成雙，鸾对影，偶新知。","玉纖澹拂眉山小，镜中嗔共照。","翠連娟，紅縹緲，早妝时。"]', '诗', 'shi', '', NULL, '酒泉子 三 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf5133f-4eb8-4d2a-8911-8860946158f8', '清平樂 一', '清平乐 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["愁腸欲斷，正是青春半。","連理分枝鸞失伴，又是一場離散。","掩鏡無語眉低，思隨芳草淒淒。","憑仗東風吹夢，與郎終日東西。"]', '["愁腸欲斷，正是青春半。","連理分枝鸾失伴，又是一場離散。","掩镜無語眉低，思隨芳草淒淒。","憑仗东风吹梦，與郎終日东西。"]', '诗', 'shi', '', NULL, '清平樂 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d07768-5f4b-4498-91be-23d7221a33e4', '清平樂 二', '清平乐 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["等閑無語，春恨如何去。","終是疎狂留不住，花暗柳濃何處。","盡日目斷魂飛，晚窗斜界殘暉。","長恨朱門薄暮，繡鞍驄馬空歸。"]', '["等闲無語，春恨如何去。","終是疎狂留不住，花暗柳濃何处。","尽日目斷魂飞，晚窗斜界殘暉。","长恨朱门薄暮，繡鞍驄马空归。"]', '诗', 'shi', '', NULL, '清平樂 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04f277e7-6a2b-4b30-8c85-ec5c936bda8e', '更漏子 一', '更漏子 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["聽寒更，聞遠雁，半夜蕭娘深院。","扃繡戶，下珠簾，滿庭噴玉蟾。","人語靜，香閨冷，紅幕半垂清影。","雲雨態，蕙蘭心，此情江海深。"]', '["听寒更，闻远雁，半夜蕭娘深院。","扃繡戶，下珠簾，满庭噴玉蟾。","人語静，香閨冷，紅幕半垂清影。","云雨態，蕙蘭心，此情江海深。"]', '诗', 'shi', '', NULL, '更漏子 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c1d321-c92b-4dac-8e94-8abe4f63a4ef', '更漏子 二', '更漏子 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["今夜期，來日別，相對祗堪愁絕。","偎粉面，撚瑤簪，無言淚滿襟。","銀箭落，霜華薄，牆外曉雞咿喔。","聽付屬，惡情悰，斷腸西復東。"]', '["今夜期，来日別，相对祗堪愁絕。","偎粉面，撚瑤簪，無言泪满襟。","銀箭落，霜华薄，牆外晓雞咿喔。","听付屬，惡情悰，斷腸西复东。"]', '诗', 'shi', '', NULL, '更漏子 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('068220f3-50dd-4943-95ff-3d6f12850ca2', '更漏子 三', '更漏子 三', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["燭熒煌，香旖旎，閑放一堆鴛被。","慵就寢，獨無憀，相思魂欲銷。","不會得，這心力，判了依前還憶。","空自怨，奈伊何，別來情更多。"]', '["燭熒煌，香旖旎，闲放一堆鴛被。","慵就寢，独無憀，相思魂欲銷。","不會得，這心力，判了依前還憶。","空自怨，奈伊何，別来情更多。"]', '诗', 'shi', '', NULL, '更漏子 三 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0153e0ff-5bfd-4804-9bf1-10ff1d30f0ef', '更漏子 四', '更漏子 四', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["掌中珠，心上氣，愛惜豈將容易。","花下月，枕前人，此生誰更親。","交頸語，合歡身，便同比目金鱗。","連繡枕，臥紅茵，霜天似暖春。"]', '["掌中珠，心上氣，愛惜豈將容易。","花下月，枕前人，此生誰更親。","交頸語，合歡身，便同比目金鱗。","連繡枕，臥紅茵，霜天似暖春。"]', '诗', 'shi', '', NULL, '更漏子 四 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f4cc9d6-6106-4c8d-9a13-1fd2643a15a7', '更漏子 五', '更漏子 五', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["對秋深，離恨苦，數夜滿庭風雨。","凝想坐，斂愁眉，孤心似有違。","紅窗靜，畫簾垂，魂消地角天涯。","和淚聽，斷腸窺，漏移燈暗時。"]', '["对秋深，離恨苦，數夜满庭风雨。","凝想坐，斂愁眉，孤心似有違。","紅窗静，畫簾垂，魂消地角天涯。","和泪听，斷腸窺，漏移灯暗时。"]', '诗', 'shi', '', NULL, '更漏子 五 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('213a3ad1-7539-4aa0-bc1a-900f001174b6', '更漏子 六', '更漏子 六', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["求君心，風韻別，渾似一團煙月。","歌皓齒，舞紅籌，花時醉上樓。","能婉媚，解嬌羞，王孫忍不攀留。","惟我恨，未綢繆，相思魂夢愁。"]', '["求君心，风韻別，渾似一團煙月。","歌皓齒，舞紅籌，花时醉上楼。","能婉媚，解嬌羞，王孫忍不攀留。","惟我恨，未綢繆，相思魂梦愁。"]', '诗', 'shi', '', NULL, '更漏子 六 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d2b0906-839a-43b2-8d08-eefa9908c4c5', '女冠子 一', '女冠子 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["蕙風芝露，壇際殘香輕度，蘂珠宮。","苔點分圓碧，桃花踐破紅。","品流巫峽外，名籍紫微中。","真侶墉城會，夢魂通。"]', '["蕙风芝露，壇際殘香轻度，蘂珠宮。","苔点分圓碧，桃花踐破紅。","品流巫峽外，名籍紫微中。","真侶墉城會，梦魂通。"]', '诗', 'shi', '', NULL, '女冠子 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f91609b-67ed-4649-b593-bed683fa0f83', '女冠子 二', '女冠子 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["淡花瘦玉，依約神仙妝束，佩瓊文。","瑞露通宵貯，幽香盡日焚。","碧紗籠絳節，黃藕冠濃雲。","勿以吹簫伴，不同羣。"]', '["淡花瘦玉，依約神仙妝束，佩瓊文。","瑞露通宵貯，幽香尽日焚。","碧紗籠絳節，黄藕冠濃云。","勿以吹簫伴，不同羣。"]', '诗', 'shi', '', NULL, '女冠子 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e8e48e4-1836-4b6a-8667-63d9fa9cee60', '風流子 一', '风流子 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["茅舍槿籬溪曲，雞犬自南自北。","菰葉長，水葓開，門外春波漲淥。","聽織，聲促，軋軋鳴梭穿屋。"]', '["茅舍槿籬溪曲，雞犬自南自北。","菰葉长，水葓开，门外春波漲淥。","听织，声促，軋軋鳴梭穿屋。"]', '诗', 'shi', '', NULL, '風流子 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('811221b6-718f-47b8-ba41-c6b1794e98c7', '風流子 二', '风流子 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["樓倚長衢欲暮，瞥見神仙伴侶。","微傅粉，攏梳頭，隱映畫簾開處。","無語，無緒，慢曳羅帬歸去。"]', '["楼倚长衢欲暮，瞥见神仙伴侶。","微傅粉，攏梳头，隐映畫簾开处。","無語，無緒，慢曳羅帬归去。"]', '诗', 'shi', '', NULL, '風流子 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aafdfd6c-c5b7-4860-ba6f-47aeb1b0c8b0', '風流子 三', '风流子 三', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["金絡玉銜嘶馬，繫向綠楊陰下。","朱戶掩，繡簾垂，曲院水流花謝。","歡罷，歸也，猶在九衢深夜。"]', '["金絡玉銜嘶马，繫向綠楊陰下。","朱戶掩，繡簾垂，曲院水流花謝。","歡罷，归也，猶在九衢深夜。"]', '诗', 'shi', '', NULL, '風流子 三 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de489a0-40a3-4b04-959c-8dfb24899a52', '定西番 一', '定西番 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["雞祿山前遊騎，邊草白，朔天明，馬蹄輕。","鵲面弓離短韔，彎來月欲成，一隻鳴𩩉雲外，曉鴻驚。"]', '["雞祿山前游騎，邊草白，朔天明，马蹄轻。","鵲面弓離短韔，彎来月欲成，一隻鳴𩩉云外，晓鴻驚。"]', '诗', 'shi', '', NULL, '定西番 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30d04a6f-e6d4-443a-b04d-49b68e65a885', '定西番 二', '定西番 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["帝子枕前秋夜，霜幄冷，月華明，正三更。","何處戍樓寒笛，夢殘聞一聲，遙想漢關萬里，淚縱橫。"]', '["帝子枕前秋夜，霜幄冷，月华明，正三更。","何处戍楼寒笛，梦殘闻一声，遙想漢关万里，泪縱橫。"]', '诗', 'shi', '', NULL, '定西番 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5836f69-97cc-4787-9b99-ff8ccf6c0c91', '何滿子', '何满子', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["冠劒不隨君去，江河還共恩深。","歌袖半遮眉黛慘，淚珠旋滴衣襟。"]', '["冠劒不隨君去，江河還共恩深。","歌袖半遮眉黛慘，泪珠旋滴衣襟。"]', '诗', 'shi', '', NULL, '何滿子 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16a17e34-c361-4342-a02f-85d67b057fbc', '玉胡蝶', '玉胡蝶', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["春欲盡，景仍長，滿園花正黃。","粉翅兩悠颺，翩翩過短牆。","鮮飆暖，牽遊伴，飛去立殘芳。","無語對蕭娘，舞衫沈麝香。"]', '["春欲尽，景仍长，满园花正黄。","粉翅兩悠颺，翩翩過短牆。","鲜飆暖，牽游伴，飞去立殘芳。","無語对蕭娘，舞衫沈麝香。"]', '诗', 'shi', '', NULL, '玉胡蝶 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9ce51fb-b1fd-43d5-9c5f-d8dcb261a1ba', '八拍蠻', '八拍蠻', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["孔雀尾拖金線長，怕人飛起入丁香。","越女沙頭爭拾翠，相呼歸去背斜陽。"]', '["孔雀尾拖金線长，怕人飞起入丁香。","越女沙头爭拾翠，相呼归去背斜陽。"]', '诗', 'shi', '', NULL, '八拍蠻 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3829100-0c2b-4189-bc42-a38649662e09', '思帝鄉', '思帝乡', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["如何，遣情情更多。","永日水堂簾下，斂羞蛾。","六幅羅帬窣地，微行曳碧波。","看盡滿池疎雨，打團荷。"]', '["如何，遣情情更多。","永日水堂簾下，斂羞蛾。","六幅羅帬窣地，微行曳碧波。","看尽满池疎雨，打團荷。"]', '诗', 'shi', '', NULL, '思帝鄉 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c46976-9c2b-4207-8951-aded0e39110a', '上行杯 一', '上行杯 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["草草離亭鞍馬，從遠道，此地分襟。","燕宋秦吳千萬里，無辭一醉。","野棠開，江草溼。","佇立，霑泣，征騎駸駸。"]', '["草草離亭鞍马，從远道，此地分襟。","燕宋秦吳千万里，無辞一醉。","野棠开，江草溼。","佇立，霑泣，征騎駸駸。"]', '诗', 'shi', '', NULL, '上行杯 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d70809f6-34dc-488f-9933-dbc70e9e5a67', '上行杯 二', '上行杯 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["離櫂逡巡欲動，臨極浦，故人相送。","去住心情知不共，金船滿捧。","綺羅愁，絲管咽。","回別，帆影滅，江浪如雪。"]', '["離櫂逡巡欲动，臨極浦，故人相送。","去住心情知不共，金船满捧。","綺羅愁，絲管咽。","回別，帆影滅，江浪如雪。"]', '诗', 'shi', '', NULL, '上行杯 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d50bcc4-6bfd-4f1e-b37f-c680fec2a4d3', '謁金門', '謁金门', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["留不得，留得也應無益。","白紵春衫如雪色，揚州初去日。","輕別離，甘拋擲，江上滿帆風疾。","却羨綵鴛三十六，孤鸞還一隻。"]', '["留不得，留得也應無益。","白紵春衫如雪色，揚州初去日。","轻別離，甘拋擲，江上满帆风疾。","却羨綵鴛三十六，孤鸾還一隻。"]', '诗', 'shi', '', NULL, '謁金門 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d204a543-56dd-4738-ba3c-e96c01a361d8', '思越人 一', '思越人 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["古臺平，芳草遠，館娃宮外春深。","翠黛空留千載恨，教人何處相尋？","綺羅無復當時事，露花點滴香淚。","惆悵遙天橫淥水，鴛鴦對對飛起。"]', '["古台平，芳草远，館娃宮外春深。","翠黛空留千載恨，教人何处相尋？","綺羅無复當时事，露花点滴香泪。","惆悵遙天橫淥水，鴛鴦对对飞起。"]', '诗', 'shi', '', NULL, '思越人 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('626cd0d4-c1a1-434f-b3d1-a378d4842677', '思越人 二', '思越人 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["渚蓮枯，宮樹老，長洲廢苑蕭條。","想像玉人空處所，月明獨上溪橋。","經春初敗秋風起，紅蘭綠蕙愁死。","一片風流傷心地，魂銷目斷西子。"]', '["渚蓮枯，宮樹老，长洲廢苑蕭條。","想像玉人空处所，月明独上溪橋。","經春初敗秋风起，紅蘭綠蕙愁死。","一片风流傷心地，魂銷目斷西子。"]', '诗', 'shi', '', NULL, '思越人 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27fb5def-5bc1-4bde-93b9-2f62411bf40c', '望梅花', '望梅花', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["數枝開與短牆平，見雪萼。","紅跗相映，引起誰人邊塞情。","簾外欲三更，吹斷離愁月正明，空聽隔江聲。"]', '["數枝开與短牆平，见雪萼。","紅跗相映，引起誰人邊塞情。","簾外欲三更，吹斷離愁月正明，空听隔江声。"]', '诗', 'shi', '', NULL, '望梅花 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e0bd74f-e386-4a4b-9d14-f8235ccf0a87', '漁歌子 一', '漁歌子 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["草芊芊，波漾漾，湖邊草色連波漲。","沿蓼岸，泊楓汀，天際玉輪初上。","扣舷歌，聯極望，槳聲伊軋知何向。","黃鵠叫，白鷗眠，誰似儂家疎曠。"]', '["草芊芊，波漾漾，湖邊草色連波漲。","沿蓼岸，泊楓汀，天際玉輪初上。","扣舷歌，聯極望，槳声伊軋知何向。","黄鵠叫，白鷗眠，誰似儂家疎曠。"]', '诗', 'shi', '', NULL, '漁歌子 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('108aa664-25b3-4400-baf7-cc05efdaf331', '漁歌子 二', '漁歌子 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["泛流螢，明又滅，夜涼水冷東灣闊。","風浩浩，笛寥寥，萬頃金波重疊。","杜若洲，香郁烈，一聲宿雁霜時節。","經霅水，過松江，盡屬儂家日月。"]', '["泛流螢，明又滅，夜涼水冷东灣闊。","风浩浩，笛寥寥，万頃金波重叠。","杜若洲，香郁烈，一声宿雁霜时節。","經霅水，過松江，尽屬儂家日月。"]', '诗', 'shi', '', NULL, '漁歌子 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32853d6d-60e8-4ff6-b4fd-860f9e3fbeac', '定風波', '定风波', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["簾拂疎香斷碧絲，淚衫還滴繡黃鸝。","上國獻書人不在，凝黛，晚庭又是落紅時。","春日自長心自促，翻覆，年來年去負前期。","應是秦雲兼楚雨，留住，向花枝誇說月中枝。"]', '["簾拂疎香斷碧絲，泪衫還滴繡黄鸝。","上国獻书人不在，凝黛，晚庭又是落紅时。","春日自长心自促，翻覆，年来年去負前期。","應是秦云兼楚雨，留住，向花枝誇说月中枝。"]', '诗', 'shi', '', NULL, '定風波 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6173b152-6691-44c1-948a-cd22f5be77ef', '南歌子 一', '南歌子 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["豔冶青樓女，風流似楚真。","驪珠美玉未爲珍，窈窕一枝芳柳，入腰身。","舞袖頻回雪，歌聲幾動塵。","慢凝秋水顧情人，祗緣傾國，著處覺生春。"]', '["豔冶青楼女，风流似楚真。","驪珠美玉未爲珍，窈窕一枝芳柳，入腰身。","舞袖頻回雪，歌声幾动塵。","慢凝秋水顧情人，祗緣傾国，著处覺生春。"]', '诗', 'shi', '', NULL, '南歌子 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fbe092f-1eda-4089-8c93-cd1ae2e4a04f', '南歌子 二', '南歌子 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["映月論心處，偎花見面時。","倚郎和袖撫香肌，遙指畫堂深院，許相期。","解佩君非晚，虛襟我未遲。","願如連理合歡枝，不似五陵狂蕩，薄情兒。"]', '["映月論心处，偎花见面时。","倚郎和袖撫香肌，遙指畫堂深院，許相期。","解佩君非晚，虛襟我未遲。","願如連理合歡枝，不似五陵狂蕩，薄情兒。"]', '诗', 'shi', '', NULL, '南歌子 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79dc061a-9acf-4aa8-8d6d-88d5da46fdf5', '應天長', '應天长', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["翠凝仙豔非凡有，窈窕年華方十九。","鬢如雲，腰似柳，妙對綺弦歌醁酒。","醉瑤臺，攜玉手。","共燕此宵相偶，魂斷晚窗分首，淚霑金縷袖。"]', '["翠凝仙豔非凡有，窈窕年华方十九。","鬢如云，腰似柳，妙对綺弦歌醁酒。","醉瑤台，携玉手。","共燕此宵相偶，魂斷晚窗分首，泪霑金縷袖。"]', '诗', 'shi', '', NULL, '應天長 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b4a825d-13aa-49fc-8522-ebc5c09a07c8', '遐方怨', '遐方怨', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["紅綬帶，錦香囊。","爲表花前意，慇懃贈玉郎。","此時更役心腸，轉添秋夜夢魂狂。","思豔質，想嬌妝。","願早傳金盞，同歡臥醉鄉。","任人猜妬惡猜防，到頭須使似鴛鴦。"]', '["紅綬带，錦香囊。","爲表花前意，慇懃贈玉郎。","此时更役心腸，轉添秋夜梦魂狂。","思豔質，想嬌妝。","願早傳金盞，同歡臥醉乡。","任人猜妬惡猜防，到头須使似鴛鴦。"]', '诗', 'shi', '', NULL, '遐方怨 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcf02abb-8930-444a-84f5-fb04bfc519d4', '浣溪沙 一', '浣溪沙 一', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["鈿轂香車過柳堤，樺煙分處馬頻嘶，爲他沈醉不成泥。","花滿驛亭香露細，杜鵑聲斷玉蟾低，含情無語倚樓西。"]', '["鈿轂香车過柳堤，樺煙分处马頻嘶，爲他沈醉不成泥。","花满驛亭香露細，杜鵑声斷玉蟾低，含情無語倚楼西。"]', '诗', 'shi', '', NULL, '浣溪沙 一 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92ece33e-701c-4bbe-b2c5-551a4602574f', '浣溪沙 二', '浣溪沙 二', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["馬上凝情憶舊遊，照花淹竹小溪流，鈿箏羅幕玉搔頭。","早是出門長帶月，可堪分袂又經秋，晚風斜日不勝愁。"]', '["马上凝情憶旧游，照花淹竹小溪流，鈿箏羅幕玉搔头。","早是出门长带月，可堪分袂又經秋，晚风斜日不勝愁。"]', '诗', 'shi', '', NULL, '浣溪沙 二 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb6be6b6-e651-426d-bdec-501e13d0ab0e', '浣溪沙 三', '浣溪沙 三', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["獨立寒堦望月華，露濃香泛小庭花，繡屏愁背一燈斜。","雲雨自從分散後，人間無路到仙家，但憑魂夢訪天涯。"]', '["独立寒堦望月华，露濃香泛小庭花，繡屏愁背一灯斜。","云雨自從分散後，人间無路到仙家，但憑魂梦訪天涯。"]', '诗', 'shi', '', NULL, '浣溪沙 三 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a8a0efd-59e0-4ecb-942a-d43868b6afa1', '浣溪沙 四', '浣溪沙 四', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["依約殘眉理舊黃，翠鬟拋擲一簪長，暖風晴日罷朝妝。","閑折海棠看又撚，玉纖無力惹餘香，此情誰會倚斜陽。"]', '["依約殘眉理旧黄，翠鬟拋擲一簪长，暖风晴日罷朝妝。","闲折海棠看又撚，玉纖無力惹餘香，此情誰會倚斜陽。"]', '诗', 'shi', '', NULL, '浣溪沙 四 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eb0030b-6ac0-4f78-87e9-0ff25da32c21', '浣溪沙 五', '浣溪沙 五', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["翡翠屏開繡幄紅，謝娥無力曉妝慵，錦帷鴛被宿香濃。","微雨小庭春寂寞，燕飛鶯語隔簾櫳，杏花凝恨倚東風。"]', '["翡翠屏开繡幄紅，謝娥無力晓妝慵，錦帷鴛被宿香濃。","微雨小庭春寂寞，燕飞鶯語隔簾櫳，杏花凝恨倚东风。"]', '诗', 'shi', '', NULL, '浣溪沙 五 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e28fe108-7e4d-459f-9457-d1d44ecd39e5', '浣溪沙 六', '浣溪沙 六', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["花月香寒悄夜塵，綺筵幽會暗傷神，嬋娟依約畫屏人。","人不見時還暫語，令纔拋後愛微嚬，越羅巴錦不勝春。"]', '["花月香寒悄夜塵，綺筵幽會暗傷神，嬋娟依約畫屏人。","人不见时還暫語，令纔拋後愛微嚬，越羅巴錦不勝春。"]', '诗', 'shi', '', NULL, '浣溪沙 六 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('871bf875-199f-45e3-8718-937d02523c0b', '浣溪沙 七', '浣溪沙 七', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["偏戴花冠白玉簪，睡容新起意沈吟，翠鈿金縷鎮眉心。","小檻日斜風悄悄，隔簾零落杏花陰，斷香輕碧鎖愁深。"]', '["偏戴花冠白玉簪，睡容新起意沈吟，翠鈿金縷鎮眉心。","小檻日斜风悄悄，隔簾零落杏花陰，斷香轻碧鎖愁深。"]', '诗', 'shi', '', NULL, '浣溪沙 七 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5330b8f1-c330-47db-9137-b28d256d3ccb', '浣溪沙 八', '浣溪沙 八', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["晚逐香車入鳳城，東風斜揭繡簾輕，慢回嬌眼笑盈盈。","消息未通何計是，便須佯醉且隨行，依稀聞道太狂生。"]', '["晚逐香车入鳳城，东风斜揭繡簾轻，慢回嬌眼笑盈盈。","消息未通何計是，便須佯醉且隨行，依稀闻道太狂生。"]', '诗', 'shi', '', NULL, '浣溪沙 八 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46fa3b83-9ff3-42c7-98cc-d57f8640fa75', '浣溪沙 九', '浣溪沙 九', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["小市東門欲雪天，衆中依約見神仙，蘂黃香畫貼金蟬。","飲散黃昏人草草，醉容無語立門前，馬嘶塵烘一街煙。"]', '["小市东门欲雪天，衆中依約见神仙，蘂黄香畫貼金蟬。","饮散黄昏人草草，醉容無語立门前，马嘶塵烘一街煙。"]', '诗', 'shi', '', NULL, '浣溪沙 九 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8cc214b-7903-4582-a8e1-c1a74964583c', '臨江仙', '臨江仙', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["煙收湘渚秋江靜，蕉花露泣愁紅。","五雲雙鶴去無蹤，幾回魂斷，凝望向長空。","翠竹暗留珠淚怨，閑調寶瑟波中。","花鬟月鬢綠雲重，古祠深殿，香冷雨和風。"]', '["煙收湘渚秋江静，蕉花露泣愁紅。","五云雙鹤去無蹤，幾回魂斷，凝望向长空。","翠竹暗留珠泪怨，闲調寶瑟波中。","花鬟月鬢綠云重，古祠深殿，香冷雨和风。"]', '诗', 'shi', '', NULL, '臨江仙 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c2b8b63-6f4a-460c-8697-ef34807ee6e2', '女冠子', '女冠子', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["露花煙草，寂寞五雲三島。","正春深，貌減潛銷玉，香殘尚惹襟。","竹疎虛檻靜，松密醮壇陰。","何事劉郎去，信沈沈。"]', '["露花煙草，寂寞五云三島。","正春深，貌減潛銷玉，香殘尚惹襟。","竹疎虛檻静，松密醮壇陰。","何事劉郎去，信沈沈。"]', '诗', 'shi', '', NULL, '女冠子 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6cc38b3-d87c-4f7e-93d2-32bd79ca23c4', '河傳 一', '河傳 一', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["渺莽雲水，惆悵暮帆。","去程迢遞，夕陽芳草。","千里萬里，雁聲無限起。","夢魂悄斷煙波裏，心如醉。","相見何處是，錦屏香冷無睡，被頭多少淚。"]', '["渺莽云水，惆悵暮帆。","去程迢遞，夕陽芳草。","千里万里，雁声無限起。","梦魂悄斷煙波裏，心如醉。","相见何处是，錦屏香冷無睡，被头多少泪。"]', '诗', 'shi', '', NULL, '河傳 一 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0700d273-7bca-4217-a0ac-be79397a313e', '河傳 二', '河傳 二', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["紅杏，交枝相映，密密濛濛。","一庭濃豔倚東風，香融，透簾櫳。","斜陽似共春光語，蝶爭舞，更引流鶯妒。","魂銷千片玉罇前，神仙，瑤池醉暮天。"]', '["紅杏，交枝相映，密密濛濛。","一庭濃豔倚东风，香融，透簾櫳。","斜陽似共春光語，蝶爭舞，更引流鶯妒。","魂銷千片玉罇前，神仙，瑤池醉暮天。"]', '诗', 'shi', '', NULL, '河傳 二 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce17839-f467-40f8-ae7e-6db8cdc59b10', '酒泉子 一', '酒泉子 一', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["春雨打窗，驚夢覺來天氣曉。","畫堂深，紅燄小，背蘭缸。","酒香噴鼻嬾開缸，惆悵更無人共醉。","舊巢中，新燕子，語雙雙。"]', '["春雨打窗，驚梦覺来天氣晓。","畫堂深，紅燄小，背蘭缸。","酒香噴鼻嬾开缸，惆悵更無人共醉。","旧巢中，新燕子，語雙雙。"]', '诗', 'shi', '', NULL, '酒泉子 一 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93acbc91-2055-4b68-8388-424e8bf35442', '酒泉子 二', '酒泉子 二', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["紫陌青門，三十六宮春色。","御溝輦路暗相通，杏園風。","咸陽沽酒寶釵空，笑指未央歸去。","插花走馬落殘紅，月明中。"]', '["紫陌青门，三十六宮春色。","御溝輦路暗相通，杏园风。","咸陽沽酒寶釵空，笑指未央归去。","插花走马落殘紅，月明中。"]', '诗', 'shi', '', NULL, '酒泉子 二 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f8f80c-5a3b-494a-8606-034df24c2b48', '生查子', '生查子', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["相見稀，喜相見，相見還相遠。","檀畫荔支紅，金蔓蜻蜓輭。","魚雁疎，芳信斷，花落庭陰晚。","可惜玉肌膚，消瘦成慵嬾。"]', '["相见稀，喜相见，相见還相远。","檀畫荔支紅，金蔓蜻蜓輭。","鱼雁疎，芳信斷，花落庭陰晚。","可惜玉肌膚，消瘦成慵嬾。"]', '诗', 'shi', '', NULL, '生查子 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fac524e-2d9f-40cf-ad96-4a1fec13f629', '思越人', '思越人', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["燕雙飛，鶯百轉，越波堤下長橋。","鬬鈿花筐金匣恰，舞衣羅薄纖腰。","東風澹蕩慵無力，黛眉愁聚春碧。","滿地落花無消息，月明腸斷空憶。"]', '["燕雙飞，鶯百轉，越波堤下长橋。","鬬鈿花筐金匣恰，舞衣羅薄纖腰。","东风澹蕩慵無力，黛眉愁聚春碧。","满地落花無消息，月明腸斷空憶。"]', '诗', 'shi', '', NULL, '思越人 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc19b41-2742-4feb-8d80-ac1dfa1f63a4', '滿宮花', '满宮花', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["花正芳，樓似綺，寂寞上陽宮裏。","鈿籠金鎖睡鴛鴦，簾冷露華珠翠。","嬌豔輕盈香雪膩，細雨黃鶯雙起。","東風惆悵欲清明，公子橋邊沈醉。"]', '["花正芳，楼似綺，寂寞上陽宮裏。","鈿籠金鎖睡鴛鴦，簾冷露华珠翠。","嬌豔轻盈香雪膩，細雨黄鶯雙起。","东风惆悵欲清明，公子橋邊沈醉。"]', '诗', 'shi', '', NULL, '滿宮花 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5596965e-8a0c-41d0-a8fb-c6704be9e67b', '柳枝', '柳枝', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["膩粉瓊妝透碧紗，雪休誇。","金鳳搔頭墜鬢斜，髮交加。","倚著雲屏新睡覺，思夢笑。","紅顋隱出枕函花，有些些。"]', '["膩粉瓊妝透碧紗，雪休誇。","金鳳搔头墜鬢斜，髮交加。","倚著云屏新睡覺，思梦笑。","紅顋隐出枕函花，有些些。"]', '诗', 'shi', '', NULL, '柳枝 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90b7eae-c7ff-4f23-8a44-656fe09e0e1c', '南歌子 一', '南歌子 一', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["柳色遮樓暗，桐花落砌香。","畫堂開處遠風涼，高卷水精簾額，襯斜陽。"]', '["柳色遮楼暗，桐花落砌香。","畫堂开处远风涼，高卷水精簾額，襯斜陽。"]', '诗', 'shi', '', NULL, '南歌子 一 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('886849ba-d1cc-4d99-a299-60afad62c024', '南歌子 二', '南歌子 二', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["岸柳拖烟綠，庭花照日紅。","數聲蜀魄入簾櫳，驚斷碧窗殘夢，畫屏空。"]', '["岸柳拖烟綠，庭花照日紅。","數声蜀魄入簾櫳，驚斷碧窗殘梦，畫屏空。"]', '诗', 'shi', '', NULL, '南歌子 二 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ed9516b-f837-474d-b953-b3de0cb7ab9f', '南歌子 三', '南歌子 三', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["錦薦紅鸂鶒，羅衣繡鳳皇。","綺疎飄雪北風狂，簾幕盡垂無事，鬱金香。"]', '["錦薦紅鸂鶒，羅衣繡鳳皇。","綺疎飄雪北风狂，簾幕尽垂無事，鬱金香。"]', '诗', 'shi', '', NULL, '南歌子 三 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f977537e-5fa2-4592-836d-3edc057d4fda', '江城子 一', '江城子 一', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["碧闌干外小中庭，雨初晴，曉鶯聲。","飛絮落花，時節近清明。","睡起卷簾無一事，勻面了，沒心情。"]', '["碧闌干外小中庭，雨初晴，晓鶯声。","飞絮落花，时節近清明。","睡起卷簾無一事，勻面了，沒心情。"]', '诗', 'shi', '', NULL, '江城子 一 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9ffd6f0-b307-46d9-95f6-e0e3162be772', '江城子 二', '江城子 二', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["浣花溪上見卿卿，臉波秋水明，黛眉輕。","綠雲高綰，金簇小蜻蜓。","好[是]問他來得麽，和笑道，莫多情。"]', '["浣花溪上见卿卿，臉波秋水明，黛眉轻。","綠云高綰，金簇小蜻蜓。","好[是]问他来得麽，和笑道，莫多情。"]', '诗', 'shi', '', NULL, '江城子 二 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15afbf19-5be3-4b97-a4f4-4655d4844b8c', '江城子 三', '江城子 三', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["窄羅衫子薄羅裙，小腰身，晚妝新。","每到花時，長是不宜春。","蚤是自家無氣力，更被你，惡憐人。"]', '["窄羅衫子薄羅裙，小腰身，晚妝新。","每到花时，长是不宜春。","蚤是自家無氣力，更被你，惡怜人。"]', '诗', 'shi', '', NULL, '江城子 三 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ec769b5-2f1c-46cf-8de6-212f148495d6', '河瀆神', '河瀆神', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["古樹噪寒鴉，滿庭楓葉蘆花。","晝燈當午隔輕紗，畫閣珠簾影斜。","門外往來祈賽客，翩翩帆落天涯。","回首隔江煙火，渡頭三兩人家。"]', '["古樹噪寒鴉，满庭楓葉蘆花。","晝灯當午隔轻紗，畫閣珠簾影斜。","门外往来祈賽客，翩翩帆落天涯。","回首隔江煙火，渡头三兩人家。"]', '诗', 'shi', '', NULL, '河瀆神 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('844c56a7-626b-486f-8e48-0f7973719673', '胡蝶兒', '胡蝶兒', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["胡蝶兒，晚春時。","阿嬌初著淡黃衣，倚窗學畫伊。","還似花間見，雙雙對對飛。","無端和淚拭燕脂，惹教雙翅垂。"]', '["胡蝶兒，晚春时。","阿嬌初著淡黄衣，倚窗学畫伊。","還似花间见，雙雙对对飞。","無端和泪拭燕脂，惹教雙翅垂。"]', '诗', 'shi', '', NULL, '胡蝶兒 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88f3e9b2-bd47-438a-a20d-fc52715b69cb', '如夢令', '如梦令', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["塵拂玉臺鸞鏡，鳳髻不堪重整。","綃帳泣流蘇，愁掩玉屏人靜。","多病，多病，自是行雲無定。"]', '["塵拂玉台鸾镜，鳳髻不堪重整。","綃帳泣流蘇，愁掩玉屏人静。","多病，多病，自是行云無定。"]', '诗', 'shi', '', NULL, '如夢令 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4d885c-4073-47a3-b91e-70477b64f9bb', '三臺令 一', '三台令 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["春色，春色，依舊青門紫陌。","日斜柳暗花嫣，醉臥春色少年。","年少，年少，行樂直須及早。"]', '["春色，春色，依旧青门紫陌。","日斜柳暗花嫣，醉臥春色少年。","年少，年少，行乐直須及早。"]', '诗', 'shi', '', NULL, '三臺令 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2985c758-6be5-4096-b642-1a26f5fea351', '三臺令 二', '三台令 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["明月，明月，照得離人愁絕。","更深影入空牀，不道帷屏夜長。","長夜，長夜，夢到庭花陰下。"]', '["明月，明月，照得離人愁絕。","更深影入空牀，不道帷屏夜长。","长夜，长夜，梦到庭花陰下。"]', '诗', 'shi', '', NULL, '三臺令 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10504673-9ec0-4096-80e2-69162b5cdf6c', '三臺令 三', '三台令 三', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["南浦，南浦，翠鬟離人何處？","當時攜手高樓，依舊樓前水流。","流水，流水，中有傷心雙淚。"]', '["南浦，南浦，翠鬟離人何处？","當时携手高楼，依旧楼前水流。","流水，流水，中有傷心雙泪。"]', '诗', 'shi', '', NULL, '三臺令 三 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b5a5cb1-9bc8-4959-bd52-96eacfa88639', '歸國謠 一', '归国謠 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["何處笛，深夜夢回情脈脈。","竹風簷雨寒窗隔，離人幾歲無消息。","今頭白，不眠特地重相憶。"]', '["何处笛，深夜梦回情脈脈。","竹风簷雨寒窗隔，離人幾歲無消息。","今头白，不眠特地重相憶。"]', '诗', 'shi', '', NULL, '歸國謠 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06006bd9-2362-46dd-b738-8185de46caeb', '歸國謠 二', '归国謠 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["春豔豔，江上晚山三四點。","柳絲如剪花如染，香閨寂寂門半掩。","愁眉歛，淚珠滴破臙脂臉。"]', '["春豔豔，江上晚山三四点。","柳絲如剪花如染，香閨寂寂门半掩。","愁眉歛，泪珠滴破臙脂臉。"]', '诗', 'shi', '', NULL, '歸國謠 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ec76dac-5ecd-4374-8f0e-d96ac31d1f2e', '歸國謠 三', '归国謠 三', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["江水碧，江上何人吹玉笛。","扁舟遠送瀟湘客，蘆花千里霜月白。","傷行色，來朝便是關山隔。"]', '["江水碧，江上何人吹玉笛。","扁舟远送瀟湘客，蘆花千里霜月白。","傷行色，来朝便是关山隔。"]', '诗', 'shi', '', NULL, '歸國謠 三 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1853142-c700-4ba2-b056-433cbaae2a27', '長相思', '长相思', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["紅滿枝，綠滿枝，宿雨厭厭睡起遲，閑庭花影移。","憶歸期，數歸期，夢見雖多相見稀，相逢知幾時。"]', '["紅满枝，綠满枝，宿雨厭厭睡起遲，闲庭花影移。","憶归期，數归期，梦见雖多相见稀，相逢知幾时。"]', '诗', 'shi', '', NULL, '長相思 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9b03cf8-e879-4b20-a370-310d10b25007', '相見歡', '相见歡', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["曉窗夢到昭華，向瓊家。","欹枕殘妝一朵，臥枝花。","情極處，却無語，玉釵斜。","翠閣銀屏回首，已天涯。"]', '["晓窗梦到昭华，向瓊家。","欹枕殘妝一朵，臥枝花。","情極处，却無語，玉釵斜。","翠閣銀屏回首，已天涯。"]', '诗', 'shi', '', NULL, '相見歡 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccdd7cca-fc16-412f-8313-7a29fb3c56cb', '拋毬樂 一', '拋毬乐 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["酒罷歌餘興未闌，小橋清水共盤桓。","波搖梅蘂傷心白，風入羅衣貼體寒。","且莫思歸去，須盡笙歌此夕歡。"]', '["酒罷歌餘兴未闌，小橋清水共盤桓。","波搖梅蘂傷心白，风入羅衣貼體寒。","且莫思归去，須尽笙歌此夕歡。"]', '诗', 'shi', '', NULL, '拋毬樂 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a292dd3-c38a-4f6f-897c-80ac28fcfc0b', '拋毬樂 二', '拋毬乐 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["逐勝歸來雨未晴，樓前風重草煙輕。","谷鶯語輭花邊過，水調聲長醉裏聽。","欵舉金觥勸，誰是當筵最有情。"]', '["逐勝归来雨未晴，楼前风重草煙轻。","谷鶯語輭花邊過，水調声长醉裏听。","欵舉金觥勸，誰是當筵最有情。"]', '诗', 'shi', '', NULL, '拋毬樂 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0548f0bb-ca74-4fa6-93bf-c7e8e7b6fce5', '拋毬樂 三', '拋毬乐 三', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["梅落新春入後庭，眼前風物可無情。","曲池波晚冰還合，芳草迎船綠未成。","且上高樓望，相共凭闌看月生。"]', '["梅落新春入後庭，眼前风物可無情。","曲池波晚冰還合，芳草迎船綠未成。","且上高楼望，相共凭闌看月生。"]', '诗', 'shi', '', NULL, '拋毬樂 三 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('536eff4e-5af8-4f57-81b3-913346b8ca4a', '拋毬樂 四', '拋毬乐 四', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["霜積秋山萬樹紅，倚巖樓上掛朱櫳。","白雲天遠重重恨，黃葉煙深淅淅風。","髣髴梁州曲，吹在誰家玉笛中。"]', '["霜積秋山万樹紅，倚巖楼上掛朱櫳。","白云天远重重恨，黄葉煙深淅淅风。","髣髴梁州曲，吹在誰家玉笛中。"]', '诗', 'shi', '', NULL, '拋毬樂 四 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4304599d-3411-479b-9afb-c16b0b92bd22', '拋毬樂 五', '拋毬乐 五', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["盡日登高興未殘，紅樓人散獨盤桓。","一鉤冷霧懸珠箔，滿面西風凭玉闌。","歸去須沈醉，小院新池月乍寒。"]', '["尽日登高兴未殘，紅楼人散独盤桓。","一鉤冷霧懸珠箔，满面西风凭玉闌。","归去須沈醉，小院新池月乍寒。"]', '诗', 'shi', '', NULL, '拋毬樂 五 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebbb2ec5-3e4a-400d-9de4-d3dd3c34093c', '拋毬樂 六', '拋毬乐 六', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["坐對高樓千萬山，鴈飛秋色滿闌干。","燒殘紅燭暮雲合，飄盡碧梧金井寒。","咫尺人千里，猶憶笙歌昨夜歡。"]', '["坐对高楼千万山，鴈飞秋色满闌干。","燒殘紅燭暮云合，飄尽碧梧金井寒。","咫尺人千里，猶憶笙歌昨夜歡。"]', '诗', 'shi', '', NULL, '拋毬樂 六 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c037512-649d-4cbe-9b4c-f254f8c8bd5c', '點絳唇', '点絳唇', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["蔭綠圍紅，夢瓊家在桃源住。","畫橋當路，臨水開朱戶。","柳徑春深，行到關情處。","顰不語，意憑風絮，吹向郎邊去。"]', '["蔭綠圍紅，梦瓊家在桃源住。","畫橋當路，臨水开朱戶。","柳徑春深，行到关情处。","顰不語，意憑风絮，吹向郎邊去。"]', '诗', 'shi', '', NULL, '點絳唇 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6682ebd0-ca24-4b46-bfd7-2a81c9d2d22f', '酒泉子 一', '酒泉子 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["庭下花飛，月照妝樓春事晚。","珠簾風，蘭燭燼，怨空閨。","迢迢何處寄相思，玉筯零零腸斷。","屏幃深，更漏永，夢魂迷。"]', '["庭下花飞，月照妝楼春事晚。","珠簾风，蘭燭燼，怨空閨。","迢迢何处寄相思，玉筯零零腸斷。","屏幃深，更漏永，梦魂迷。"]', '诗', 'shi', '', NULL, '酒泉子 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad47e380-bfb9-4551-9b53-71cfac036094', '酒泉子 二', '酒泉子 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["芳草長川，柳映危橋橋下路。","歸鴻飛，行人去，碧山邊。","風微煙淡雨蕭然，隔岸馬嘶何處？","九回腸，雙臉淚，夕陽天。"]', '["芳草长川，柳映危橋橋下路。","归鴻飞，行人去，碧山邊。","风微煙淡雨蕭然，隔岸马嘶何处？","九回腸，雙臉泪，夕陽天。"]', '诗', 'shi', '', NULL, '酒泉子 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6096b9cd-c1a3-40d5-bffe-6e7d775a7492', '酒泉子 三', '酒泉子 三', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["[春]色融融，飛燕乍來鶯未語。","小桃寒，垂柳晚，玉樓空。","天長煙遠恨重重，消息燕鴻歸去。","枕前燈，窗外月，閉朱籠。"]', '["[春]色融融，飞燕乍来鶯未語。","小桃寒，垂柳晚，玉楼空。","天长煙远恨重重，消息燕鴻归去。","枕前灯，窗外月，閉朱籠。"]', '诗', 'shi', '', NULL, '酒泉子 三 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd951f4-02f4-46a0-a2f1-e84d9ff95540', '酒泉子 四', '酒泉子 四', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["深院空幃，廊下風簾驚宿燕。","香印灰，蘭燭灺，覺來時。","月明人自擣寒衣，剛愛無端惆悵。","階前行，闌外立，欲雞啼。"]', '["深院空幃，廊下风簾驚宿燕。","香印灰，蘭燭灺，覺来时。","月明人自擣寒衣，剛愛無端惆悵。","階前行，闌外立，欲雞啼。"]', '诗', 'shi', '', NULL, '酒泉子 四 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63cd382a-840e-4029-9fb0-7ef393f6b16e', '采桑子 一', '采桑子 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["小庭雨過春將盡，片片花飛，獨折殘枝，無語凭闌秪自知。","玉堂香煖珠簾卷，雙燕來歸，君約佳期，肯信韶華得幾時。"]', '["小庭雨過春將尽，片片花飞，独折殘枝，無語凭闌秪自知。","玉堂香煖珠簾卷，雙燕来归，君約佳期，肯信韶华得幾时。"]', '诗', 'shi', '', NULL, '采桑子 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f585b9-c50d-4157-8e1a-e30bbe7af989', '采桑子 二', '采桑子 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["馬嘶人語春風岸，芳草綿綿，楊柳橋邊，落日高樓酒斾懸。","舊愁新恨知多少，目斷遙天，獨立花前，更聽笙歌滿畫船。"]', '["马嘶人語春风岸，芳草綿綿，楊柳橋邊，落日高楼酒斾懸。","旧愁新恨知多少，目斷遙天，独立花前，更听笙歌满畫船。"]', '诗', 'shi', '', NULL, '采桑子 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae003587-92bd-470a-b2bf-de30b68c70ee', '采桑子 三', '采桑子 三', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["西風半夜簾櫳冷，遠夢初歸，夢過金扉，花謝窗前夜合枝。","昭陽殿裏新翻曲，未有人知，偷取笙吹，驚覺寒蛩到曉啼。"]', '["西风半夜簾櫳冷，远梦初归，梦過金扉，花謝窗前夜合枝。","昭陽殿裏新翻曲，未有人知，偷取笙吹，驚覺寒蛩到晓啼。"]', '诗', 'shi', '', NULL, '采桑子 三 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e874b28-0782-4b78-9b68-edce9374c10e', '采桑子 四', '采桑子 四', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["酒闌睡覺天香煖，繡戶慵開，香印成灰，獨背寒屏理舊眉。","朦朧却向燈前臥，窗月徘徊，曉夢初回，一夜東風綻早梅。"]', '["酒闌睡覺天香煖，繡戶慵开，香印成灰，独背寒屏理旧眉。","朦朧却向灯前臥，窗月徘徊，晓梦初回，一夜东风綻早梅。"]', '诗', 'shi', '', NULL, '采桑子 四 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22107b82-29af-4476-9267-4c413dfdd803', '采桑子 五', '采桑子 五', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["小堂深靜無人到，滿院春風，惆悵牆東，一樹櫻桃帶雨紅。","愁心似醉兼如病，欲語還慵，日暮疎鐘，雙燕歸棲畫閣中。"]', '["小堂深静無人到，满院春风，惆悵牆东，一樹櫻桃带雨紅。","愁心似醉兼如病，欲語還慵，日暮疎鐘，雙燕归棲畫閣中。"]', '诗', 'shi', '', NULL, '采桑子 五 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcce4f6f-97df-429f-8d93-83172191d210', '采桑子 六', '采桑子 六', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["畫堂燈煖簾櫳卷，禁漏丁丁，雨罷寒生，一夜西窗夢不成。","玉娥重起添香印，回倚孤屏，不語含情，水調何人吹笛聲。"]', '["畫堂灯煖簾櫳卷，禁漏丁丁，雨罷寒生，一夜西窗梦不成。","玉娥重起添香印，回倚孤屏，不語含情，水調何人吹笛声。"]', '诗', 'shi', '', NULL, '采桑子 六 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae8d510a-d2a6-418f-86c5-6b9d629c02f2', '采桑子 七', '采桑子 七', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["笙歌放散人歸去，獨宿江樓，月上雲收，一半珠簾掛玉鉤。","起來檢點經遊地，處處新愁，憑仗東流，將取離心過橘州。"]', '["笙歌放散人归去，独宿江楼，月上云收，一半珠簾掛玉鉤。","起来檢点經游地，处处新愁，憑仗东流，將取離心過橘州。"]', '诗', 'shi', '', NULL, '采桑子 七 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a70986a4-8883-4a0a-b8d0-f6388b2a07ad', '采桑子 八', '采桑子 八', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["昭陽記得神仙侶，獨自承恩，水殿燈昏，羅幕輕寒夜正春。","如今別館添蕭索，滿面啼痕，舊約猶存，忍把金環別與人。"]', '["昭陽記得神仙侶，独自承恩，水殿灯昏，羅幕轻寒夜正春。","如今別館添蕭索，满面啼痕，旧約猶存，忍把金环別與人。"]', '诗', 'shi', '', NULL, '采桑子 八 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbaa9b93-3995-4290-9bb7-ed77eabbe4a9', '采桑子 九', '采桑子 九', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["微風簾幕清明近，花落春殘，尊酒留歡，添盡羅衣怯夜寒。","愁顏恰似燒殘燭，珠淚闌干，也欲高拌，爭奈相逢情萬般。"]', '["微风簾幕清明近，花落春殘，尊酒留歡，添尽羅衣怯夜寒。","愁顏恰似燒殘燭，珠泪闌干，也欲高拌，爭奈相逢情万般。"]', '诗', 'shi', '', NULL, '采桑子 九 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('541abfd7-6d17-497e-b915-783944ba3340', '采桑子 十', '采桑子 十', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["畫堂昨夜愁無睡，風雨淒淒，林鵲爭棲，落盡燈花雞未啼。","年光往事如流水，休說情迷，玉筯雙垂，祗是金籠鸚鵡知。"]', '["畫堂昨夜愁無睡，风雨淒淒，林鵲爭棲，落尽灯花雞未啼。","年光往事如流水，休说情迷，玉筯雙垂，祗是金籠鸚鵡知。"]', '诗', 'shi', '', NULL, '采桑子 十 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4414bb27-f21b-423e-9257-32b29116d3cc', '采桑子 十一', '采桑子 十一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["寒蟬欲報三秋候，寂靜幽居，葉落閑階，月透簾櫳遠夢回。","昭陽舊恨依前在，休說當時，玉笛纔吹，滿袖猩猩血又垂。"]', '["寒蟬欲報三秋候，寂静幽居，葉落闲階，月透簾櫳远梦回。","昭陽旧恨依前在，休说當时，玉笛纔吹，满袖猩猩血又垂。"]', '诗', 'shi', '', NULL, '采桑子 十一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0996aebe-f474-42e2-bc8e-805639113c8c', '采桑子 十二', '采桑子 十二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["洞房深夜笙歌散，簾幕重重，斜月朦朧，雨過殘花落地紅。","昔年無限傷心事，依舊東風，獨倚梧桐，閑想閑思到曉鐘。"]', '["洞房深夜笙歌散，簾幕重重，斜月朦朧，雨過殘花落地紅。","昔年無限傷心事，依旧东风，独倚梧桐，闲想闲思到晓鐘。"]', '诗', 'shi', '', NULL, '采桑子 十二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef2f5dfc-6a5f-4dc0-b867-2f751688488b', '采桑子 十三', '采桑子 十三', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["花前失却遊春侶，極目尋芳，滿眼悲涼，縱有笙歌亦斷腸。","林間戲蝶簾間燕，各自雙雙，忍更思量，綠樹青苔半夕陽。"]', '["花前失却游春侶，極目尋芳，满眼悲涼，縱有笙歌亦斷腸。","林间戲蝶簾间燕，各自雙雙，忍更思量，綠樹青苔半夕陽。"]', '诗', 'shi', '', NULL, '采桑子 十三 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d20685bf-a54f-4964-8b46-ec4a785408d8', '菩薩蠻 一', '菩薩蠻 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["金波遠逐行雲去，疎星時作銀河渡。","花影臥秋千，更長人不眠。","玉箏彈未徹，鳳髻黃釵脫。","憶夢翠蛾低，微風吹繡衣。"]', '["金波远逐行云去，疎星时作銀河渡。","花影臥秋千，更长人不眠。","玉箏彈未徹，鳳髻黄釵脫。","憶梦翠蛾低，微风吹繡衣。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c422f547-5ef1-4f78-9a23-0c9f0078e496', '菩薩蠻 二', '菩薩蠻 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["畫堂昨夜西風過，繡簾時拂朱門鎖。","驚夢不成雲，雙蛾枕上顰。","金爐煙嫋嫋，燭暗紗窗曉。","殘日尚彎環，玉箏和淚彈。"]', '["畫堂昨夜西风過，繡簾时拂朱门鎖。","驚梦不成云，雙蛾枕上顰。","金爐煙嫋嫋，燭暗紗窗晓。","殘日尚彎环，玉箏和泪彈。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2c8e84-0958-4523-acfb-32ecf64ffb88', '菩薩蠻 三', '菩薩蠻 三', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["梅花吹入誰家笛，行雲半夜凝空碧。","欹枕不成眠，關山人未還。","聲隨幽怨絕，空斷澄霜月。","月影下重簷，輕風花滿簾。"]', '["梅花吹入誰家笛，行云半夜凝空碧。","欹枕不成眠，关山人未還。","声隨幽怨絕，空斷澄霜月。","月影下重簷，轻风花满簾。"]', '诗', 'shi', '', NULL, '菩薩蠻 三 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('642f6b75-6ca4-4748-be02-1588d9bafe05', '菩薩蠻 四', '菩薩蠻 四', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["回廊遠砌生秋草，夢魂千里青門道。","鸚鵡怨長更，碧籠金鎖橫。","羅幃中夜起，霜月清如水。","玉露不成圓，寶箏悲斷弦。"]', '["回廊远砌生秋草，梦魂千里青门道。","鸚鵡怨长更，碧籠金鎖橫。","羅幃中夜起，霜月清如水。","玉露不成圓，寶箏悲斷弦。"]', '诗', 'shi', '', NULL, '菩薩蠻 四 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('818cb2e4-fab8-4586-8765-76e1b64b2c0e', '菩薩蠻 五', '菩薩蠻 五', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["嬌鬟堆枕釵橫鳳，溶溶春水楊花夢。","紅燭淚闌干，翠屏煙浪寒。","錦壺催畫箭，玉佩天涯遠。","和淚試嚴妝，落梅飛夜霜。"]', '["嬌鬟堆枕釵橫鳳，溶溶春水楊花梦。","紅燭泪闌干，翠屏煙浪寒。","錦壺催畫箭，玉佩天涯远。","和泪試嚴妝，落梅飞夜霜。"]', '诗', 'shi', '', NULL, '菩薩蠻 五 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5ca8cb-54fc-4715-b475-c9ef07b20417', '菩薩蠻 六', '菩薩蠻 六', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["西風嫋嫋凌歌扇，秋期正與行雲遠。","花葉脫霜紅，流螢殘月中。","蘭閨人在否，千里重樓暮。","翠被已銷香，夢隨寒漏長。"]', '["西风嫋嫋凌歌扇，秋期正與行云远。","花葉脫霜紅，流螢殘月中。","蘭閨人在否，千里重楼暮。","翠被已銷香，梦隨寒漏长。"]', '诗', 'shi', '', NULL, '菩薩蠻 六 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b8042c4-9ea3-447b-bded-055466b2d397', '菩薩蠻 七', '菩薩蠻 七', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["沈沈朱戶橫金鎖，紗窗月影隨花過。","燭淚欲闌干，落梅生晚寒。","寶釵橫翠鳳，千里香屏夢。","雲雨已荒涼，江南春草長。"]', '["沈沈朱戶橫金鎖，紗窗月影隨花過。","燭泪欲闌干，落梅生晚寒。","寶釵橫翠鳳，千里香屏梦。","云雨已荒涼，江南春草长。"]', '诗', 'shi', '', NULL, '菩薩蠻 七 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6af04b2-c5bf-45a7-a8ee-03b55f04f726', '菩薩蠻 八', '菩薩蠻 八', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["欹鬟墮髻搖雙槳，采蓮晚出清江上。","顧影約流萍，楚歌嬌未成。","相逢顰翠黛，笑把珠璫解。","家住柳陰中，畫橋東復東。"]', '["欹鬟墮髻搖雙槳，采蓮晚出清江上。","顧影約流萍，楚歌嬌未成。","相逢顰翠黛，笑把珠璫解。","家住柳陰中，畫橋东复东。"]', '诗', 'shi', '', NULL, '菩薩蠻 八 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db30f2d3-22b2-4826-a7c6-e186ebf589bf', '謁金門 一', '謁金门 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["風乍起，吹皺一池春水。","閑引鴛鴦芳徑裏，手挼紅杏蘂。","鬬鴨闌干獨倚，碧玉搔頭斜墜。","終日望君君不至，舉頭聞鵲喜。"]', '["风乍起，吹皺一池春水。","闲引鴛鴦芳徑裏，手挼紅杏蘂。","鬬鴨闌干独倚，碧玉搔头斜墜。","終日望君君不至，舉头闻鵲喜。"]', '诗', 'shi', '', NULL, '謁金門 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('931569e5-6d54-4620-afd7-f0ba0cfd49e0', '謁金門 二', '謁金门 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["楊柳陌，寶馬嘶空無跡。","新著荷衣人未識，年年江海客。","夢覺巫山春色，醉眼飛花狼藉。","起舞不辭無氣力，愛君吹玉笛。"]', '["楊柳陌，寶马嘶空無跡。","新著荷衣人未識，年年江海客。","梦覺巫山春色，醉眼飞花狼藉。","起舞不辞無氣力，愛君吹玉笛。"]', '诗', 'shi', '', NULL, '謁金門 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81e6726-94e5-4a06-af01-68c4e3710f2f', '清平樂 一', '清平乐 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["深冬寒月，庭戶凝霜雪。","風鴈過時魂斷絕，塞管數聲嗚咽。","披衣獨立披香，流蘇亂結愁腸。","往事總堪惆悵，前歡休更思量。"]', '["深冬寒月，庭戶凝霜雪。","风鴈過时魂斷絕，塞管數声嗚咽。","披衣独立披香，流蘇亂結愁腸。","往事總堪惆悵，前歡休更思量。"]', '诗', 'shi', '', NULL, '清平樂 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d62403-11c7-4f1c-b6bc-4026e26b778e', '清平樂 二', '清平乐 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["雨晴煙晚，綠水新池滿。","雙燕飛來垂柳院，小閣畫簾高卷。","黃昏獨倚朱闌，西南新月眉彎。","砌下落花風起，羅衣特地春寒。"]', '["雨晴煙晚，綠水新池满。","雙燕飞来垂柳院，小閣畫簾高卷。","黄昏独倚朱闌，西南新月眉彎。","砌下落花风起，羅衣特地春寒。"]', '诗', 'shi', '', NULL, '清平樂 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f5334cc-54ec-4895-84f7-6bc2b2baefb2', '清平樂 三', '清平乐 三', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["西園春早，夾逕抽新草。","冰散漪瀾生碧沼，寒在梅花先老。","與君同飲金杯，飲餘相取徘徊。","次第小桃將發，軒車莫厭頻來。"]', '["西园春早，夾逕抽新草。","冰散漪瀾生碧沼，寒在梅花先老。","與君同饮金杯，饮餘相取徘徊。","次第小桃將發，軒车莫厭頻来。"]', '诗', 'shi', '', NULL, '清平樂 三 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72170378-5250-49bd-85cb-b12ceb07d520', '更漏子 一', '更漏子 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["風帶寒，枝正好，蘭蕙無端先老。","情悄悄，夢依依，離人殊未歸。","褰羅幕，凭朱閣，不獨堪悲搖落。","月東出，雁南飛，誰家夜擣衣。"]', '["风带寒，枝正好，蘭蕙無端先老。","情悄悄，梦依依，離人殊未归。","褰羅幕，凭朱閣，不独堪悲搖落。","月东出，雁南飞，誰家夜擣衣。"]', '诗', 'shi', '', NULL, '更漏子 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('563ea9ff-2b27-4177-9e95-a33b44448749', '更漏子 二', '更漏子 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["夜初長，人近別，夢覺一窗殘月。","鸚鵡臥，蟪蛄鳴，西風寒未成。","紅蠟燭，彈棋局，牀上畫屏山綠。","褰繡幌，倚瑤琴，前歡淚滴襟。"]', '["夜初长，人近別，梦覺一窗殘月。","鸚鵡臥，蟪蛄鳴，西风寒未成。","紅蠟燭，彈棋局，牀上畫屏山綠。","褰繡幌，倚瑤琴，前歡泪滴襟。"]', '诗', 'shi', '', NULL, '更漏子 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7876129b-6032-4bec-90c1-6844b78a01eb', '更漏子 三', '更漏子 三', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["玉爐煙，紅燭淚，偏對畫堂秋思。","眉翠薄，鬢雲殘，夜長衾枕寒。","梧桐樹，三更雨，不道離情最苦。","一葉葉，一聲聲，空堦滴到明。"]', '["玉爐煙，紅燭泪，偏对畫堂秋思。","眉翠薄，鬢云殘，夜长衾枕寒。","梧桐樹，三更雨，不道離情最苦。","一葉葉，一声声，空堦滴到明。"]', '诗', 'shi', '', NULL, '更漏子 三 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('841e98b3-07a3-4815-bd0d-3a1dabe6d844', '喜遷鶯 一', '喜遷鶯 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["宿鶯啼，鄉夢斷。","春樹曉朦朧，殘燈和燼閉朱櫳，人語隔屏風。","香已寒，燈已絕。","忽憶去年離別，石城花雨倚江樓，波上木蘭舟。"]', '["宿鶯啼，乡梦斷。","春樹晓朦朧，殘灯和燼閉朱櫳，人語隔屏风。","香已寒，灯已絕。","忽憶去年離別，石城花雨倚江楼，波上木蘭舟。"]', '诗', 'shi', '', NULL, '喜遷鶯 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('154fd3b4-3a2e-4e42-b2eb-755350f825fc', '喜遷鶯 二', '喜遷鶯 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["霧濛濛，風淅淅。","楊柳帶疎煙，飄飄輕絮滿南園，牆下草芊綿。","燕初飛，鶯已老。","拂面春風長好，相逢攜酒且高歌，人生得幾何。"]', '["霧濛濛，风淅淅。","楊柳带疎煙，飄飄轻絮满南园，牆下草芊綿。","燕初飞，鶯已老。","拂面春风长好，相逢携酒且高歌，人生得幾何。"]', '诗', 'shi', '', NULL, '喜遷鶯 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56fcccb3-d805-41ab-92d8-1f3f36b5de4e', '阮郎歸 一', '阮郎归 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["南園春半踏青時，風和聞馬嘶。","青梅如豆柳如絲，日長蝴蝶飛。","花露重，草煙低，人家簾幕垂。","鞦韆慵困解羅衣，畫梁雙燕棲。"]', '["南园春半踏青时，风和闻马嘶。","青梅如豆柳如絲，日长蝴蝶飞。","花露重，草煙低，人家簾幕垂。","鞦韆慵困解羅衣，畫梁雙燕棲。"]', '诗', 'shi', '', NULL, '阮郎歸 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe5c2174-97dc-46e4-acd4-518ca15abfd5', '阮郎歸 二', '阮郎归 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["角聲吹斷隴梅枝，孤窗月影低。","塞鴻無限欲驚飛，城烏休夜啼。","尋斷夢，掩深閨，行人去路迷。","門前楊柳綠陰齊，何時聞馬嘶。"]', '["角声吹斷隴梅枝，孤窗月影低。","塞鴻無限欲驚飞，城烏休夜啼。","尋斷梦，掩深閨，行人去路迷。","门前楊柳綠陰齊，何时闻马嘶。"]', '诗', 'shi', '', NULL, '阮郎歸 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c448ff-cf3b-4dff-bf6f-e0b799434d74', '賀聖朝', '賀聖朝', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["金絲帳煖牙牀穩，懷香方寸。","輕顰輕笑，汗珠微透，柳霑花潤。","雲鬟斜墜，春應未已，不勝嬌困。","半欹犀枕，亂纏珠被，轉羞人問。"]', '["金絲帳煖牙牀穩，懷香方寸。","轻顰轻笑，汗珠微透，柳霑花潤。","云鬟斜墜，春應未已，不勝嬌困。","半欹犀枕，亂纏珠被，轉羞人问。"]', '诗', 'shi', '', NULL, '賀聖朝 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d57b6526-261e-4dea-901e-aee34d580371', '應天長', '應天长', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["石城山下桃花綻，宿雨初晴雲未散。","南去棹，北飛鴈，水闊山遙腸欲斷。","倚樓情緒懶，[惆悵]春心無限。","燕度蒹葭風晚，欲歸愁滿面。"]', '["石城山下桃花綻，宿雨初晴云未散。","南去棹，北飞鴈，水闊山遙腸欲斷。","倚楼情緒懶，[惆悵]春心無限。","燕度蒹葭风晚，欲归愁满面。"]', '诗', 'shi', '', NULL, '應天長 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('383f4c6e-6d35-40cf-b38f-07c7efff4227', '醉花間 一', '醉花间 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["獨立堦前星又月，簾櫳偏皎潔。","霜樹盡空枝，腸斷丁香結。","夜深寒不寐，疑恨何曾歇，凭闌干欲折。","兩條玉筯爲君垂，此宵情，誰共說。"]', '["独立堦前星又月，簾櫳偏皎潔。","霜樹尽空枝，腸斷丁香結。","夜深寒不寐，疑恨何曾歇，凭闌干欲折。","兩條玉筯爲君垂，此宵情，誰共说。"]', '诗', 'shi', '', NULL, '醉花間 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d707d6fe-2b8f-4209-929e-860239d08bd4', '醉花間 二', '醉花间 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["月落霜繁深院閉，洞房人正睡。","桐樹倚雕簷，金井臨瑤砌。","曉風寒不啻，獨立成顦顇，閑愁渾未已。","離人心緒自無端，莫思量，休退悔。"]', '["月落霜繁深院閉，洞房人正睡。","桐樹倚雕簷，金井臨瑤砌。","晓风寒不啻，独立成顦顇，闲愁渾未已。","離人心緒自無端，莫思量，休退悔。"]', '诗', 'shi', '', NULL, '醉花間 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc87a16a-2d3d-4996-b546-0858a93d5deb', '芳草渡', '芳草渡', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["梧桐落，蓼花秋。","煙初冷，雨纔收。","蕭條風物正堪愁，人去後，多少恨，在心頭。","燕鴻遠，羌笛怨，渺渺澄波一片。","山如黛，月如鉤。","笙歌散，夢魂斷，倚高樓。"]', '["梧桐落，蓼花秋。","煙初冷，雨纔收。","蕭條风物正堪愁，人去後，多少恨，在心头。","燕鴻远，羌笛怨，渺渺澄波一片。","山如黛，月如鉤。","笙歌散，梦魂斷，倚高楼。"]', '诗', 'shi', '', NULL, '芳草渡 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bf50ee3-438c-4cde-b7d1-addc5b3435e4', '南鄉子 一', '南乡子 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["細雨濕流光，芳草年年與恨長。","煙鎖鳳樓無限事，茫茫，鸞鏡鴛衾兩斷腸。","魂夢任悠揚，睡起楊花滿繡牀。","薄倖不來門半掩，斜陽，負你殘春淚幾行。"]', '["細雨濕流光，芳草年年與恨长。","煙鎖鳳楼無限事，茫茫，鸾镜鴛衾兩斷腸。","魂梦任悠揚，睡起楊花满繡牀。","薄倖不来门半掩，斜陽，負你殘春泪幾行。"]', '诗', 'shi', '', NULL, '南鄉子 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87667899-17f5-43b4-adb0-e3eb3b0a3236', '南鄉子 二', '南乡子 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["細雨泣秋風，金鳳花[殘]滿地紅。","閑[蹙]黛眉慵不語，情緒，寂寞相思知幾許。","玉枕擁孤衾，挹恨還聞歲月深。","簾卷曲房誰共醉，顦顇，惆悵秦樓彈粉淚。"]', '["細雨泣秋风，金鳳花[殘]满地紅。","闲[蹙]黛眉慵不語，情緒，寂寞相思知幾許。","玉枕擁孤衾，挹恨還闻歲月深。","簾卷曲房誰共醉，顦顇，惆悵秦楼彈粉泪。"]', '诗', 'shi', '', NULL, '南鄉子 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edfac3cf-27cf-42e0-90ab-e9a8238aebbf', '舞春風', '舞春风', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["嚴妝纔罷怨春風，粉牆畫壁宋家東。","蕙蘭有恨枝尤綠，桃李無言花自紅。","燕燕巢兒羅幕卷，鶯鶯啼處鳳樓空。","少年薄倖知何處，每夜歸來春夢中。"]', '["嚴妝纔罷怨春风，粉牆畫壁宋家东。","蕙蘭有恨枝尤綠，桃李無言花自紅。","燕燕巢兒羅幕卷，鶯鶯啼处鳳楼空。","少年薄倖知何处，每夜归来春梦中。"]', '诗', 'shi', '', NULL, '舞春風 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61d856b5-781d-4528-8aa4-af17582cc44d', '虞美人 一', '虞美人 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["玉鉤鸞柱調鸚鵡，宛轉留春語。","雲屏冷落畫堂空，薄晚春寒，無奈落花風。","搴簾燕子低飛去，拂鏡塵鸞舞。","不知今夜月眉彎，誰佩同心雙結，倚闌干。"]', '["玉鉤鸾柱調鸚鵡，宛轉留春語。","云屏冷落畫堂空，薄晚春寒，無奈落花风。","搴簾燕子低飞去，拂镜塵鸾舞。","不知今夜月眉彎，誰佩同心雙結，倚闌干。"]', '诗', 'shi', '', NULL, '虞美人 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bcc3825-58cc-4634-8827-13ef623a8067', '虞美人 二', '虞美人 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["春風拂拂橫秋水，掩映遙相對。","秪知長作碧窗期，誰信東風，吹散彩雲飛。","銀屏夢與飛鸞遠，秪有珠簾卷。","楊花零落月溶溶，塵掩玉箏弦柱，畫堂空。"]', '["春风拂拂橫秋水，掩映遙相对。","秪知长作碧窗期，誰信东风，吹散彩云飞。","銀屏梦與飞鸾远，秪有珠簾卷。","楊花零落月溶溶，塵掩玉箏弦柱，畫堂空。"]', '诗', 'shi', '', NULL, '虞美人 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57cf05b6-5a03-4fc4-9765-4fc9739844aa', '臨江仙', '臨江仙', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["冷紅飄起桃花片，青春意緒闌珊。","高樓簾幕卷輕寒，酒餘人散，獨自倚闌干。","夕陽千里連芳草，風光愁殺王孫。","徘徊飛盡碧天雲，鳳城何處，明月照黃昏。"]', '["冷紅飄起桃花片，青春意緒闌珊。","高楼簾幕卷轻寒，酒餘人散，独自倚闌干。","夕陽千里連芳草，风光愁殺王孫。","徘徊飞尽碧天云，鳳城何处，明月照黄昏。"]', '诗', 'shi', '', NULL, '臨江仙 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bfbacc6-26af-4fd4-a645-7d7ab1cb011d', '蝶戀花 一', '蝶戀花 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["窗外寒雞天欲曙，香印成灰，坐起渾無緒。","庭際高梧凝宿霧，卷簾雙鵲驚飛去。","屏上羅衣閑繡縷，一晌關情，憶遍江南路。","夜夜夢魂休謾語，已知前事無情處。"]', '["窗外寒雞天欲曙，香印成灰，坐起渾無緒。","庭際高梧凝宿霧，卷簾雙鵲驚飞去。","屏上羅衣闲繡縷，一晌关情，憶遍江南路。","夜夜梦魂休謾語，已知前事無情处。"]', '诗', 'shi', '', NULL, '蝶戀花 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b513b4f5-7c33-4fa5-9707-88ddb7556b4c', '蝶戀花 二', '蝶戀花 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["蕭索清秋珠淚墜，枕簟微涼，展轉渾無寐。","殘酒欲醒中夜起，月明如練天如水。","堦下寒聲啼絡緯，庭樹金風，悄悄重門閉。","可惜舊歡攜手地，思量一夕成憔悴。"]', '["蕭索清秋珠泪墜，枕簟微涼，展轉渾無寐。","殘酒欲醒中夜起，月明如練天如水。","堦下寒声啼絡緯，庭樹金风，悄悄重门閉。","可惜旧歡携手地，思量一夕成憔悴。"]', '诗', 'shi', '', NULL, '蝶戀花 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31af4498-2d1e-42e3-851a-d31d5393d4ef', '蝶戀花 三', '蝶戀花 三', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["幾度鳳樓同飲宴，此夕相逢，却勝當時見。","低語前歡頻轉面，雙眉歛恨春山遠。","蠟燭淚流羌笛怨，偷整羅衣，欲唱情猶嬾。","醉裏不辭金爵滿，陽關一曲腸千斷。"]', '["幾度鳳楼同饮宴，此夕相逢，却勝當时见。","低語前歡頻轉面，雙眉歛恨春山远。","蠟燭泪流羌笛怨，偷整羅衣，欲唱情猶嬾。","醉裏不辞金爵满，陽关一曲腸千斷。"]', '诗', 'shi', '', NULL, '蝶戀花 三 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a221be8-63a7-4fe7-83db-54828ac8f9d5', '蝶戀花 四', '蝶戀花 四', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["幾日行雲何處去，忘了歸來，不道春將暮。","百草千花寒食路，香車繫在誰家樹。","淚眼倚樓頻獨語，雙燕飛來，陌上相逢否。","撩亂春愁如柳絮，悠悠夢裏無尋處。"]', '["幾日行云何处去，忘了归来，不道春將暮。","百草千花寒食路，香车繫在誰家樹。","泪眼倚楼頻独語，雙燕飞来，陌上相逢否。","撩亂春愁如柳絮，悠悠梦裏無尋处。"]', '诗', 'shi', '', NULL, '蝶戀花 四 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca6c25dd-5fd3-4242-bf68-bad5312e11c4', '蝶戀花 五', '蝶戀花 五', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["六曲闌干偎碧樹，楊柳風輕，展盡黃金縷。","誰把鈿箏移玉柱，穿簾海燕雙飛去。","滿眼遊絲兼落絮，紅杏開時，一霎清明雨。","濃醉覺來鶯亂語，驚殘好夢無尋處。"]', '["六曲闌干偎碧樹，楊柳风轻，展尽黄金縷。","誰把鈿箏移玉柱，穿簾海燕雙飞去。","满眼游絲兼落絮，紅杏开时，一霎清明雨。","濃醉覺来鶯亂語，驚殘好梦無尋处。"]', '诗', 'shi', '', NULL, '蝶戀花 五 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfe5f1fe-47bd-45f0-ba58-efb8eff03cec', '蝶戀花 六', '蝶戀花 六', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["誰道閑情拋棄久，每到春來，惆悵還依舊。","日日花前常病酒，不辭鏡裏朱顏瘦。","河畔青蕪堤上柳，爲問新愁，何事年年有。","獨立小樓風滿袖，平林新月人歸後。"]', '["誰道闲情拋棄久，每到春来，惆悵還依旧。","日日花前常病酒，不辞镜裏朱顏瘦。","河畔青蕪堤上柳，爲问新愁，何事年年有。","独立小楼风满袖，平林新月人归後。"]', '诗', 'shi', '', NULL, '蝶戀花 六 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17121e57-7aa3-4a1d-90e5-3bc53b694574', '壽山曲', '壽山曲', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["銅壺滴漏初盡，高閤雞鳴半空。","[催啓]五門金鎖，猶垂三殿簾櫳。","階前御柳搖綠，仗下宮花散紅。","鴛瓦數行曉日，[鸞]旗百尺春風。","侍臣舞蹈重拜，聖壽南山永同。"]', '["銅壺滴漏初尽，高閤雞鳴半空。","[催啓]五门金鎖，猶垂三殿簾櫳。","階前御柳搖綠，仗下宮花散紅。","鴛瓦數行晓日，[鸾]旗百尺春风。","侍臣舞蹈重拜，聖壽南山永同。"]', '诗', 'shi', '', NULL, '壽山曲 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e4aef7d-28c9-4235-be1f-cab5397b48ae', '思越人', '思越人', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["酒醒情懷惡，金縷褪，玉肌如削。","寒食過却，海棠零落。","乍倚遍，闌干煙淡薄，翠幕簾櫳畫閣。","春睡著，覺來失，鞦韆期約。"]', '["酒醒情懷惡，金縷褪，玉肌如削。","寒食過却，海棠零落。","乍倚遍，闌干煙淡薄，翠幕簾櫳畫閣。","春睡著，覺来失，鞦韆期約。"]', '诗', 'shi', '', NULL, '思越人 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c467c217-d0b3-45fc-98a0-37b9b432f15e', '上行杯', '上行杯', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["落梅暑雨消殘粉，雲重煙深寒食近。","羅幕遮香，柳外鞦韆出畫牆。","春山顛倒釵橫鳳，飛絮入簾春睡重。","夢裏佳期，秪許庭花與月知。"]', '["落梅暑雨消殘粉，云重煙深寒食近。","羅幕遮香，柳外鞦韆出畫牆。","春山顛倒釵橫鳳，飞絮入簾春睡重。","梦裏佳期，秪許庭花與月知。"]', '诗', 'shi', '', NULL, '上行杯 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02b45ec9-2f4d-41ed-8c68-9253f5ac222b', '薄命妾', '薄命妾', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["春日宴，綠酒一杯歌一遍，再拜陳三願。","一願郎君千歲，二願妾身長健，三願如同梁上燕，歲歲長相見。"]', '["春日宴，綠酒一杯歌一遍，再拜陳三願。","一願郎君千歲，二願妾身长健，三願如同梁上燕，歲歲长相见。"]', '诗', 'shi', '', NULL, '薄命妾 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da17c64c-6313-4b73-9989-64a262ab3af8', '金錯刀 一', '金錯刀 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["雙玉斗，百瓊壺，佳人歡飲笑喧呼。","麒麟欲畫時難偶，鷗鷺何猜興不孤。","歌婉轉，醉模糊，高燒銀燭臥流蘇。","只銷幾覺懵騰睡，身外功名任有無。"]', '["雙玉斗，百瓊壺，佳人歡饮笑喧呼。","麒麟欲畫时难偶，鷗鷺何猜兴不孤。","歌婉轉，醉模糊，高燒銀燭臥流蘇。","只銷幾覺懵腾睡，身外功名任有無。"]', '诗', 'shi', '', NULL, '金錯刀 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d5771e-fc1c-4d68-99bf-c9c31c41524f', '金錯刀 二', '金錯刀 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["日融融，草芊芊，黃鶯求友啼林前。","柳條嫋嫋拖金線，花蘂茸茸簇錦氈。","鳩逐婦，燕穿簾，狂蜂浪蝶相翩翩。","春光堪賞還堪翫，惱殺東風悞少年。"]', '["日融融，草芊芊，黄鶯求友啼林前。","柳條嫋嫋拖金線，花蘂茸茸簇錦氈。","鳩逐婦，燕穿簾，狂蜂浪蝶相翩翩。","春光堪賞還堪翫，惱殺东风悞少年。"]', '诗', 'shi', '', NULL, '金錯刀 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d0df616-9e14-4237-a470-7520d2c7bf9d', '憶江南 一', '憶江南 一', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["去歲迎春樓上月，正是西窗，夜涼時節。","玉人貪睡墜釵雲，粉消妝薄見天真。","人非風月長依舊，破鏡塵箏一夢經年瘦。","今宵簾幕颺花陰，空餘枕淚獨傷心。"]', '["去歲迎春楼上月，正是西窗，夜涼时節。","玉人貪睡墜釵云，粉消妝薄见天真。","人非风月长依旧，破镜塵箏一梦經年瘦。","今宵簾幕颺花陰，空餘枕泪独傷心。"]', '诗', 'shi', '', NULL, '憶江南 一 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65da009a-662f-45e6-84aa-1fc9a0d1034e', '憶江南 二', '憶江南 二', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["今日相逢花未發，正是去年，別離時節。","東風次第有花開，恁時須約却重來。","重來不怕花堪折，秪恐明年花發人離別。","別離若向百花時，東風彈淚有誰知。"]', '["今日相逢花未發，正是去年，別離时節。","东风次第有花开，恁时須約却重来。","重来不怕花堪折，秪恐明年花發人離別。","別離若向百花时，东风彈泪有誰知。"]', '诗', 'shi', '', NULL, '憶江南 二 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cc7dfdb-ae61-4f88-987e-ed530573f0e7', '木蘭花', '木蘭花', '6bd86c1f-6607-451f-8aee-47b7b430311a', '唐', '["沈檀煙起盤紅霧，一箭霜風吹繡戶。","漢宮花面學梅妝，謝女雪詩栽柳絮。","長垂夾幕孤鸞舞，旋炙銀笙雙鳳語。","紅窗酒病嚼寒冰，冰損相思無夢處。"]', '["沈檀煙起盤紅霧，一箭霜风吹繡戶。","漢宮花面学梅妝，謝女雪诗栽柳絮。","长垂夾幕孤鸾舞，旋炙銀笙雙鳳語。","紅窗酒病嚼寒冰，冰損相思無梦处。"]', '诗', 'shi', '', NULL, '木蘭花 徐昌圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b061a7ec-aecb-4e28-b87e-0f57c5862949', '臨江仙', '臨江仙', '6bd86c1f-6607-451f-8aee-47b7b430311a', '唐', '["飲散離亭西去，浮生常恨飄蓬。","回頭煙柳漸重重，淡雲孤鴈遠，寒日暮天紅。","今夜畫船何處，潮平淮月朦朧。","酒醒人靜奈愁濃，殘燈孤枕夢，輕浪五更風。"]', '["饮散離亭西去，浮生常恨飄蓬。","回头煙柳漸重重，淡云孤鴈远，寒日暮天紅。","今夜畫船何处，潮平淮月朦朧。","酒醒人静奈愁濃，殘灯孤枕梦，轻浪五更风。"]', '诗', 'shi', '', NULL, '臨江仙 徐昌圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af8721a5-4fb3-4f18-9d66-833baa208fca', '河傳', '河傳', '6bd86c1f-6607-451f-8aee-47b7b430311a', '唐', '["秋光滿目，風清露白，蓮紅水綠。","何處夢回，弄珠拾翠盈盈。","倚闌橈，眉黛蹙。","采蓮調穩，吳侶聲相續，倚棹吳江曲。","鷺起暮天，幾雙交頸鴛鴦，入蘆花深處宿。"]', '["秋光满目，风清露白，蓮紅水綠。","何处梦回，弄珠拾翠盈盈。","倚闌橈，眉黛蹙。","采蓮調穩，吳侶声相續，倚棹吳江曲。","鷺起暮天，幾雙交頸鴛鴦，入蘆花深处宿。"]', '诗', 'shi', '', NULL, '河傳 徐昌圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a8b979-7512-438c-a807-b175febd539a', '拋毬樂 一', '拋毬乐 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["歌舞送飛毬，金觥碧玉籌。","管弦桃李月，簾幕鳳皇樓。","一笑千場醉，浮生任白頭。"]', '["歌舞送飞毬，金觥碧玉籌。","管弦桃李月，簾幕鳳皇楼。","一笑千場醉，浮生任白头。"]', '诗', 'shi', '', NULL, '拋毬樂 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c630c840-f227-4882-9104-49bd4bfa2fb7', '拋毬樂 二', '拋毬乐 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["灼灼傅花枝，紛紛度畫旂。","不知紅燭下，照見彩毬飛。","借勢因期尅，巫山暮雨歸。"]', '["灼灼傅花枝，紛紛度畫旂。","不知紅燭下，照见彩毬飞。","借勢因期尅，巫山暮雨归。"]', '诗', 'shi', '', NULL, '拋毬樂 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bae413a-b4af-4a64-aefe-90c024dc2bb7', '木蘭花', '木蘭花', '425029f1-fa8c-49a7-bd0c-85854af15515', '唐', '["木蘭紅豔多情態，不似凡花人不愛。","移來孔雀檻邊栽，折向鳳皇釵上戴。","是何芍藥爭風彩，自共[牡]丹長作對。","若教爲女嫁東風，除却黃鶯難匹配。"]', '["木蘭紅豔多情態，不似凡花人不愛。","移来孔雀檻邊栽，折向鳳皇釵上戴。","是何芍藥爭风彩，自共[牡]丹长作对。","若教爲女嫁东风，除却黄鶯难匹配。"]', '诗', 'shi', '', NULL, '木蘭花 庾傳素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de57cd2-de97-4216-a48f-51a285c09ffa', '生查子', '生查子', '8a75ca9e-1bda-483a-a07c-90ece6de8e54', '唐', '["深秋更漏長，滴盡銀臺燭。","獨步出幽閨，月晃波澄綠。","菱荷風乍觸，一對鴛鴦宿。","虛櫂玉釵驚，驚起還相續。"]', '["深秋更漏长，滴尽銀台燭。","独步出幽閨，月晃波澄綠。","菱荷风乍觸，一对鴛鴦宿。","虛櫂玉釵驚，驚起還相續。"]', '诗', 'shi', '', NULL, '生查子 劉侍讀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56f03ec3-4715-4481-af04-af0b019ac29b', '木蘭花 一', '木蘭花 一', '9b5b7029-6506-4aaf-8e77-04ecf6efaa64', '唐', '["小庭日晚花零落，倚戶無聊妝臉薄。","寶箏金鴨任生塵，繡畫工夫全放却。","有時覷著同心結，萬恨千愁無處說。","當初不合儘饒伊，贏得如今長恨別。"]', '["小庭日晚花零落，倚戶無聊妝臉薄。","寶箏金鴨任生塵，繡畫工夫全放却。","有时覷著同心結，万恨千愁無处说。","當初不合儘饒伊，贏得如今长恨別。"]', '诗', 'shi', '', NULL, '木蘭花 一 許岷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec559d38-d063-4ccd-858a-36cf6461c4f8', '木蘭花 二', '木蘭花 二', '9b5b7029-6506-4aaf-8e77-04ecf6efaa64', '唐', '["江南日暖芭蕉展，美人折得親裁翦。","畫成小簡寄情人，臨行更把輕輕撚。","其中撚破相思字，却恐郎疑蹤不似。","若還猜妾倩人書，誤了平生多少事。"]', '["江南日暖芭蕉展，美人折得親裁翦。","畫成小簡寄情人，臨行更把轻轻撚。","其中撚破相思字，却恐郎疑蹤不似。","若還猜妾倩人书，誤了平生多少事。"]', '诗', 'shi', '', NULL, '木蘭花 二 許岷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('776edd10-d0c0-4e09-9ad5-87b1377f4e91', '菩薩蠻', '菩薩蠻', 'f7a9c77b-218c-4c5a-a7e0-4c21261e3fe0', '唐', '["畫堂春晝垂珠箔，臥來揉惹金釵落。","簟滑枕頭移，鬢蟬狂欲飛。","笑拖嬌眼慢，羅袖籠花面。","重道好郎君，人前莫惱人。"]', '["畫堂春晝垂珠箔，臥来揉惹金釵落。","簟滑枕头移，鬢蟬狂欲飞。","笑拖嬌眼慢，羅袖籠花面。","重道好郎君，人前莫惱人。"]', '诗', 'shi', '', NULL, '菩薩蠻 林楚翹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6936a6c-47c8-4caf-b114-fcaf9609479d', '一片子', '一片子', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["柳色青山映，梨花雪鳥藏。","綠窗桃李下，閑坐歎春芳。"]', '["柳色青山映，梨花雪鸟藏。","綠窗桃李下，闲坐歎春芳。"]', '诗', 'shi', '', NULL, '一片子 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a3e3618-f57f-42c6-8c0e-3364db244e5d', '塞姑', '塞姑', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["昨日盧梅塞口，整見諸人鎮守。","都護三年不歸，折盡江邊楊柳。"]', '["昨日盧梅塞口，整见諸人鎮守。","都護三年不归，折尽江邊楊柳。"]', '诗', 'shi', '', NULL, '塞姑 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8db991e6-cd4b-4042-b416-26965a16e294', '醉公子', '醉公子', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["門外猧兒吠，知是蕭郎至。","剗襪下香階，冤家今夜醉。","扶得入羅幃，不肯脫羅衣。","醉則從他醉，還勝獨睡時。"]', '["门外猧兒吠，知是蕭郎至。","剗襪下香階，冤家今夜醉。","扶得入羅幃，不肯脫羅衣。","醉則從他醉，還勝独睡时。"]', '诗', 'shi', '', NULL, '醉公子 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2aa5d4e-8685-43a4-906a-441097a51fac', '菩薩蠻', '菩薩蠻', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["牡丹含露真珠顆，美人折向庭前過。","含笑問檀郎，花強妾貌強。","檀郎故相惱，須道花枝好。","一面發嬌嗔，碎挼花打人。"]', '["牡丹含露真珠顆，美人折向庭前過。","含笑问檀郎，花強妾貌強。","檀郎故相惱，須道花枝好。","一面發嬌嗔，碎挼花打人。"]', '诗', 'shi', '', NULL, '菩薩蠻 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b94c8bad-e982-4625-9a9b-e9a5c6e66a24', '賀聖朝', '賀聖朝', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["白露點，曉星明滅，秋風落葉。","故址頹垣，冷煙衰草，前朝宮闕。","長安道上行客，依舊利深名切。","改變容顏，消磨今古，隴頭殘月。"]', '["白露点，晓星明滅，秋风落葉。","故址頹垣，冷煙衰草，前朝宮闕。","长安道上行客，依旧利深名切。","改变容顏，消磨今古，隴头殘月。"]', '诗', 'shi', '', NULL, '賀聖朝 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74fe7e95-9350-4357-8921-6f6d6b654998', '虞美人', '虞美人', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["帳中草草軍情變，月下旌旗亂。","褫衣推枕愴離情，遠風吹下楚歌聲，正三更。","撫騅欲下重相顧，豔態花無主。","手中蓮鍔凜秋霜，九泉歸去是仙鄉，恨茫茫。"]', '["帳中草草軍情变，月下旌旗亂。","褫衣推枕愴離情，远风吹下楚歌声，正三更。","撫騅欲下重相顧，豔態花無主。","手中蓮鍔凜秋霜，九泉归去是仙乡，恨茫茫。"]', '诗', 'shi', '', NULL, '虞美人 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20fac5fc-bc10-4982-842e-de5b59195b0e', '後庭宴', '後庭宴', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["千里故鄉，十年華屋，亂魂飛過屏山簇。","眼重眉褪不勝春，菱花知我銷香玉。","雙雙燕子歸來，應解笑人幽獨。","斷歌零舞，遺恨清江曲。","萬樹綠低迷，一庭紅{艹/撲}𫂙。"]', '["千里故乡，十年华屋，亂魂飞過屏山簇。","眼重眉褪不勝春，菱花知我銷香玉。","雙雙燕子归来，應解笑人幽独。","斷歌零舞，遺恨清江曲。","万樹綠低迷，一庭紅{艹/撲}𫂙。"]', '诗', 'shi', '', NULL, '後庭宴 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff4943ef-4dd7-41c8-a4fa-20a4e11f70e7', '擷芳詞', '擷芳词', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["風搖蕩，雨濛茸，翠條柔弱花頭重。","春衫窄，香肌濕，記得年時，共伊曾[摘]。","都如夢，何曾共，可憐孤似釵頭鳳。","關山隔，晚雲碧，燕兒來也，又無消息。"]', '["风搖蕩，雨濛茸，翠條柔弱花头重。","春衫窄，香肌濕，記得年时，共伊曾[摘]。","都如梦，何曾共，可怜孤似釵头鳳。","关山隔，晚云碧，燕兒来也，又無消息。"]', '诗', 'shi', '', NULL, '擷芳詞 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d4845a7-22a2-4c81-820c-8460e2c913d8', '魚遊春水', '鱼游春水', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["秦樓東風裏，燕子還來尋舊壘。","餘寒猶峭，紅日薄侵羅綺。","嫩草方抽碧玉茵，媚柳輕窣黃金縷。","鶯轉上林，魚遊春水。","幾曲闌干遍倚，又是一番新桃李。","佳人應怪歸遲，梅妝淚洗。","鳳簫聲絕沈孤鴈，望斷清波無雙鯉。","雲山萬重，寸心千里。"]', '["秦楼东风裏，燕子還来尋旧壘。","餘寒猶峭，紅日薄侵羅綺。","嫩草方抽碧玉茵，媚柳轻窣黄金縷。","鶯轉上林，鱼游春水。","幾曲闌干遍倚，又是一番新桃李。","佳人應怪归遲，梅妝泪洗。","鳳簫声絕沈孤鴈，望斷清波無雙鯉。","云山万重，寸心千里。"]', '诗', 'shi', '', NULL, '魚遊春水 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f7e226a-46d9-4a9f-8efe-4525920db4a6', '阿那曲', '阿那曲', '02ab63b8-2a8c-4205-aa8b-df59281a4a34', '唐', '["羅袖動香香不已，紅蕖嫋嫋秋煙裏。","輕雲嶺下乍搖風，嫩柳池塘初拂水。"]', '["羅袖动香香不已，紅蕖嫋嫋秋煙裏。","轻云嶺下乍搖风，嫩柳池塘初拂水。"]', '诗', 'shi', '', NULL, '阿那曲 楊貴妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('978e67ae-af35-4457-aaca-1d2f3c210769', '樂遊曲 一', '乐游曲 一', '8b0c206a-81c2-473b-a248-3cf38aadf322', '唐', '["龍舟搖曳東復東，采蓮湖上紅更紅。","波淡淡，水溶溶，奴隔荷花路不通。"]', '["龙舟搖曳东复东，采蓮湖上紅更紅。","波淡淡，水溶溶，奴隔荷花路不通。"]', '诗', 'shi', '', NULL, '樂遊曲 一 閩后陳氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0babb46-2fb7-4710-acde-f819dfe4fc7d', '樂遊曲 二', '乐游曲 二', '8b0c206a-81c2-473b-a248-3cf38aadf322', '唐', '["西湖南湖鬬綵舟，青蒲紫蓼滿中洲。","波渺渺，水悠悠，長奉君王萬歲遊。"]', '["西湖南湖鬬綵舟，青蒲紫蓼满中洲。","波渺渺，水悠悠，长奉君王万歲游。"]', '诗', 'shi', '', NULL, '樂遊曲 二 閩后陳氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c619b58-00aa-418f-beb7-103c5f914bfe', '楊柳枝', '楊柳枝', '768a19eb-4eda-49ad-b96f-efae5d0bdcbb', '唐', '["楊柳枝，芳菲節，可恨年年贈離別。","一葉隨風忽報秋，縱使君來豈堪折。"]', '["楊柳枝，芳菲節，可恨年年贈離別。","一葉隨风忽報秋，縱使君来豈堪折。"]', '诗', 'shi', '', NULL, '楊柳枝 柳氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf19cbe0-2ec7-4f4b-823f-c21646165b82', '字字雙', '字字雙', 'fed1df81-ada2-4048-a950-c50869844ecd', '唐', '["牀頭錦衾斑復斑，架上朱衣殷復殷。","空庭明月閑復閑，夜長路遠山復山。"]', '["牀头錦衾斑复斑，架上朱衣殷复殷。","空庭明月闲复闲，夜长路远山复山。"]', '诗', 'shi', '', NULL, '字字雙 王麗真女郎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca8992f8-291a-48ef-9988-8c0b644c3fc8', '菩薩蠻', '菩薩蠻', '9117e2d0-1436-46fd-8e89-64fe8cc9938d', '唐', '["玉京人去秋蕭索，畫簷鵲起梧桐落。","欹枕悄無言，月和殘夢圓。","背燈唯暗泣甚處砧聲急眉黛遠山攢芭蕉生暮寒。"]', '["玉京人去秋蕭索，畫簷鵲起梧桐落。","欹枕悄無言，月和殘梦圓。","背灯唯暗泣甚处砧声急眉黛远山攢芭蕉生暮寒。"]', '诗', 'shi', '', NULL, '菩薩蠻 耿玉真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0488f605-2f27-4137-b127-759d53d963db', '句 一', '句 一', '9117e2d0-1436-46fd-8e89-64fe8cc9938d', '唐', '["庭空客散人歸後，畫堂半掩朱簾。","林風[淅淅]夜厭厭，小樓新月，回首自纖纖。"]', '["庭空客散人归後，畫堂半掩朱簾。","林风[淅淅]夜厭厭，小楼新月，回首自纖纖。"]', '诗', 'shi', '', NULL, '句 一 耿玉真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eda59a31-d907-40fb-862b-72d73b66f4ce', '句 二', '句 二', '9117e2d0-1436-46fd-8e89-64fe8cc9938d', '唐', '["春光鎮在人空老，新愁往恨何窮。","金窗力困起還慵，一聲羌笛，驚起醉怡容。"]', '["春光鎮在人空老，新愁往恨何窮。","金窗力困起還慵，一声羌笛，驚起醉怡容。"]', '诗', 'shi', '', NULL, '句 二 耿玉真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37e7c8de-bc8a-4002-ad5f-c5913329380f', '句 三', '句 三', '9117e2d0-1436-46fd-8e89-64fe8cc9938d', '唐', '["尋春須是陽春早，看花莫待花枝老。"]', '["尋春須是陽春早，看花莫待花枝老。"]', '诗', 'shi', '', NULL, '句 三 耿玉真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f399b1c6-13be-4dad-afa8-feb02b28ee69', '句 四', '句 四', '9117e2d0-1436-46fd-8e89-64fe8cc9938d', '唐', '["帝鄉煙雨鎖春愁，故國山川空淚眼。"]', '["帝乡煙雨鎖春愁，故国山川空泪眼。"]', '诗', 'shi', '', NULL, '句 四 耿玉真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9d66fe-9016-43a0-b421-d333eed0923f', '句 五', '句 五', '9117e2d0-1436-46fd-8e89-64fe8cc9938d', '唐', '["金鳳欲飛遭掣搦，情脈脈，看即玉樓雲雨隔。"]', '["金鳳欲飞遭掣搦，情脈脈，看即玉楼云雨隔。"]', '诗', 'shi', '', NULL, '句 五 耿玉真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b60f722-b912-4b3c-b00e-4056521c92b4', '句 六', '句 六', '9117e2d0-1436-46fd-8e89-64fe8cc9938d', '唐', '["桃李不須誇爛熳，已輸了風吹一半。"]', '["桃李不須誇爛熳，已輸了风吹一半。"]', '诗', 'shi', '', NULL, '句 六 耿玉真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3890eb4-8be2-43a9-a824-62431fd48aa2', '句 七', '句 七', '9117e2d0-1436-46fd-8e89-64fe8cc9938d', '唐', '["學著荷衣還可喜，年少多來有幾，自古閑愁無際。"]', '["学著荷衣還可喜，年少多来有幾，自古闲愁無際。"]', '诗', 'shi', '', NULL, '句 七 耿玉真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2225ec3-c939-423d-acd9-3b5430bb6c6e', '句 八', '句 八', '9117e2d0-1436-46fd-8e89-64fe8cc9938d', '唐', '["初離蜀道心將碎，離恨綿綿，春日如年，馬上時時聞杜鵑。"]', '["初離蜀道心將碎，離恨綿綿，春日如年，马上时时闻杜鵑。"]', '诗', 'shi', '', NULL, '句 八 耿玉真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8753a366-a20a-496d-b53a-1807f85dd14f', '梧桐影', '梧桐影', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["落日斜，秋風冷。","今夜故人來不來，教人立盡梧桐影。"]', '["落日斜，秋风冷。","今夜故人来不来，教人立尽梧桐影。"]', '诗', 'shi', '', NULL, '梧桐影 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8e060c0-34aa-4623-a1f9-6b003a635212', '憶江南 一', '憶江南 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["淮南法，秋石最堪誇。","位應乾坤白露節，象移寅卯紫河車，子午結朝霞。"]', '["淮南法，秋石最堪誇。","位應乾坤白露節，象移寅卯紫河车，子午結朝霞。"]', '诗', 'shi', '', NULL, '憶江南 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d623962-e293-4cc8-ae05-4fd069c71eec', '憶江南 二', '憶江南 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["王陽術，得祕是黃牙。","萬蘂初生將此類，黃鍾應律始歸家，十月定君誇。"]', '["王陽術，得祕是黄牙。","万蘂初生將此類，黄鍾應律始归家，十月定君誇。"]', '诗', 'shi', '', NULL, '憶江南 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e6cfc6-3b1f-47d9-87c5-1b8a58c710dc', '憶江南 三', '憶江南 三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["黃帝術，玄妙美金花。","玉液初凝紅粉見，乾坤覆載暗交加，龍虎變成砂。"]', '["黄帝術，玄妙美金花。","玉液初凝紅粉见，乾坤覆載暗交加，龙虎变成砂。"]', '诗', 'shi', '', NULL, '憶江南 三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e99d2274-cdbe-47d4-a7ca-d78c6aa946a1', '憶江南 四', '憶江南 四', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["長生術，玄要補泥丸。","彭祖得之年八百，世人因此轉傷殘，誰是識陰丹。"]', '["长生術，玄要補泥丸。","彭祖得之年八百，世人因此轉傷殘，誰是識陰丹。"]', '诗', 'shi', '', NULL, '憶江南 四 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a192a67-78fe-4baa-9e92-6b0ab508cfb7', '憶江南 五', '憶江南 五', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["陰丹訣，三五合玄圖。","二八應機堪采運，玉瓊回首免榮枯，顏貌勝凡姝。"]', '["陰丹訣，三五合玄圖。","二八應機堪采運，玉瓊回首免榮枯，顏貌勝凡姝。"]', '诗', 'shi', '', NULL, '憶江南 五 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91452add-317c-4c8f-8159-a1a722320013', '憶江南 六', '憶江南 六', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["長生術，初九祕潛龍。","慎勿從高宜作客，丹田流注氣交通，耆老反嬰童。"]', '["长生術，初九祕潛龙。","慎勿從高宜作客，丹田流注氣交通，耆老反嬰童。"]', '诗', 'shi', '', NULL, '憶江南 六 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32ac9a3e-2d42-4662-884f-5d26c51cf4c3', '憶江南 七', '憶江南 七', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["修身客，莫誤入迷津。","氣術金丹傳在世，象天象地象人身，不用問東鄰。"]', '["修身客，莫誤入迷津。","氣術金丹傳在世，象天象地象人身，不用问东鄰。"]', '诗', 'shi', '', NULL, '憶江南 七 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39de066b-2f43-4a77-9528-3b09819fa0f0', '憶江南 八', '憶江南 八', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["還丹訣，九九最幽玄。","三性本同一體內，要燒靈藥切尋鉛，尋得是神仙。"]', '["還丹訣，九九最幽玄。","三性本同一體內，要燒靈藥切尋鉛，尋得是神仙。"]', '诗', 'shi', '', NULL, '憶江南 八 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef0b88fc-b0fd-41d2-a236-818dbb9dcdc7', '憶江南 九', '憶江南 九', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["長生藥，不用問他人。","八卦九宮看掌上，五行四象在人身，明了自通神。"]', '["长生藥，不用问他人。","八卦九宮看掌上，五行四象在人身，明了自通神。"]', '诗', 'shi', '', NULL, '憶江南 九 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d60c46c5-fd75-4ff5-916a-6085e89f2e68', '憶江南 十', '憶江南 十', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["學道客，修養莫遲遲。","光景斯須如夢裏，還丹粟粒變金姿，死去莫回歸。"]', '["学道客，修養莫遲遲。","光景斯須如梦裏，還丹粟粒变金姿，死去莫回归。"]', '诗', 'shi', '', NULL, '憶江南 十 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1ed58ca-02c5-49b3-81f5-a20752f98f8d', '憶江南 十一', '憶江南 十一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["治生客，審細察微言。","百歲夢中看即過，勸君修煉保尊年，不久是神仙。"]', '["治生客，審細察微言。","百歲梦中看即過，勸君修煉保尊年，不久是神仙。"]', '诗', 'shi', '', NULL, '憶江南 十一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b0cf058-9216-48a3-898f-9a4868c36c77', '憶江南 十二', '憶江南 十二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["瑤池上，瑞霧靄羣仙。","素練金童鏘鳳板，青衣玉女嘯鸞弦，身在大羅天。","沉醉處，縹渺玉京山。","唱徹步虛清燕罷，不知今夕是何年，海水又桑田。"]', '["瑤池上，瑞霧靄羣仙。","素練金童鏘鳳板，青衣玉女嘯鸾弦，身在大羅天。","沉醉处，縹渺玉京山。","唱徹步虛清燕罷，不知今夕是何年，海水又桑田。"]', '诗', 'shi', '', NULL, '憶江南 十二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6560bcad-c106-4db5-9a4f-13201b9d820b', '西江月 一', '西江月 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["著意黃庭歲久，留心金碧年深。","爲憂白髮鬢相侵，仙訣朝朝討論。","秘要俱皆覽過，神仙奧旨重吟。","至人親指水中金，不負平生志性。"]', '["著意黄庭歲久，留心金碧年深。","爲憂白髮鬢相侵，仙訣朝朝討論。","秘要俱皆覽過，神仙奧旨重吟。","至人親指水中金，不負平生志性。"]', '诗', 'shi', '', NULL, '西江月 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('890c7427-d465-45d2-a05a-ce7d2bd339cd', '西江月 二', '西江月 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["任是聰明志士，常迷東竈黃庭。","參同大易事分明，不曉醉眠難醒。","若遇高人指引，都來不費功程。","北方坎子是金精，忍得黃牙方盛。"]', '["任是聰明志士，常迷东竈黄庭。","參同大易事分明，不晓醉眠难醒。","若遇高人指引，都来不費功程。","北方坎子是金精，忍得黄牙方盛。"]', '诗', 'shi', '', NULL, '西江月 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f79b2166-8d8d-4543-8a03-561230d5a256', '沁園春 一', '沁园春 一', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["七返還丹，在我先須，煉已待時。","正一陽初動，中宵漏永。","溫溫鉛鼎，光透簾幃。","造化爭馳，虎龍交媾，進火功夫牛斗危。","曲江上，看月華瑩淨，有箇烏飛。","當時，自飲刀圭，又誰信無中就養兒。","辨水源清濁，木金間隔。","不因師指，此事難知。","道要玄微，天機深遠，下手忙修猶太遲。","蓬萊路，待三千行滿，獨步雲歸。"]', '["七返還丹，在我先須，煉已待时。","正一陽初动，中宵漏永。","溫溫鉛鼎，光透簾幃。","造化爭驰，虎龙交媾，進火功夫牛斗危。","曲江上，看月华瑩淨，有箇烏飞。","當时，自饮刀圭，又誰信無中就養兒。","辨水源清濁，木金间隔。","不因師指，此事难知。","道要玄微，天機深远，下手忙修猶太遲。","蓬萊路，待三千行满，独步云归。"]', '诗', 'shi', '', NULL, '沁園春 一 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1e456f2-641f-45a6-840c-fc798915730b', '沁園春 二', '沁园春 二', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["火宅牽纏，夜去明來，早晚擔憂。","奈今日茫然，不知明日。","波波劫劫，有甚來由。","人世風燈，草頭珠露，我見傷心眼淚流。","不堅久，似石中迸火，水上浮漚。","休休，及早回頭，把往日風流一筆鉤。","但麤衣淡飯，隨緣度日。","任人笑我，我又何求。","限到頭來，不論貧富，著甚干忙日夜憂。","勸年少，把家緣棄了，海上來遊。"]', '["火宅牽纏，夜去明来，早晚擔憂。","奈今日茫然，不知明日。","波波劫劫，有甚来由。","人世风灯，草头珠露，我见傷心眼泪流。","不堅久，似石中迸火，水上浮漚。","休休，及早回头，把往日风流一笔鉤。","但麤衣淡飯，隨緣度日。","任人笑我，我又何求。","限到头来，不論貧富，著甚干忙日夜憂。","勸年少，把家緣棄了，海上来游。"]', '诗', 'shi', '', NULL, '沁園春 二 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49080a9f-d874-49f6-811f-4d7207698bb1', '沁園春 三', '沁园春 三', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["詩曲文章，任汝空留，數千萬篇。","奈日推一日，月推一月。","今年不了，又待來年。","有限光陰，無涯火院，只恐蹉跎老却賢。","貪癡漢，望成家學道，兩事雙全。","凡間，只戀塵緣，又誰信壺中別有天。","這道本無情，不親富貴。","不疎貧賤，只要心堅。","不在勞神，不須苦行，息慮忘機合自然。","長生事，待明公放下，方可相傳。"]', '["诗曲文章，任汝空留，數千万篇。","奈日推一日，月推一月。","今年不了，又待来年。","有限光陰，無涯火院，只恐蹉跎老却賢。","貪癡漢，望成家学道，兩事雙全。","凡间，只戀塵緣，又誰信壺中別有天。","這道本無情，不親富貴。","不疎貧賤，只要心堅。","不在勞神，不須苦行，息慮忘機合自然。","长生事，待明公放下，方可相傳。"]', '诗', 'shi', '', NULL, '沁園春 三 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb40d068-a6dd-4c64-9da2-e45a0a26be64', '卜算子', '卜算子', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["心空道亦空，風靜林還靜。","卷盡浮雲月自明，中有山河影。","供養及修行，舊話成重省。","豆爆生蓮火裏時，痛撥寒灰冷。"]', '["心空道亦空，风静林還静。","卷尽浮云月自明，中有山河影。","供養及修行，旧話成重省。","豆爆生蓮火裏时，痛撥寒灰冷。"]', '诗', 'shi', '', NULL, '卜算子 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2058921-ae4f-4946-9e42-236f5e63fd8b', '步蟾宮', '步蟾宮', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["坎離乾兌逢子午，須認取，自家根祖。","地雷震動山頭雨，要洗濯黃牙土。","捉得金精牢閉錮，煉甲庚，要生龍虎。","待他問汝甚人傳，但說道，先生姓呂。"]', '["坎離乾兌逢子午，須認取，自家根祖。","地雷震动山头雨，要洗濯黄牙土。","捉得金精牢閉錮，煉甲庚，要生龙虎。","待他问汝甚人傳，但说道，先生姓呂。"]', '诗', 'shi', '', NULL, '步蟾宮 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cf0801e-a524-479a-bdeb-e7988496e86c', '滿庭芳', '满庭芳', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["大道淵源，高真隱秘，風流豈可知聞。","先天一氣，清濁自然分。","不識坎離顛倒，誰能辨，金木浮沈。","幽微處，無中產有，澗畔虎龍吟。","壺中，真造化，天精地髓，陰魄陽魂。","運周天水火，燮理寒溫。","十月脫胎丹就，除此外，皆是傍門。","君知否，塵寰走徧，端的少知音。"]', '["大道淵源，高真隐秘，风流豈可知闻。","先天一氣，清濁自然分。","不識坎離顛倒，誰能辨，金木浮沈。","幽微处，無中產有，澗畔虎龙吟。","壺中，真造化，天精地髓，陰魄陽魂。","運周天水火，燮理寒溫。","十月脫胎丹就，除此外，皆是傍门。","君知否，塵寰走徧，端的少知音。"]', '诗', 'shi', '', NULL, '滿庭芳 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('693a5119-99c3-430b-9ece-110bc27a1339', '酹江月', '酹江月', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["仙風道骨，顛倒運乾坤，平分時節。","金木相交坎離位，一粒刀圭凝結。","水虎潛形，火龍伏體，萬丈毫光烈。","仙花朵秀，聖男靈女扳折。","霄漢此夜中秋，銀蟾離海，浪卷千層雪。","此是天關地軸，誰解推窮圓缺。","片晌功夫，霎時丹聚，到此憑何訣。","倚天長嘯，洞中無限風月。"]', '["仙风道骨，顛倒運乾坤，平分时節。","金木相交坎離位，一粒刀圭凝結。","水虎潛形，火龙伏體，万丈毫光烈。","仙花朵秀，聖男靈女扳折。","霄漢此夜中秋，銀蟾離海，浪卷千層雪。","此是天关地軸，誰解推窮圓缺。","片晌功夫，霎时丹聚，到此憑何訣。","倚天长嘯，洞中無限风月。"]', '诗', 'shi', '', NULL, '酹江月 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e3afafd-08b0-455f-96ec-cbf6b42a17f8', '水龍吟', '水龙吟', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["目前咫尺長生路，多少愚人不悟。","愛河浪闊，洪波風緊，舟船難渡。","略聽仙師語，到彼岸。","只消一句，煉金丹換了，凡胎濁骨。","免輪迴，三塗苦。","萬事澄心定意，聚真陽，都歸一處。","分明認得，靈光真趣，本來面目。","此箇幽微理，莫容易，等閑分付。","知蓬萊自有，神仙伴侶，同攜手，朝天去。"]', '["目前咫尺长生路，多少愚人不悟。","愛河浪闊，洪波风緊，舟船难渡。","略听仙師語，到彼岸。","只消一句，煉金丹換了，凡胎濁骨。","免輪迴，三塗苦。","万事澄心定意，聚真陽，都归一处。","分明認得，靈光真趣，本来面目。","此箇幽微理，莫容易，等闲分付。","知蓬萊自有，神仙伴侶，同携手，朝天去。"]', '诗', 'shi', '', NULL, '水龍吟 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe347a3d-272c-4630-80cb-2c9ca3433f05', '豆葉黃', '豆葉黄', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["二月江南山水路，李花零落春無主。","一箇魚兒無覓處，風和雨，玉龍生甲歸天去。"]', '["二月江南山水路，李花零落春無主。","一箇鱼兒無覓处，风和雨，玉龙生甲归天去。"]', '诗', 'shi', '', NULL, '豆葉黃 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a3c409c-7d6e-4585-9d7b-dc8c154d2287', '浪淘沙', '浪淘沙', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["我有屋三椽，住在靈源。","無遮四壁任蕭然，萬象森羅爲斗拱，瓦蓋青天。","無漏得多年，結就因緣。","修成功行滿三千，降得火龍伏得虎，陸路神仙。"]', '["我有屋三椽，住在靈源。","無遮四壁任蕭然，万象森羅爲斗拱，瓦蓋青天。","無漏得多年，結就因緣。","修成功行满三千，降得火龙伏得虎，陸路神仙。"]', '诗', 'shi', '', NULL, '浪淘沙 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8a4be0-3124-4c39-863e-6ee781d79817', '蘇幙遮', '蘇幙遮', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["天不高，地不大，惟有真心，物物俱含載。","不用之時全體在，用即拈來，萬象周沙界。","虛無中，塵色內，盡是還丹，歷歷堪收采。","這箇鼎鑪解不解，養就靈烏，飛出光明海。"]', '["天不高，地不大，惟有真心，物物俱含載。","不用之时全體在，用即拈来，万象周沙界。","虛無中，塵色內，尽是還丹，歷歷堪收采。","這箇鼎鑪解不解，養就靈烏，飞出光明海。"]', '诗', 'shi', '', NULL, '蘇幙遮 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05fd3d42-ee74-4b05-a06b-281d697b4ec4', '雨中花', '雨中花', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["三百年間，功標青史，幾多俱委埃塵。","悟黃粱棄事，厭世藏身。","將我一枝丹桂，換他千載青春。","岳陽樓上，綸巾羽扇，誰識天人。","蓬萊願應仙舉，誰知會合仙賓。","遙想望，吹笙玉殿，奏舞鸞裀。","風馭雲軿不散，碧桃紫奈長新。","願逢一粒，九霞光裏，相繼朝真。"]', '["三百年间，功標青史，幾多俱委埃塵。","悟黄粱棄事，厭世藏身。","將我一枝丹桂，換他千載青春。","岳陽楼上，綸巾羽扇，誰識天人。","蓬萊願應仙舉，誰知會合仙賓。","遙想望，吹笙玉殿，奏舞鸾裀。","风馭云軿不散，碧桃紫奈长新。","願逢一粒，九霞光裏，相繼朝真。"]', '诗', 'shi', '', NULL, '雨中花 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b52eb4-5bf0-4112-9281-abd4be0295d2', '促拍滿路花', '促拍满路花', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["西風吹渭水，落葉滿長安。","茫茫塵世裏，獨清閑。","自然鑪鼎，虎繞與龍盤。","九轉丹砂就，一粒刀圭，便成陸地神仙。","任萬釘寶帶貂蟬，富貴欲熏天。","黃粱炊未熟，夢驚殘。","是非海裏，直道作人難。","袖手江南去，白蘋紅蓼，又尋湓浦廬山。"]', '["西风吹渭水，落葉满长安。","茫茫塵世裏，独清闲。","自然鑪鼎，虎繞與龙盤。","九轉丹砂就，一粒刀圭，便成陸地神仙。","任万釘寶带貂蟬，富貴欲熏天。","黄粱炊未熟，梦驚殘。","是非海裏，直道作人难。","袖手江南去，白蘋紅蓼，又尋湓浦廬山。"]', '诗', 'shi', '', NULL, '促拍滿路花 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63e1f80b-f679-407a-b139-9f954c3b5a07', '六么令', '六么令', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["東與西，眼與眉。","偃月爐中運坎離，靈砂且上飛。","最幽微，是天機。","你休癡，你不知。"]', '["东與西，眼與眉。","偃月爐中運坎離，靈砂且上飞。","最幽微，是天機。","你休癡，你不知。"]', '诗', 'shi', '', NULL, '六么令 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b1a44fe-ef38-45a2-ad78-57c404cadd32', '漢宮春', '漢宮春', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["橫笛聲沉，倚危樓紅日，江轉天斜。","黃塵邊火澒洞，何處吾家。","胎禽怨夜，來乘風，玄露丹霞。","先生笑，飛空一劒，東風猶自天涯。","情知道山中好，早翠囂含隱，瑤草新芽。","青溪故人信斷，夢[逐]飆車。","乾坤星火，歸來了，煮石煎沙。","回首處，幅巾蒲帳，雲邊獨是桃花。"]', '["橫笛声沉，倚危楼紅日，江轉天斜。","黄塵邊火澒洞，何处吾家。","胎禽怨夜，来乘风，玄露丹霞。","先生笑，飞空一劒，东风猶自天涯。","情知道山中好，早翠囂含隐，瑤草新芽。","青溪故人信斷，梦[逐]飆车。","乾坤星火，归来了，煮石煎沙。","回首处，幅巾蒲帳，云邊独是桃花。"]', '诗', 'shi', '', NULL, '漢宮春 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50f6e7cb-74f5-4e76-a22a-890b7ac28cfb', '減蘭', '減蘭', 'c11bfa8a-1e32-429a-92df-316c6565266d', '唐', '["暫遊大庾，白鶴飛來誰共語。","嶺畔人家，曾見寒梅幾度花。","春來春去，人在落花流水處。","花滿前蹊，藏盡神仙人不知。"]', '["暫游大庾，白鹤飞来誰共語。","嶺畔人家，曾见寒梅幾度花。","春来春去，人在落花流水处。","花满前蹊，藏尽神仙人不知。"]', '诗', 'shi', '', NULL, '減蘭 呂巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e973a86-9936-4893-bf0a-433a8fa0c092', '憶江南', '憶江南', 'd9620983-a08f-4714-bdf4-a29f2808d5bd', '唐', '["江南鼓，梭肚兩頭欒。","釘著不知侵骨髓，打來只是沒心肝，空腹被人謾。"]', '["江南鼓，梭肚兩头欒。","釘著不知侵骨髓，打来只是沒心肝，空腹被人謾。"]', '诗', 'shi', '', NULL, '憶江南 伊用昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54736eff-4076-4768-8069-1d5981f2639f', '送日本使', '送日本使', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["日下非殊俗，天中嘉會朝。","念余懷義遠，矜爾畏途遙。","漲海寬秋月，歸帆[駛]夕飆。","因驚彼君子，王化遠昭昭。"]', '["日下非殊俗，天中嘉會朝。","念余懷義远，矜爾畏途遙。","漲海寬秋月，归帆[駛]夕飆。","因驚彼君子，王化远昭昭。"]', '诗', 'shi', '', NULL, '送日本使 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1abdb4a3-6d67-4ddd-a722-ea5f80ee90a8', '賜新羅王', '賜新羅王', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["四維分景緯，萬象含中樞。","玉帛遍天下，梯杭歸上都。","緬懷阻青陸，歲月勤黃圖。","漫漫窮地際，蒼蒼連海隅。","興言名義國，豈謂山河殊。","使去傳風教，人來習典謨。","衣冠知奉禮，忠信識尊儒。","誠矣天其鑒，賢哉德不孤。","擁旄同作牧，厚貺比生蒭。","益重青青志，風霜恆不渝。"]', '["四維分景緯，万象含中樞。","玉帛遍天下，梯杭归上都。","緬懷阻青陸，歲月勤黄圖。","漫漫窮地際，蒼蒼連海隅。","兴言名義国，豈謂山河殊。","使去傳风教，人来習典謨。","衣冠知奉禮，忠信識尊儒。","誠矣天其鑒，賢哉德不孤。","擁旄同作牧，厚貺比生蒭。","益重青青志，风霜恆不渝。"]', '诗', 'shi', '', NULL, '賜新羅王 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e8d7241-5bba-4134-95a2-f683e230b8c8', '句', '句', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["玉殿笙歌宜此夜，更看明月照高樓。"]', '["玉殿笙歌宜此夜，更看明月照高楼。"]', '诗', 'shi', '', NULL, '句 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c3bf850-5c5e-414e-b9cf-4d1d003aefd4', '采蓮', '采蓮', '7d3c6801-907a-4338-9040-ac5767a7b007', '唐', '["采蓮江浦覓同心，日暮風生江水深。","莫言花重船應沒，自解凌波不畏沈。"]', '["采蓮江浦覓同心，日暮风生江水深。","莫言花重船應沒，自解凌波不畏沈。"]', '诗', 'shi', '', NULL, '采蓮 楊師道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43ae7d31-c83f-45b6-a168-2f6be3066f4e', '句', '句', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["曙色隨行漏，早吹入繁笳。","旗文縈桂葉，騎影拂桃華。","碧潭寫春照，青山籠雪花。","池牑風月清，閒居遊客情。","蘭泛樽中色，松今弦上聲。"]', '["曙色隨行漏，早吹入繁笳。","旗文縈桂葉，騎影拂桃华。","碧潭寫春照，青山籠雪花。","池牑风月清，閒居游客情。","蘭泛樽中色，松今弦上声。"]', '诗', 'shi', '', NULL, '句 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b8b78ea-df36-4678-bd16-e35ec6705cbe', '句', '句', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["天上姮娥遙解意，偏教月向踏歌明。","共待山頭明月上，照君行棹出長川。"]', '["天上姮娥遙解意，偏教月向踏歌明。","共待山头明月上，照君行棹出长川。"]', '诗', 'shi', '', NULL, '句 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a8e5f5b-69b3-42db-8623-c807e5be700f', '句', '句', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["雨鳴鴛瓦收炎氣，風卷珠簾送曉涼。"]', '["雨鳴鴛瓦收炎氣，风卷珠簾送晓涼。"]', '诗', 'shi', '', NULL, '句 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e970b631-7a9d-401a-887c-6403f63c1226', '句', '句', '929a09b1-ba43-4245-a8e7-af95eda1cd9f', '唐', '["歸心靜對螢飛月，遠夢長驚角滿樓。"]', '["归心静对螢飞月，远梦长驚角满楼。"]', '诗', 'shi', '', NULL, '句 殷遙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c23f40ec-9c73-4910-90bf-2ba86de0d95d', '句', '句', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["自恨開遲還落早，縱橫只是怨春風。"]', '["自恨开遲還落早，縱橫只是怨春风。"]', '诗', 'shi', '', NULL, '句 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f0d92d2-79a2-43b2-9c07-5502bf7fc531', '句', '句', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["巴路千山秋水上，江村獨樹夕陽時。"]', '["巴路千山秋水上，江村独樹夕陽时。"]', '诗', 'shi', '', NULL, '句 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79281dbc-069e-4143-9538-2082395cafec', '旅次盩厔過韓士別業', '旅次盩厔過韓士別業', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["春煙桑柘林，落日隱荒墅。","泱漭平原夕，清吟久延佇。","故人家於此，招我漁樵所。"]', '["春煙桑柘林，落日隐荒墅。","泱漭平原夕，清吟久延佇。","故人家於此，招我漁樵所。"]', '诗', 'shi', '', NULL, '旅次盩厔過韓士別業 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ead5758b-2fac-46bb-a69d-a6eb160e0f3c', '上侍御士兄', '上侍御士兄', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["天人俟明路，益稷分堯心。","利器必先舉，非賢安可任。","吾兄執嚴憲，時佐能釣深。"]', '["天人俟明路，益稷分堯心。","利器必先舉，非賢安可任。","吾兄執嚴憲，时佐能釣深。"]', '诗', 'shi', '', NULL, '上侍御士兄 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b11acf95-785c-4cc1-be74-f2c7ec39dba7', '上同州使君伯', '上同州使君伯', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["大賢本孤立，有時起絲綸。","伯父自天稟，元功載生人。"]', '["大賢本孤立，有时起絲綸。","伯父自天稟，元功載生人。"]', '诗', 'shi', '', NULL, '上同州使君伯 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6adcac53-3a5b-449e-94d2-e6ee701167a7', '留別', '留別', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["桑林映陂水，雨過宛城西。","留醉楚山別，陰雲暮霋霋。"]', '["桑林映陂水，雨過宛城西。","留醉楚山別，陰云暮霋霋。"]', '诗', 'shi', '', NULL, '留別 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('912b3271-6087-4685-8c7d-a4aaa7edb5be', '贈李侍御', '贈李侍御', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["青冥孤雲去，終當暮歸山。","志士杖苦節，何時見龍顏。"]', '["青冥孤云去，終當暮归山。","志士杖苦節，何时见龙顏。"]', '诗', 'shi', '', NULL, '贈李侍御 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d1fdcbe-228a-47e4-bda9-594778992438', '又贈李侍御', '又贈李侍御', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["渺然客子魂，倏鑠川上暉。","還雲慘知暮，九月仍未歸。"]', '["渺然客子魂，倏鑠川上暉。","還云慘知暮，九月仍未归。"]', '诗', 'shi', '', NULL, '又贈李侍御 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5808be9d-483e-4767-b645-d8ae678ca8f7', '送別', '送別', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["春江愁送君，蕙草生氤氳。","醉後不能語，鄉山雨雰雰。"]', '["春江愁送君，蕙草生氤氳。","醉後不能語，乡山雨雰雰。"]', '诗', 'shi', '', NULL, '送別 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfcf86d4-859d-43ef-8dad-702de538edff', '失題', '失題', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["時與醉林壑，因之墮農桑。","槐煙漸含夜，樓月深蒼茫。"]', '["时與醉林壑，因之墮農桑。","槐煙漸含夜，楼月深蒼茫。"]', '诗', 'shi', '', NULL, '失題 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88b0021d-0e69-4c42-bf2c-a60ebe56a22c', '失題', '失題', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["桑葉下墟落，鵾雞鳴渚田。","物情每衰極，吾道方淵然。"]', '["桑葉下墟落，鵾雞鳴渚田。","物情每衰極，吾道方淵然。"]', '诗', 'shi', '', NULL, '失題 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df2eed5-f4ec-4f8f-a22e-4f61f470d180', '句', '句', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["與君遠相知，不道雲海深。","得罪由己招，本性易然諾。","黃葉亂秋雨，空齋愁暮心。","通經彼上人，無迹任勤苦。","楓橋延海岸，客帆歸富春。","寒江映村林，亭上納高潔。","陵藪寒蒼茫，登城遂懷古。","孤煙曳長林，春水聊一望。","河口餞南客，進帆清江水。","遷客又相送，風悲蟬更號。","微雨隨雲收，濛濛傍山去。","海客時獨飛，永然滄洲意。","日夕辨靈藥，空山松桂香。","墟落有懷縣，長煙溪樹邊。","青桂花未吐，江中獨鳴琴。","還家望炎海，楚葉下秋水。"]', '["與君远相知，不道云海深。","得罪由己招，本性易然諾。","黄葉亂秋雨，空斋愁暮心。","通經彼上人，無迹任勤苦。","楓橋延海岸，客帆归富春。","寒江映村林，亭上納高潔。","陵藪寒蒼茫，登城遂懷古。","孤煙曳长林，春水聊一望。","河口餞南客，進帆清江水。","遷客又相送，风悲蟬更號。","微雨隨云收，濛濛傍山去。","海客时独飞，永然滄洲意。","日夕辨靈藥，空山松桂香。","墟落有懷縣，长煙溪樹邊。","青桂花未吐，江中独鳴琴。","還家望炎海，楚葉下秋水。"]', '诗', 'shi', '', NULL, '句 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad74f084-1837-4cc8-838c-e6d3be1c393d', '句', '句', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["春苔滿地無行處，深映桃花獨閉門。"]', '["春苔满地無行处，深映桃花独閉门。"]', '诗', 'shi', '', NULL, '句 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1372742b-f030-4946-81ff-3e69f1675dd9', '句', '句', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["夜臺一閉無時盡，逝水東流何處還？田家收已盡，蒼蒼只白茅。"]', '["夜台一閉無时尽，逝水东流何处還？田家收已尽，蒼蒼只白茅。"]', '诗', 'shi', '', NULL, '句 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66be92b1-a992-42a5-899b-7b02b0b7cf91', '句', '句', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉堦一夜留明月，金殿三春滿落花。"]', '["玉堦一夜留明月，金殿三春满落花。"]', '诗', 'shi', '', NULL, '句 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8baea0b6-bdfc-460a-88a7-c079ae0f8c7b', '題故人別業', '題故人別業', '8f7aa8e3-f4fd-48cf-b313-984d3a4513a9', '唐', '["平子歸田處，園林接汝濆。","落花開戶入，啼鳥隔窗聞。","池淨流春水，山明斂霽雲。","晝遊仍不厭，乘月夜尋君。"]', '["平子归田处，园林接汝濆。","落花开戶入，啼鸟隔窗闻。","池淨流春水，山明斂霽云。","晝游仍不厭，乘月夜尋君。"]', '诗', 'shi', '', NULL, '題故人別業 張謂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30129b3a-7cef-44d9-89ef-2f793a42103a', '句', '句', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["巴峽猿聲催客淚，銅梁山翠入江樓。","千峰鳥路含梅雨，五月蟬聲送麥秋。"]', '["巴峽猿声催客泪，銅梁山翠入江楼。","千峰鸟路含梅雨，五月蟬声送麦秋。"]', '诗', 'shi', '', NULL, '句 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dc32df8-ef28-4f13-8ab9-b5d97ce9d1de', '失題', '失題', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["胡風迎馬首，漢月學蛾眉。","久戍人將老，長征馬不肥。"]', '["胡风迎马首，漢月学蛾眉。","久戍人將老，长征马不肥。"]', '诗', 'shi', '', NULL, '失題 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a629ef8-9aaf-429e-9af2-65362af378c4', '句', '句', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["野人誤向人閒老，爲謝金華洞裏雲。","莫言歸去無人伴，自有中天月正明。"]', '["野人誤向人閒老，爲謝金华洞裏云。","莫言归去無人伴，自有中天月正明。"]', '诗', 'shi', '', NULL, '句 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89740c4e-5567-498f-8381-21c0dced6b67', '句', '句', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["兩岸楊花風作雪，一池荷葉雨成珠。","暮猿啼處三聲絕，寒雁歸時一葉秋。","一雙淚滴黃河水，願得東流入漢宮。"]', '["兩岸楊花风作雪，一池荷葉雨成珠。","暮猿啼处三声絕，寒雁归时一葉秋。","一雙泪滴黄河水，願得东流入漢宮。"]', '诗', 'shi', '', NULL, '句 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76cf322d-42b0-4774-b508-3173bd98a1a6', '句', '句', 'a8c47753-b338-4d4d-8898-f7f8b717ae70', '唐', '["不隨暮雨蒼江去，且向朝雲白雪歌。","欲于北闕辭蒼海，却望東山愧白雲。"]', '["不隨暮雨蒼江去，且向朝云白雪歌。","欲于北闕辞蒼海，却望东山愧白云。"]', '诗', 'shi', '', NULL, '句 崔膺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48552172-3cad-409b-9777-cc8a33064105', '句', '句', '02246080-d605-4f54-9d01-0465e371ec26', '唐', '["九衢車馬傳佳句，萬戶鶯花接勝遊。"]', '["九衢车马傳佳句，万戶鶯花接勝游。"]', '诗', 'shi', '', NULL, '句 馮宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85376101-c4ff-489b-9dde-9b7bd7d093b9', '句', '句', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["曾讀列仙王母傳，九天未勝此中遊。"]', '["曾读列仙王母傳，九天未勝此中游。"]', '诗', 'shi', '', NULL, '句 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f459add3-8a52-4d5e-8459-2f97d4810ab5', '句', '句', '08b14256-c564-4489-be33-927205119c81', '唐', '["鳴鞭秋色詩情遠，拂匣寒花劒力多。","籍通蓮闕秋光遍，詩答蓬山晚思遙。","青門日暖塵光動，紫陌花晴風色來。","豔欺藤蔓鶯無限，香壓荆花蝶不飛。","內史舊山空日暮，南朝古木向人秋。","夢中鄉信驚秋鴈，窗下林聲帶夜蟬。","獨向曉山知露溼，遠臨秋水愛雲明。","新河柳色千株暗，故國雲帆萬里歸。","一院綠錢童子拂，千竿青玉主人栽。","露凝丹地初疑雨，煙著紅樓半是霞。","空門水定埃塵遠，真偈金書世界稀。"]', '["鳴鞭秋色诗情远，拂匣寒花劒力多。","籍通蓮闕秋光遍，诗答蓬山晚思遙。","青门日暖塵光动，紫陌花晴风色来。","豔欺藤蔓鶯無限，香壓荆花蝶不飞。","內史旧山空日暮，南朝古木向人秋。","梦中乡信驚秋鴈，窗下林声带夜蟬。","独向晓山知露溼，远臨秋水愛云明。","新河柳色千株暗，故国云帆万里归。","一院綠錢童子拂，千竿青玉主人栽。","露凝丹地初疑雨，煙著紅楼半是霞。","空门水定埃塵远，真偈金书世界稀。"]', '诗', 'shi', '', NULL, '句 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('817910cd-954c-4124-998c-93eb97361f0c', '句', '句', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["煙波半落新沙地，鳥雀羣飛欲雪天。","櫻桃帶雨胭脂溼，楊柳當風綠線低。","山似屏風江似簟，叩舷來往月明中。","晴日碧空雲腳斷，一條如練挂山尖。","飛文鬬疾敲銅器，陪宴會歡吐錦茵。"]', '["煙波半落新沙地，鸟雀羣飞欲雪天。","櫻桃带雨胭脂溼，楊柳當风綠線低。","山似屏风江似簟，叩舷来往月明中。","晴日碧空云腳斷，一條如練挂山尖。","飞文鬬疾敲銅器，陪宴會歡吐錦茵。"]', '诗', 'shi', '', NULL, '句 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2297314f-6b78-4a4a-a7ae-3aff6ce9e10d', '奉和白舍人遊鏡湖夜歸', '奉和白舍人游镜湖夜归', '44304464-87c5-4dd8-8110-96fedd4b1a27', '唐', '["風前酒醒看山笑，湖上詩成共客吟。","畫燭滿堤燒月色，澄江繞樹浸城陰。"]', '["风前酒醒看山笑，湖上诗成共客吟。","畫燭满堤燒月色，澄江繞樹浸城陰。"]', '诗', 'shi', '', NULL, '奉和白舍人遊鏡湖夜歸 周元範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07cdb34b-3ba7-4759-bc9b-4eb3458ab943', '句', '句', '44304464-87c5-4dd8-8110-96fedd4b1a27', '唐', '["路出胥門深淺浪，月殘吳苑兩三星。","石橋路上千峯月，山殿雲中半夜鐘。"]', '["路出胥门深淺浪，月殘吳苑兩三星。","石橋路上千峯月，山殿云中半夜鐘。"]', '诗', 'shi', '', NULL, '句 周元範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e125e56c-4de2-425e-ad1a-85139399300f', '水樓', '水楼', '54b66031-94fa-497a-9e0d-963d5a8c410e', '唐', '["山銜落日溪光動，岸轉回風檻影浮。","座內數聲來遠鶴，煙中一派辨孤舟。"]', '["山銜落日溪光动，岸轉回风檻影浮。","座內數声来远鹤，煙中一派辨孤舟。"]', '诗', 'shi', '', NULL, '水樓 王魯復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feb3e82e-c4fa-47b8-b8c5-2143ee6e8f57', '句', '句', '54b66031-94fa-497a-9e0d-963d5a8c410e', '唐', '["清泉遶屋澄心遠，曙月銜山出定遲。"]', '["清泉遶屋澄心远，曙月銜山出定遲。"]', '诗', 'shi', '', NULL, '句 王魯復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8210a13a-4b36-42ed-987a-1319d932283a', '句', '句', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["滿手香傳金菊酒，漏聲遙滴上陽宮。"]', '["满手香傳金菊酒，漏声遙滴上陽宮。"]', '诗', 'shi', '', NULL, '句 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab0f1587-8078-4834-8c33-3657c7148323', '句', '句', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["徑草漸生長短綠，庭花欲綻淺深紅。","夜瑟絃驚綠流水，暖松花放碧香煙。","窗間夜學凝殘燭，軒下朝吟向暖風。","幽客攜琴好歸去，七絲閑和百泉聲。","野寺訪僧歸帶月，芳林攜客醉眠花。"]', '["徑草漸生长短綠，庭花欲綻淺深紅。","夜瑟絃驚綠流水，暖松花放碧香煙。","窗间夜学凝殘燭，軒下朝吟向暖风。","幽客携琴好归去，七絲闲和百泉声。","野寺訪僧归带月，芳林携客醉眠花。"]', '诗', 'shi', '', NULL, '句 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e63df4-bbf6-4c4f-80e5-c7d15f97078a', '句', '句', '52966ee9-6b26-48e4-a71b-eb49dcd095aa', '唐', '["須臾滿寺泉聲合，百尺飛簷挂玉繩。","座客醉來雲雨散，一行高鳥萬山秋。","綺羅香裏春長在，絲管聲中水暗流。","何事不歸巫峽去，故來人世斷人腸。","身居曉嶂紅霞外，書讀秋窗紫竹間。","瀑布水高清漢冷，莓苔橋滑碧煙虛。","日月在天常照耀，了無塵垢汙清光。"]', '["須臾满寺泉声合，百尺飞簷挂玉繩。","座客醉来云雨散，一行高鸟万山秋。","綺羅香裏春长在，絲管声中水暗流。","何事不归巫峽去，故来人世斷人腸。","身居晓嶂紅霞外，书读秋窗紫竹间。","瀑布水高清漢冷，莓苔橋滑碧煙虛。","日月在天常照耀，了無塵垢汙清光。"]', '诗', 'shi', '', NULL, '句 張蕭遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be165166-a03c-4103-b3eb-6d916db99235', '句', '句', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["雲收碧海連天水，風動紅蕉滴露光。"]', '["云收碧海連天水，风动紅蕉滴露光。"]', '诗', 'shi', '', NULL, '句 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f83a186-f453-477d-8652-c648d170655f', '句', '句', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["空巖雨暴泉聲亂，幽徑苔深鳥跡重。"]', '["空巖雨暴泉声亂，幽徑苔深鸟跡重。"]', '诗', 'shi', '', NULL, '句 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf3a6a0-6bee-4d10-b766-3d41664a2fa9', '送張孝廉歸吳', '送張孝廉归吳', '037f5a12-a1ca-422c-82f5-9c1a2b49b796', '唐', '["吳將勤苦見高科，藝至春官不奈何。","想得江南諸父老，因君鞭韃子孫多。"]', '["吳將勤苦见高科，藝至春官不奈何。","想得江南諸父老，因君鞭韃子孫多。"]', '诗', 'shi', '', NULL, '送張孝廉歸吳 章孝標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa53e505-2e5a-489f-8341-ae3c6558cd0f', '夜笛詞', '夜笛词', '037f5a12-a1ca-422c-82f5-9c1a2b49b796', '唐', '["皎潔西樓月未斜，笛聲寥亮入東家。","頓令燈下裁衣婦，誤翦同心一片依。"]', '["皎潔西楼月未斜，笛声寥亮入东家。","頓令灯下裁衣婦，誤翦同心一片依。"]', '诗', 'shi', '', NULL, '夜笛詞 章孝標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01e01cde-5d71-46c9-ae30-67331f2422f0', '題碧山寺塔', '題碧山寺塔', '037f5a12-a1ca-422c-82f5-9c1a2b49b796', '唐', '["六時佛火明珠綴，午後茶煙出翠微。","縈砌乳泉梳石髮，滴松銀露洗牆衣。"]', '["六时佛火明珠綴，午後茶煙出翠微。","縈砌乳泉梳石髮，滴松銀露洗牆衣。"]', '诗', 'shi', '', NULL, '題碧山寺塔 章孝標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dffe7755-e690-4a82-9919-b15b4879de47', '翫月遇雲', '翫月遇云', '037f5a12-a1ca-422c-82f5-9c1a2b49b796', '唐', '["無端玉葉連天起，不放金波到曉流。","暗惜蚌胎沈海面，仰思鵬翼破風頭。"]', '["無端玉葉連天起，不放金波到晓流。","暗惜蚌胎沈海面，仰思鵬翼破风头。"]', '诗', 'shi', '', NULL, '翫月遇雲 章孝標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb8dfaf4-16fb-44f9-b6b4-3681901dda91', '句', '句', '037f5a12-a1ca-422c-82f5-9c1a2b49b796', '唐', '["錢塘去國三千里，一道風光任意看。","珠呈夜浦螢無影，鶻坐秋林鳥失行。","昨日見君親下筆，五花牋上黑龍飛。","何人枉折教狼籍，孤負春風長養情。","梅花帶雪飛琴上，柳色和煙入酒中。","阮籍嘯場人步月，子猷看處鳥棲煙。","白練鳥迷山芍藥，紅妝妓妒水林檎。","今日華山秋頂上，聞天長叫在長空。","天風更送新聲出，不放行雲過鳳樓。","昨日天宮吹樂府，六官絃管一時新。","通傳勝事因風月，打破愁腸是酒杯。","姑蘇臺上煙花月，寧負春風簫管聲。","玉輪低月中天曉，金鐸縱風上界秋。","蕭灑竹房塵境外，滿天雲月共清虛。","言若浚川流巨海，戒如秋月挂長空。","金殿月中看擣藥，玉樓風裏聽吹笙。"]', '["錢塘去国三千里，一道风光任意看。","珠呈夜浦螢無影，鶻坐秋林鸟失行。","昨日见君親下笔，五花牋上黑龙飞。","何人枉折教狼籍，孤負春风长養情。","梅花带雪飞琴上，柳色和煙入酒中。","阮籍嘯場人步月，子猷看处鸟棲煙。","白練鸟迷山芍藥，紅妝妓妒水林檎。","今日华山秋頂上，闻天长叫在长空。","天风更送新声出，不放行云過鳳楼。","昨日天宮吹乐府，六官絃管一时新。","通傳勝事因风月，打破愁腸是酒杯。","姑蘇台上煙花月，寧負春风簫管声。","玉輪低月中天晓，金鐸縱风上界秋。","蕭灑竹房塵境外，满天云月共清虛。","言若浚川流巨海，戒如秋月挂长空。","金殿月中看擣藥，玉楼风裏听吹笙。"]', '诗', 'shi', '', NULL, '句 章孝標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c2a13bd-9f4f-44bb-9748-8dc25fb18140', '句', '句', 'e0116b12-899f-48c3-89f3-ae0b27958060', '唐', '["長把酒杯憑夜月，每將詩思泥春風。","襄陽樂事經過盡，峴首煙花倒瀉空。","猶疑波底鮫人淚，滴在衣裳半欲零。","春明門外襄陽路，落日秋風送客歸。"]', '["长把酒杯憑夜月，每將诗思泥春风。","襄陽乐事經過尽，峴首煙花倒瀉空。","猶疑波底鮫人泪，滴在衣裳半欲零。","春明门外襄陽路，落日秋风送客归。"]', '诗', 'shi', '', NULL, '句 陳標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef76c64b-fad1-44a7-8e87-8b4326d95bcd', '入洞庭望岳陽', '入洞庭望岳陽', '4ad6fc77-e6c8-43a3-bf1c-3fdd891b6cd0', '唐', '["飛鷗撒浪三千里，暮草搖風一萬畦。","黛色淺深山遠近，碧煙濃淡樹高低。"]', '["飞鷗撒浪三千里，暮草搖风一万畦。","黛色淺深山远近，碧煙濃淡樹高低。"]', '诗', 'shi', '', NULL, '入洞庭望岳陽 楊收 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c85f0c-3d84-4e5f-bd8d-151ab3ab4d29', '句', '句', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蒹葭水暗螢知夜，楊柳風高鴈送秋。","露滴曉花疑錦繡，風吹寒竹認笙簧。"]', '["蒹葭水暗螢知夜，楊柳风高鴈送秋。","露滴晓花疑錦繡，风吹寒竹認笙簧。"]', '诗', 'shi', '', NULL, '句 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eee7e201-d9b5-4287-9079-c3fb93083e25', '句', '句', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["虹橫布水臺南雨，鴈返爐峰頂北霞。","閑臥東風燈漸曉，溪南花氣雨中來。","一別山陰詩酒客，水風花片夢蘭亭。"]', '["虹橫布水台南雨，鴈返爐峰頂北霞。","闲臥东风灯漸晓，溪南花氣雨中来。","一別山陰诗酒客，水风花片梦蘭亭。"]', '诗', 'shi', '', NULL, '句 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bcb052c-634d-4358-814c-f9cbdae5d625', '句', '句', '9bced07a-90e1-45b4-ae54-6b949fdf22d9', '唐', '["卻覓終南山色看，倚天橫展玉屏風。","杜甫一生憐李白，應緣孔聖道才難。","終南山腳盤龍勢，紫閣雲心望鶴歸。"]', '["卻覓終南山色看，倚天橫展玉屏风。","杜甫一生怜李白，應緣孔聖道才难。","終南山腳盤龙勢，紫閣云心望鹤归。"]', '诗', 'shi', '', NULL, '句 祝元膺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e09efea-eef0-424a-8c3b-bc4526edc355', '句', '句', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["池上昔遊夫子鳳，雲間初起武侯龍。","亭分楚寺依依樹，水應公臺夜夜琴。","鴝鵒舞酣人自醉，琵琶聲緩客初來。","高鳥過時秋色動，征帆落處暮煙生。","夜吟孤枕潮聲近，晚過千山雪氣寒。","望臘早花緣路見，隨巖寒水隔林聞。","宿處客塵隨夜靜，坐中煙水向人閑。"]', '["池上昔游夫子鳳，云间初起武侯龙。","亭分楚寺依依樹，水應公台夜夜琴。","鴝鵒舞酣人自醉，琵琶声緩客初来。","高鸟過时秋色动，征帆落处暮煙生。","夜吟孤枕潮声近，晚過千山雪氣寒。","望臘早花緣路见，隨巖寒水隔林闻。","宿处客塵隨夜静，坐中煙水向人闲。"]', '诗', 'shi', '', NULL, '句 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a81203-6597-4aa3-b5b6-bd2218888417', '句', '句', 'ac51d998-5542-4eda-a55e-1688f2b00cac', '唐', '["九重城裏春來早，百尺樓頭日落遲。"]', '["九重城裏春来早，百尺楼头日落遲。"]', '诗', 'shi', '', NULL, '句 崔澹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff7b71cd-cb8d-4240-9a4f-3500a1864be6', '句', '句', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["莫是上天宮裏唱，歌聲飄下玉梁塵。"]', '["莫是上天宮裏唱，歌声飄下玉梁塵。"]', '诗', 'shi', '', NULL, '句 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc21f8f-8132-47a8-be2f-db3b9bf32089', '句', '句', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["沿澗水聲喧戶外，卷簾山色入窗來。","自有晚風推楚浪，不勞春色染湘煙。","卓氏壚前金綫柳，隋家隄畔錦帆風。","門外白雲何處雨，一條清澗遶溪流。"]', '["沿澗水声喧戶外，卷簾山色入窗来。","自有晚风推楚浪，不勞春色染湘煙。","卓氏壚前金綫柳，隋家隄畔錦帆风。","门外白云何处雨，一條清澗遶溪流。"]', '诗', 'shi', '', NULL, '句 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca5beaf9-2be9-4d66-8553-cc64395e1122', '句', '句', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["巖溜噴空晴似雨，林蘿礙日夏多寒。"]', '["巖溜噴空晴似雨，林蘿礙日夏多寒。"]', '诗', 'shi', '', NULL, '句 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c0fd958-281c-489c-9c9a-58fafb07acc7', '句', '句', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["庾樓宴罷三更月，宏閣談時一座風。"]', '["庾楼宴罷三更月，宏閣談时一座风。"]', '诗', 'shi', '', NULL, '句 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28c1bdf1-9bcb-4a48-966b-36801722bacb', '過友人故居', '過友人故居', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["隄草裊空垂露眼，渚浦穿浪湊煙芽。","晴樓談罷山橫黛，夜局碁酣燭墜花。"]', '["隄草裊空垂露眼，渚浦穿浪湊煙芽。","晴楼談罷山橫黛，夜局碁酣燭墜花。"]', '诗', 'shi', '', NULL, '過友人故居 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('949526b9-964c-474c-ae5e-8ad2f48e1956', '句', '句', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["雪中放馬朝尋跡，雲外聞鴻夜射聲。","龍鱗柳弱垂朝露，麈尾松高揮夜風。","猿隔亂雲啼暮嶺，鴈和微雨下寒湖。","夜渡酒酣千頃月，晝樓碁罷一窗山。"]', '["雪中放马朝尋跡，云外闻鴻夜射声。","龙鱗柳弱垂朝露，麈尾松高揮夜风。","猿隔亂云啼暮嶺，鴈和微雨下寒湖。","夜渡酒酣千頃月，晝楼碁罷一窗山。"]', '诗', 'shi', '', NULL, '句 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('197f558f-a056-4baa-b7b3-5e3e8a430609', '句', '句', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["千嶂雪消溪影綠，幾家梅綻酒波清。","風拂亂燈山磬曙，露沾仙杏石壇春。"]', '["千嶂雪消溪影綠，幾家梅綻酒波清。","风拂亂灯山磬曙，露沾仙杏石壇春。"]', '诗', 'shi', '', NULL, '句 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('163aeb63-9e47-4b97-90e9-c702d43ff884', '句', '句', 'ecd87a30-fb52-43a5-9287-b08301151b48', '唐', '["手邊雲起何時雨，筆下波生不待風。"]', '["手邊云起何时雨，笔下波生不待风。"]', '诗', 'shi', '', NULL, '句 神穎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('833981e9-ced0-4dc6-a926-dd5e842b9809', '句', '句', 'a0f59752-3d86-4c3c-b98d-73490e58fac8', '唐', '["渭水橋邊春已渡，灞陵原上雨初晴。","清冷池裏冰初合，紅粉樓中月未圓。","可惜韶年三日暮，風光由繞碧燕觴。","晚日半銜西苑樹，晴雲直卷上天風。","離筵風日三晡晚，歸路雲霞一道開。"]', '["渭水橋邊春已渡，灞陵原上雨初晴。","清冷池裏冰初合，紅粉楼中月未圓。","可惜韶年三日暮，风光由繞碧燕觴。","晚日半銜西苑樹，晴云直卷上天风。","離筵风日三晡晚，归路云霞一道开。"]', '诗', 'shi', '', NULL, '句 惠文太子 shi');
